INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C1','soc',6,2,'u2',1,'시장과 시장경제 — 시장은 물건이나 서비스의 거래가 이루어지는 곳(장소와 상관없이 온라인 쇼핑도 시장), 가계는 살림을 꾸려 가는 생활 공동체, 기업은 이윤을 목적으로 생산·판매하는 조직(이윤 = 수입 − 비용) · 가격은 사람들이 필요로 하는 양과 기업이 제공하는 양을 함께 견주어 정해지고, 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식이 시장경제 — 자유로운 경쟁으로 더 좋은 품질의 물건을 살 수 있음',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C2','soc',6,2,'u2',2,'가계와 기업의 역할과 관계 — 가계는 기업의 생산 활동에 참여해 소득을 얻고 그 소득으로 소비하며 적은 비용으로 가장 큰 만족을 얻는 합리적 선택(기준을 정해 비교)을 하려 하고, 기업은 일자리를 제공하고 물건·서비스를 생산·판매해 이윤을 얻으며 급여 지급·연구·세금 납부를 함 · 가계와 기업은 시장에서 만나 서로 도움을 주고받아 어느 한쪽이 역할을 못하면 다른 쪽도 어려워짐 · 기업의 성장 노력은 품질 좋고 값싼 상품·일자리·나라 경제 발전으로 이어짐',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C3','soc',6,2,'u2',3,'근로자의 권리 보호 — 가계는 노동력을 제공하는 근로자로서 경제활동에 참여하고, 휴가·휴식 같은 권리가 지켜지지 않으면 근로자·기업·소비자 모두 어려워짐 · 근로자는 단체를 만들거나 가입하고, 근로 조건을 기업과 협의하고, 함께 단체로 행동할 수 있으며, 나라는 법과 제도(최저 임금 제도·육아 휴직 제도 등)로 이를 보호 — 노동력은 경제활동에서 중요하고 근로자와 기업은 서로 의존하기 때문',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C4','soc',6,2,'u2',4,'기업의 자유와 사회적 책임 — 헌법이 보장하는 기업의 자유로 기업을 세워 자유롭게 경쟁하고 무엇을 얼마나 생산할지 합리적으로 결정하며, 새 제품·일자리·나라 경제 발전으로 이어짐 · 지나친 경쟁은 환경 오염·담합(약속해 가격 올리기)·잘못된 정보·사업 방해를 낳으므로 정부가 바로잡고, 기업은 사회에 큰 영향을 미치므로 환경·사회·투명 경영 같은 사회적 책임을 다해야 함',ARRAY['6사 경제 — 우리나라 시장경제의 특징(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C5','soc',6,2,'u2',5,'경제성장의 뜻과 우리나라의 경제성장 과정 — 경제성장은 국가 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것(1인당 국민 총소득 = 국민이 일정 기간 생산 활동으로 받은 소득의 합 ÷ 인구수) · 일제의 식민 통치와 6·25 전쟁으로 폐허가 된 뒤 가계·기업·정부가 함께 노력해 1960년대 경공업 제품 수출 → 1970년대 중화학 공업 발달 → 1988년 서울 올림픽 대회 → 반도체·자동차 등 첨단 산업과 문화 콘텐츠로 빠르게 성장(한강의 기적)',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C6','soc',6,2,'u2',5,'경제성장이 우리 생활에 미친 영향 — 첨단 기술 발전으로 생산 속도·생산량이 늘고 생활이 편리해짐, 새 일자리와 소득 증가로 생활이 풍족해져 문화 산업(콘텐츠 산업)이 발달하고 다시 경제를 키움, 교육의 질이 높아지고 수준 높은 의료 혜택으로 기대 수명이 늘어남 — 삶의 질이 높아짐',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C7','soc',6,2,'u2',7,'빠른 경제성장으로 생긴 문제 — 무분별한 개발·오염 물질·쓰레기 증가로 환경 문제, 소득 차이가 커지는 빈부 격차(상대적 빈곤율), 필요보다 많이 쓰는 과소비와 자원 낭비, 임금·복지를 둘러싼 근로자와 기업의 노사 갈등이 생김 — 그대로 두면 갈등·빚·자원 부족으로 경제성장도 어려워짐',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C8','soc',6,2,'u2',7,'경제성장 문제의 해결과 함께하는 노력 — 경제가 지속적으로 발전하려면 문제를 해결해야 함 · 해결 방안은 평가 기준(실천할 수 있나·효과가 큰가·비용이 적게 드나 등)을 세워 점수를 매겨 견주고 실천 계획을 세움, 기준이 바뀌면 고르는 방안도 바뀜 · 정부는 제도·정책, 기업과 근로자는 소통, 시민 단체·개인도 노력 · 공유지의 비극(함께 쓰는 자원을 자기 이익만 생각해 쓰면 공동체 전체가 피해)을 막으려면 규칙과 공동의 이익을 생각하는 태도가 함께 필요',ARRAY['6사 경제 — 경제성장과 우리 생활(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C9','soc',6,2,'u2',9,'무역의 뜻과 무역이 이루어지는 까닭 — 무역은 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일, 사 오면 수입·팔면 수출(같은 거래도 어느 나라에서 보느냐에 따라 수입이자 수출), 고려 벽란도에서도 무역이 있었고 오늘날 드라마·예능 같은 서비스도 수출 · 나라마다 자연환경·자원·자본·기술이 달라 효율적으로 생산하는 것이 다르므로, 잘 만드는 것은 수출하고 구하기 어렵거나 더 좋고 값싼 것은 수입하면 두 나라 모두 이익(흑연 수입 → 배터리 수출)',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C10','soc',6,2,'u2',11,'무역이 이루어지는 다양한 모습 — 우리나라는 원유·천연가스·석탄 같은 천연자원을 주로 수입하고 발달한 기술로 반도체·자동차·석유 제품·무선 통신 기기를 만들어 수출(원유 ≠ 석유 제품) · 넓은 땅과 알맞은 기후의 나라는 농산물(쌀 등), 자원이 풍부한 나라는 자원(원유 등), 기술이 뛰어난 나라는 첨단 제품(백신·로봇)·문화 상품을 수출하고, 싱가포르처럼 항로 길목의 지리적 위치를 활용하기도 함 · 박람회에서 상품을 알리고 거래함',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C11','soc',6,2,'u2',12,'무역을 통한 상호 의존과 경쟁 — 여러 나라는 물자·기술을 주고받으며 서로 의존(여러 나라 부품으로 스마트폰, 광물 탐사 기술 협력)하고 첨단 기술 개발·다른 나라 시설 건설·더 나은 무역 환경(자동화 항만)을 두고 경쟁 · 수출이 늘면 산업 성장·일자리·소득 증가, 수입이 늘면 생활은 편리해지나 국내 기업이 어려워질 수 있어 관세(수입품에 매기는 세금)·수입 제한으로 국내 산업을 보호하기도 함 · 기업은 노동력·시장·관세 조건이 유리한 나라에서 생산하기도 하며, 값싸고 다양한 제품·일자리를 주지만 정당한 임금·환경 문제도 살펴야 함',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-2-u2-C12','soc',6,2,'u2',12,'기업 운영 계획 세우기 — 기업의 대표가 되어 대표 상품(물건이나 서비스)과 특징을 정하고, 상품이 필요할 만한 나라를 조사해 주요 수출국을 고르며, 사회적 책임을 다하는 목표와 근로자의 권리를 보호하는 노력(대화의 시간·성과급·휴가 보장)을 담아 기업 소개 잡지로 나타냄',ARRAY['6사 경제 — 무역과 세계 여러 나라의 상호 의존·경쟁(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X01','soc',6,'u2',ARRAY['SO6-2-u2-C1']::text[],'시장은 물건을 사고파는 건물이 있는 곳만이라고 여겨 온라인 쇼핑·중고 거래 같은 곳은 시장이 아니라고 여긴다','거래가 이루어지면 장소와 상관없이 시장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X02','soc',6,'u2',ARRAY['SO6-2-u2-C1']::text[],'가격이 한쪽(사려는 양이나 내놓은 양 하나, 또는 한 기업의 뜻)만으로 정해진다고 여긴다','사려는 양과 내놓은 양을 함께 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X03','soc',6,'u2',ARRAY['SO6-2-u2-C1','SO6-2-u2-C2']::text[],'가계와 기업이 하는 일·얻는 것을 바꾸어 안다(가계가 이윤을, 기업이 소득을 얻는다 등)','가계 → 소득·소비 · 기업 → 생산·이윤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X04','soc',6,'u2',ARRAY['SO6-2-u2-C2']::text[],'가계와 기업이 서로 상관없이 따로 경제활동을 하거나, 한쪽이 역할을 못해도 다른 쪽은 괜찮다고 여긴다','고리 하나가 끊기면 흐름 전체가 멈춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X05','soc',6,'u2',ARRAY['SO6-2-u2-C2']::text[],'합리적 선택을 가장 비싼(또는 가장 싼) 것 고르기나 남 따라 하기로 여기고, 기준을 정해 비교하지 않는다','우리 가족의 기준 몇 가지로 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X06','soc',6,'u2',ARRAY['SO6-2-u2-C3']::text[],'근로자의 권리는 기업이 알아서 지켜 주므로 법과 제도가 필요 없다거나, 근로자는 기업과 협의하거나 단체로 행동할 수 없다고 여긴다','혼자 낸 목소리 vs 법이 보장한 권리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X07','soc',6,'u2',ARRAY['SO6-2-u2-C3','SO6-2-u2-C4','SO6-2-u2-C11']::text[],'근로자와 기업, 기업과 사회, 나라와 나라처럼 서로 의존하는 관계를 한쪽만의 일로 여긴다','한쪽이 어려우면 다른 쪽은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X08','soc',6,'u2',ARRAY['SO6-2-u2-C4']::text[],'기업의 자유를 무엇이든 해도 되는 것(담합·거짓 광고·사업 방해·환경 오염도 자유)으로 여겨 사회적 책임을 놓친다','돛(자유)과 키(책임)를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X09','soc',6,'u2',ARRAY['SO6-2-u2-C4']::text[],'기업의 사회적 책임 활동의 갈래(환경·사회·투명 경영)나 정부의 바로잡기 노력을 헷갈린다','환경 — 에너지·폐기물 · 사회 — 인권·지역 · 투명 경영 — 공정·윤리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X10','soc',6,'u2',ARRAY['SO6-2-u2-C5']::text[],'경제성장을 인구가 늘어나는 것이나 한 기업의 이윤이 느는 것으로 여기거나, 1인당 국민 총소득의 뜻을 헷갈린다','나라 전체의 생산·소득 → 경제 규모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X11','soc',6,'u2',ARRAY['SO6-2-u2-C5']::text[],'우리나라 경제성장 과정의 차례(경공업 → 중화학 공업 → 서울 올림픽 → 첨단·문화 산업)나 출발 조건(폐허·자원 부족)을 헷갈린다','가벼운 물건 → 무거운 공업 → 첨단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X12','soc',6,'u2',ARRAY['SO6-2-u2-C5','SO6-2-u2-C6','SO6-2-u2-C7']::text[],'경제성장의 한쪽 영향만 보거나(좋은 점만·문제만), 성장이 누군가 혼자의 노력으로 저절로 이루어졌다고 여긴다','좋아진 모습과 경고등을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X13','soc',6,'u2',ARRAY['SO6-2-u2-C6']::text[],'경제성장이 생활에 준 영향의 갈래(첨단 기술·문화 산업·교육·의료)를 바꾸어 짝짓는다','기대 수명 → 의료 · 콘텐츠 → 문화 산업') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X14','soc',6,'u2',ARRAY['SO6-2-u2-C7']::text[],'빠른 경제성장으로 생긴 문제의 갈래(환경·빈부 격차·과소비와 자원 낭비·노사 갈등)를 헷갈린다','무엇이 지나쳤나? 개발·소득 차이·씀씀이·임금') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X15','soc',6,'u2',ARRAY['SO6-2-u2-C8']::text[],'해결 방안을 평가 기준 없이 느낌·먼저 낸 순서로 고르거나, 문제 해결을 한 주체(정부만·개인만)의 일로 여긴다','기준 → 점수 → 견주기 · 정부·기업·근로자·시민') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X16','soc',6,'u2',ARRAY['SO6-2-u2-C8']::text[],'공유지의 비극을 모두가 아껴 써서 생기는 일로 알거나, 규칙만 있으면 태도는 필요 없다고 여긴다','함께 쓰는 자원을 나만 생각하며 쓰면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X17','soc',6,'u2',ARRAY['SO6-2-u2-C9']::text[],'수입과 수출을 바꾸어 알거나, 같은 거래도 어느 나라에서 보느냐에 따라 수입·수출이 갈린다는 점을 놓친다','사 오면 수입 · 팔면 수출 — 누구 쪽에서?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X18','soc',6,'u2',ARRAY['SO6-2-u2-C9','SO6-2-u2-C10']::text[],'무역은 물건이 모자랄 때만 하거나 손에 잡히는 물건만 사고판다고 여겨, 나라마다 조건이 달라 잘 만드는 것을 바꾸어 서로 이익을 얻는 까닭을 놓친다','자연환경·자원·자본·기술의 차이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X19','soc',6,'u2',ARRAY['SO6-2-u2-C10']::text[],'나라의 조건과 무역의 모습을 맞지 않게 짝짓는다(우리나라가 원유를 수출한다, 원유와 석유 제품을 같은 것으로 안다 등)','우리나라 — 자원 수입 → 기술로 제품 수출') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X20','soc',6,'u2',ARRAY['SO6-2-u2-C11']::text[],'무역에서의 상호 의존과 경쟁을 헷갈리거나, 관세·수입 제한·해외 생산의 한쪽 영향만 본다','함께 만들기 = 의존 · 먼저 차지하기 = 경쟁') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-2-u2-X21','soc',6,'u2',ARRAY['SO6-2-u2-C12']::text[],'기업 운영 계획에서 이윤만 생각하고 수출국 조사·사회적 책임·근로자를 위한 노력을 빠뜨린다','상품 · 수출국 · 목표 · 노력 넷 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#1','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'mc','auto','물건이나 서비스의 거래가 이루어지는 곳을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"물건이나 서비스의 거래가 이루어지는 곳을 무엇이라고 하나요?","options":[{"t":"시장","correct":true},{"t":"가계","mis":"SO6-2-u2-X03"},{"t":"기업","mis":"SO6-2-u2-X03"},{"t":"이윤","mis":"SO6-2-u2-X03"}],"explanation":["거래가 이루어지는 곳이 시장이에요.","전통 시장·대형 할인점·문구점이 모두 시장이에요.","온라인 쇼핑도 시장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#2','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'mc','auto','시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직은 무엇인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X01']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"시장에서 이윤을 목적으로 물건이나 서비스를 생산하거나 판매하는 조직은 무엇인가요?","options":[{"t":"기업","correct":true},{"t":"가계","mis":"SO6-2-u2-X03"},{"t":"시장","mis":"SO6-2-u2-X01"},{"t":"서비스","mis":"SO6-2-u2-X03"}],"explanation":["기업은 이윤을 얻으려고 생산하고 판매해요.","이윤은 수입에서 비용을 뺀 금액이에요.","살림을 꾸려 가는 쪽은 가계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#3','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'ox','auto','온라인 쇼핑몰에서 중고 물품을 사고파는 것도 시장에서 이루어지는 거래예요.',ARRAY['SO6-2-u2-X01']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"ox","stem":"온라인 쇼핑몰에서 중고 물품을 사고파는 것도 시장에서 이루어지는 거래예요.","answer":"O","reason_options":[{"t":"장소와 상관없이 물건이나 서비스의 거래가 이루어지는 곳은 모두 시장이기 때문에","correct":true},{"t":"시장은 물건을 사고파는 건물이 있어야만 하기 때문에","mis":"SO6-2-u2-X01"}],"mis":"SO6-2-u2-X01","explanation":["시장을 정하는 것은 장소가 아니라 거래예요.","온라인에서도 거래가 이루어져요.","그래서 온라인 쇼핑몰도 시장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#4','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',1,'sa','auto','시장에서 경제활동을 함께하며 살림을 꾸려 가는 생활 공동체를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"sa","stem":"시장에서 경제활동을 함께하며 살림을 꾸려 가는 생활 공동체를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["가계"],"explanation":["함께 살림을 꾸려 가는 공동체예요.","우리 가족도 하나의 가계예요.","가계는 시장에서 물건을 사요."],"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#5','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','사과 가게 수첩에서 ㉮처럼 사려는 사과만 늘고 시장에 나온 사과는 그대로라면 사과 가격은 어떻게 될까요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"사과 가게 수첩에서 ㉮처럼 사려는 사과만 늘고 시장에 나온 사과는 그대로라면 사과 가격은 어떻게 될까요?","options":[{"t":"지난주보다 비싸진다","correct":true},{"t":"지난주보다 싸진다","mis":"SO6-2-u2-X02"},{"t":"지난주와 같다","mis":"SO6-2-u2-X02"},{"t":"가격이 사라진다","mis":"SO6-2-u2-X02"}],"explanation":["사려는 양은 늘고 나온 양은 그대로예요.","사과를 사려는 사람끼리 경쟁해요.","그래서 가격이 비싸져요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#6','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','사과 가게 수첩에서 ㉰처럼 사려는 사과와 시장에 나온 사과가 똑같이 한 상자씩 늘면 가격은 어떻게 될까요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"사과 가게 수첩에서 ㉰처럼 사려는 사과와 시장에 나온 사과가 똑같이 한 상자씩 늘면 가격은 어떻게 될까요?","options":[{"t":"지난주와 같다","correct":true},{"t":"지난주보다 비싸진다","mis":"SO6-2-u2-X02"},{"t":"지난주보다 싸진다","mis":"SO6-2-u2-X02"},{"t":"알 수 없다","mis":"SO6-2-u2-X02"}],"explanation":["두 쪽이 똑같이 늘었어요.","두 양을 견주면 달라진 것이 없어요.","그래서 가격은 지난주와 같아요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#7','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','시장경제의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X04','SO6-2-u2-X03']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"시장경제의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식","correct":true},{"t":"기업 한 곳이 정한 가격대로만 물건을 사는 방식","mis":"SO6-2-u2-X02"},{"t":"가계와 기업이 만나지 않고 저마다 만들어 쓰는 방식","mis":"SO6-2-u2-X04"},{"t":"가계만 시장에서 경제활동을 하는 방식","mis":"SO6-2-u2-X03"}],"explanation":["가계와 기업이 시장에서 만나요.","자유롭게 경쟁하며 경제활동을 해요.","이 방식이 시장경제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#8','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'mc','auto','시장에서 이루어지는 자유로운 경쟁의 모습이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"시장에서 이루어지는 자유로운 경쟁의 모습이 아닌 것은 어느 것인가요?","options":[{"t":"한 기업이 정한 가격을 모두가 그대로 따른다","correct":true},{"t":"일자리를 얻으려고 다른 사람들과 경쟁한다","mis":"SO6-2-u2-X02"},{"t":"원하는 물건을 사려고 다른 사람들과 경쟁한다","mis":"SO6-2-u2-X02"},{"t":"기업이 더 좋은 물건을 만들려고 다른 기업과 경쟁한다","mis":"SO6-2-u2-X02"}],"explanation":["사람들은 일자리와 물건을 두고 경쟁해요.","기업은 더 팔고 더 좋게 만들려고 경쟁해요.","한 기업이 가격을 정하면 자유로운 경쟁이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#9','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',2,'ox','auto','시장에서 상품의 가격은 기업이 시장에 내놓은 양 하나만으로 정해져요.',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"ox","stem":"시장에서 상품의 가격은 기업이 시장에 내놓은 양 하나만으로 정해져요.","answer":"X","reason_options":[{"t":"사람들이 필요로 하는 양과 기업이 제공하는 양을 함께 견주어 정해지기 때문에","correct":true},{"t":"파는 쪽이 원하는 대로 가격을 정하기 때문에","mis":"SO6-2-u2-X02"}],"mis":"SO6-2-u2-X02","explanation":["가격은 두 가지 양에 따라 정해져요.","사려는 양과 내놓은 양이에요.","한쪽만 봐서는 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_basic#10','soc',6,2,'u2','L01','g6_2_soc_u2_L01_basic','lesson_basic','SO6-2-u2-C1',3,'error','auto','사과 가게 수첩을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"error","stem":"사과 가게 수첩을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「사려는 사람이 늘면 가격은 언제나 비싸져.」","correct":true,"mis_target":"SO6-2-u2-X02"},{"t":"민서 — 「㉯는 나온 사과가 많아져서 가격이 싸질 거야.」","mis":"SO6-2-u2-X02"},{"t":"태윤 — 「두 쪽을 함께 봐야 가격이 어떻게 될지 알 수 있어.」","mis":"SO6-2-u2-X02"}],"explanation":["㉰를 보면 사려는 사과가 늘어도 가격이 같아요.","나온 사과도 함께 늘었기 때문이에요.","가격은 두 쪽을 함께 견주어 정해져요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#1','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',2,'sa','auto','기업이 물건을 팔아 얻은 수입에서 그것을 생산하는 데 든 비용을 뺀 금액을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"sa","stem":"기업이 물건을 팔아 얻은 수입에서 그것을 생산하는 데 든 비용을 뺀 금액을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["이윤"],"explanation":["수입 − 비용 = 이윤이에요.","기업은 이윤을 목적으로 해요.","가계가 얻는 것은 소득이에요."],"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#2','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',2,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"시장","r":"물건이나 서비스의 거래가 이루어지는 곳"},{"l":"가계","r":"함께 살림을 꾸려 가는 생활 공동체"},{"l":"기업","r":"이윤을 목적으로 생산·판매하는 조직"},{"l":"서비스","r":"사람들에게 즐거움이나 편리함을 주는 활동"}],"mis":"SO6-2-u2-X03","explanation":["시장은 거래가 이루어지는 곳이에요.","가계는 살림, 기업은 이윤이에요.","서비스는 손에 잡히지 않는 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#3','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','사과 가게 수첩의 ㉯에서 사과 가격이 싸지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"사과 가게 수첩의 ㉯에서 사과 가격이 싸지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사려는 양은 그대로인데 시장에 나온 사과가 많아져서 팔려는 쪽끼리 경쟁하기 때문에","correct":true},{"t":"사과를 사려는 사람이 많아졌기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과 가게가 가격을 마음대로 정했기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과를 사려는 사람과 나온 사과가 똑같이 늘었기 때문에","mis":"SO6-2-u2-X02"}],"explanation":["㉯는 나온 사과만 늘었어요.","팔려는 쪽이 사려는 쪽보다 많아요.","그래서 가격이 싸져요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#4','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','「사과 가격이 지난주와 같다」는 것만 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"「사과 가격이 지난주와 같다」는 것만 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사려는 양과 나온 양이 모두 그대로였을 수도, 똑같이 늘거나 줄었을 수도 있다","correct":true},{"t":"사과를 사려는 사람이 한 명도 늘지 않았다","mis":"SO6-2-u2-X02"},{"t":"시장에 나온 사과는 지난주와 꼭 같다","mis":"SO6-2-u2-X02"},{"t":"가격은 처음부터 정해져 있어 바뀌지 않는다","mis":"SO6-2-u2-X02"}],"explanation":["가격이 같다는 것은 두 쪽의 견줌이 같다는 뜻이에요.","두 쪽이 함께 늘었을 수도 있어요.","㉰가 그런 경우예요."],"asset":{"type":"passage","lines":["지난주 — 사려는 사과 3상자 · 시장에 나온 사과 3상자","㉮ 이번 주 — 사려는 사과 5상자 · 시장에 나온 사과 3상자","㉯ 이번 주 — 사려는 사과 3상자 · 시장에 나온 사과 5상자","㉰ 이번 주 — 사려는 사과 4상자 · 시장에 나온 사과 4상자"],"title":"사과 가게 수첩(금액은 적지 않음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#5','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'ox','auto','기업들이 자유롭게 경쟁하면 소비자는 더 좋은 품질의 물건을 고를 수 있어요.',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"ox","stem":"기업들이 자유롭게 경쟁하면 소비자는 더 좋은 품질의 물건을 고를 수 있어요.","answer":"O","reason_options":[{"t":"기업들이 다른 기업보다 더 좋은 물건을 만들려고 노력하기 때문에","correct":true},{"t":"경쟁하면 기업이 하나만 남아 고를 필요가 없어지기 때문에","mis":"SO6-2-u2-X02"}],"mis":"SO6-2-u2-X02","explanation":["기업은 더 많이 팔려고 경쟁해요.","그래서 더 좋은 물건을 만들려고 해요.","소비자는 우수한 물건을 살 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#6','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'mc','auto','우리나라 경제활동의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X04']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"mc","stem":"우리나라 경제활동의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"가계와 기업이 시장에서 만나 자유롭게 경쟁하면서 경제활동을 한다","correct":true},{"t":"나라가 모든 물건의 가격과 생산량을 정한다","mis":"SO6-2-u2-X02"},{"t":"가계는 시장에 가지 않고 필요한 물건을 모두 집에서 만든다","mis":"SO6-2-u2-X04"},{"t":"기업끼리는 경쟁하지 않기로 약속한다","mis":"SO6-2-u2-X02"}],"explanation":["우리나라는 시장경제의 특징을 따라요.","가계와 기업이 시장에서 만나요.","자유롭게 경쟁하며 경제활동을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#7','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',3,'error','auto','시장을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X01']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"error","stem":"시장을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「건물이 없으니 온라인 쇼핑은 시장이 아니야.」","correct":true,"mis_target":"SO6-2-u2-X01"},{"t":"도윤 — 「문구점도 연필을 사고파니까 시장이야.」","mis":"SO6-2-u2-X01"},{"t":"세아 — 「전통 시장과 대형 할인점도 시장이야.」","mis":"SO6-2-u2-X01"}],"explanation":["시장은 거래가 이루어지는 곳이에요.","건물이 있든 없든 상관없어요.","온라인 쇼핑도 시장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#8','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'mc','auto','어느 날 사과 농장에 우박이 내려 시장에 나온 사과가 크게 줄었어요. 사려는 사람의 수는 그대로일 때 생길 일과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"mc","stem":"어느 날 사과 농장에 우박이 내려 시장에 나온 사과가 크게 줄었어요. 사려는 사람의 수는 그대로일 때 생길 일과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사과 가격이 비싸진다 — 사려는 양에 비해 나온 사과가 적어 사려는 쪽끼리 경쟁하기 때문에","correct":true},{"t":"사과 가격이 싸진다 — 사과가 적으면 팔기 어렵기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과 가격이 그대로다 — 사려는 사람의 수가 그대로이기 때문에","mis":"SO6-2-u2-X02"},{"t":"사과 가격이 비싸진다 — 농장 한 곳이 가격을 정하기 때문에","mis":"SO6-2-u2-X02"}],"explanation":["나온 사과가 줄었어요.","사려는 양은 그대로예요.","사려는 양이 더 많아지니 가격이 올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#9','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'mc','auto','시장경제에서 가격이 하는 역할을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"mc","stem":"시장경제에서 가격이 하는 역할을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"사려는 양과 내놓은 양의 차이를 보여 주어 가계와 기업이 무엇을 얼마나 사고 만들지 정하게 돕는다","correct":true},{"t":"기업이 원하는 이윤만큼 미리 정해 둔 숫자이다","mis":"SO6-2-u2-X02"},{"t":"나라가 정해 주어 해마다 똑같이 유지된다","mis":"SO6-2-u2-X02"},{"t":"사려는 사람의 수만 알려 준다","mis":"SO6-2-u2-X02"}],"explanation":["가격은 두 쪽의 양을 견주어 정해져요.","가격이 오르면 기업은 더 만들려고 해요.","가계는 가격을 보고 살지 말지 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L01_challenge#10','soc',6,2,'u2','L01','g6_2_soc_u2_L01_challenge','lesson_challenge','SO6-2-u2-C1',4,'essay','teacher','시장경제가 무엇인지 쓰고, 시장에서 이루어지는 자유로운 경쟁이 우리 생활에 주는 도움을 기업과 소비자의 쪽에서 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"essay","stem":"시장경제가 무엇인지 쓰고, 시장에서 이루어지는 자유로운 경쟁이 우리 생활에 주는 도움을 기업과 소비자의 쪽에서 하나씩 쓰세요.","answer_guide":{"answer":"예: 시장경제는 시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식이다. 기업은 다른 기업보다 더 많이 팔려고 더 좋은 물건을 만들고 새로운 물건을 개발하려고 노력한다. 그래서 소비자는 품질이 더 좋은 물건을 여러 가지 가운데 골라 살 수 있다.","scoring_points":["시장경제의 뜻을 바르게 썼는가","기업 쪽의 경쟁 모습을 썼는가","소비자가 얻는 도움을 썼는가"]},"explanation":["가계와 기업이 자유롭게 경쟁해요.","기업은 더 좋은 물건을 만들어요.","소비자는 더 좋은 물건을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#1','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'mc','auto','가계가 기업의 생산 활동에 참여하고 그 대가로 얻는 것은 무엇인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"가계가 기업의 생산 활동에 참여하고 그 대가로 얻는 것은 무엇인가요?","options":[{"t":"소득","correct":true},{"t":"이윤","mis":"SO6-2-u2-X03"},{"t":"세금","mis":"SO6-2-u2-X03"},{"t":"비용","mis":"SO6-2-u2-X03"}],"explanation":["가계는 기업에서 일해요.","그 대가로 소득을 얻어요.","이윤은 기업이 얻는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#2','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'mc','auto','기업이 하는 일이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"기업이 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"함께 살림을 꾸려 가며 저축을 의논한다","correct":true},{"t":"근로자를 고용하고 급여를 준다","mis":"SO6-2-u2-X03"},{"t":"더 좋은 물건을 만들려고 연구한다","mis":"SO6-2-u2-X03"},{"t":"판매로 얻은 수익에 대해 나라에 세금을 낸다","mis":"SO6-2-u2-X03"}],"explanation":["기업은 생산·고용·연구·세금 납부를 해요.","살림을 꾸리는 것은 가계예요.","저축 의논도 가계의 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#3','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'ox','auto','가계는 소득을 생각하여 적은 비용으로 가장 큰 만족을 얻는 소비를 하려고 노력해요.',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"ox","stem":"가계는 소득을 생각하여 적은 비용으로 가장 큰 만족을 얻는 소비를 하려고 노력해요.","answer":"O","reason_options":[{"t":"정해진 소득 안에서 꼭 필요한 것을 골라야 하기 때문에","correct":true},{"t":"가계는 소득과 상관없이 마음대로 쓰기 때문에","mis":"SO6-2-u2-X05"}],"mis":"SO6-2-u2-X05","explanation":["소득에는 한계가 있어요.","그래서 따져 보고 골라요.","이것이 합리적 선택이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#4','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',1,'mc','auto','어느 가족의 하루에서 가계가 기업의 생산 활동에 참여하는 모습은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"어느 가족의 하루에서 가계가 기업의 생산 활동에 참여하는 모습은 어느 것인가요?","options":[{"t":"오전 10시 — 엄마와 아빠가 각자 일터에서 일한다","correct":true},{"t":"오후 5시 — 자동차를 살펴본다","mis":"SO6-2-u2-X03"},{"t":"오후 7시 — 저녁을 먹는다","mis":"SO6-2-u2-X03"},{"t":"오후 10시 — 저축을 의논한다","mis":"SO6-2-u2-X03"}],"explanation":["일터에서 일하는 것이 생산 활동 참여예요.","그 대가로 소득을 얻어요.","자동차를 살펴보는 것은 소비를 위한 모습이에요."],"asset":{"type":"passage","lines":["오전 10시 — 엄마와 아빠는 각자 일터에서 일한다.","오후 5시 — 가족이 자동차 판매점에서 자동차를 살펴본다.","오후 7시 — 가족이 모여 저녁을 먹는다.","오후 10시 — 엄마와 아빠가 저축에 관해 의논한다."],"title":"어느 가족의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#5','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'match','auto','가계와 기업이 주고받는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"match","stem":"가계와 기업이 주고받는 것을 알맞게 이으세요.","pairs":[{"l":"가계 → 기업","r":"일손(노동력)"},{"l":"기업 → 가계","r":"급여(소득)"},{"l":"기업 → 시장","r":"물건과 서비스"},{"l":"가계 → 시장","r":"물건값"}],"mis":"SO6-2-u2-X03","explanation":["가계는 일손을 주고 급여를 받아요.","기업은 물건과 서비스를 내놓아요.","가계는 물건값을 내고 소비해요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#6','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','네 고리 가운데 ①이 끊기면 어떤 일이 생길까요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"네 고리 가운데 ①이 끊기면 어떤 일이 생길까요?","options":[{"t":"기업이 생산에 필요한 일손을 얻지 못해 생산이 어려워진다","correct":true},{"t":"기업만 더 많은 이윤을 얻는다","mis":"SO6-2-u2-X04"},{"t":"가계가 소득을 더 많이 얻는다","mis":"SO6-2-u2-X04"},{"t":"다른 고리로 돌아 흐름이 그대로 이어진다","mis":"SO6-2-u2-X04"}],"explanation":["①은 가계가 기업에 일손을 주는 고리예요.","일손이 없으면 생산이 어려워요.","흐름은 끊긴 자리에서 멈춰요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#7','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','자동차 비교표에서 「크기」 기준만 본다면 우리 가족에게 가장 알맞은 자동차는 어느 것인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"자동차 비교표에서 「크기」 기준만 본다면 우리 가족에게 가장 알맞은 자동차는 어느 것인가요?","options":[{"t":"자동차 ②","correct":true},{"t":"자동차 ①","mis":"SO6-2-u2-X05"},{"t":"자동차 ③","mis":"SO6-2-u2-X05"},{"t":"세 자동차가 같다","mis":"SO6-2-u2-X05"}],"explanation":["크기 별은 ① 1개, ② 3개, ③ 2개예요.","별이 많을수록 더 알맞아요.","하지만 기준 하나만 보면 다른 기준을 놓칠 수 있어요."],"asset":{"type":"passage","lines":["우리 가족이 고른 기준 — 연비 · 크기 · 가격","자동차 ① — 연비 ★★★ · 크기 ★ · 가격 ★★★","자동차 ② — 연비 ★★ · 크기 ★★★ · 가격 ★★","자동차 ③ — 연비 ★ · 크기 ★★ · 가격 ★","별이 많을수록 그 기준에서 우리 가족에게 더 알맞다."],"title":"자동차 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#8','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'ox','auto','자동차를 고르는 기준은 가족마다 다를 수 있어서 선택의 결과도 달라질 수 있어요.',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"ox","stem":"자동차를 고르는 기준은 가족마다 다를 수 있어서 선택의 결과도 달라질 수 있어요.","answer":"O","reason_options":[{"t":"가족마다 중요하게 생각하는 것이 다르기 때문에","correct":true},{"t":"합리적 선택의 답은 언제나 하나뿐이기 때문에","mis":"SO6-2-u2-X05"}],"mis":"SO6-2-u2-X05","explanation":["어떤 가족은 연비, 어떤 가족은 크기를 중요하게 여겨요.","기준이 다르면 고르는 것도 달라요.","그래도 기준을 정해 비교하는 것은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#9','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',2,'mc','auto','기업이 생산 시설을 늘리고 낡은 시설을 바꾸었을 때 소비자가 얻는 좋은 점은 어느 것인가요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X03','SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"기업이 생산 시설을 늘리고 낡은 시설을 바꾸었을 때 소비자가 얻는 좋은 점은 어느 것인가요?","options":[{"t":"품질이 좋은 상품을 더 저렴하게 살 수 있다","correct":true},{"t":"물건을 살 수 있는 곳이 사라진다","mis":"SO6-2-u2-X04"},{"t":"물건값을 내지 않아도 된다","mis":"SO6-2-u2-X03"},{"t":"물건을 고를 필요가 없어진다","mis":"SO6-2-u2-X02"}],"explanation":["생산 기술이 좋아지면 품질이 좋아져요.","많이 생산하면 값이 싸져요.","나라 경제가 발전하는 데도 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_basic#10','soc',6,2,'u2','L02','g6_2_soc_u2_L02_basic','lesson_basic','SO6-2-u2-C2',3,'error','auto','가계와 기업의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"error","stem":"가계와 기업의 관계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「기업이 문을 닫아도 가계는 아무 상관이 없어.」","correct":true,"mis_target":"SO6-2-u2-X04"},{"t":"나은 — 「기업이 어려워지면 가계는 소득을 얻기 어려워.」","mis":"SO6-2-u2-X04"},{"t":"시우 — 「가계와 기업은 시장에서 만나 도움을 주고받아.」","mis":"SO6-2-u2-X04"}],"explanation":["기업은 가계에 일자리를 줘요.","기업이 문을 닫으면 가계는 소득을 잃어요.","가계와 기업은 서로 이어져 있어요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#1','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',2,'sa','auto','가계와 기업이 만나 서로 필요한 것을 주고받을 수 있게 해 주는 곳은 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"sa","stem":"가계와 기업이 만나 서로 필요한 것을 주고받을 수 있게 해 주는 곳은 어디인가요? 두 글자로 쓰세요.","answer":["시장"],"explanation":["가계와 기업은 시장에서 만나요.","물건·서비스·일손이 오가요.","시장은 형태가 다양해요."],"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#2','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',2,'mc','auto','어느 가족의 하루에서 가계가 소비를 하려고 준비하는 모습은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"어느 가족의 하루에서 가계가 소비를 하려고 준비하는 모습은 어느 것인가요?","options":[{"t":"오후 5시 — 가족이 자동차 판매점에서 자동차를 살펴본다","correct":true},{"t":"오전 10시 — 각자 일터에서 일한다","mis":"SO6-2-u2-X03"},{"t":"오후 10시 — 저축을 의논한다","mis":"SO6-2-u2-X03"},{"t":"오전 10시 — 기업이 급여를 준다","mis":"SO6-2-u2-X03"}],"explanation":["자동차를 사는 것은 소비예요.","살펴보며 비교하는 것은 소비를 위한 준비예요.","일터에서 일하는 것은 생산 활동 참여예요."],"asset":{"type":"passage","lines":["오전 10시 — 엄마와 아빠는 각자 일터에서 일한다.","오후 5시 — 가족이 자동차 판매점에서 자동차를 살펴본다.","오후 7시 — 가족이 모여 저녁을 먹는다.","오후 10시 — 엄마와 아빠가 저축에 관해 의논한다."],"title":"어느 가족의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#3','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','자동차 비교표에서 ①과 ②의 별 합이 같아요. 이때 우리 가족이 「가격」을 가장 중요하게 여긴다면 고를 자동차와 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"자동차 비교표에서 ①과 ②의 별 합이 같아요. 이때 우리 가족이 「가격」을 가장 중요하게 여긴다면 고를 자동차와 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자동차 ① — 가장 중요한 가격 기준에서 별이 더 많기 때문에","correct":true},{"t":"자동차 ② — 크기 별이 가장 많기 때문에","mis":"SO6-2-u2-X05"},{"t":"자동차 ③ — 별의 합이 가장 적기 때문에","mis":"SO6-2-u2-X05"},{"t":"아무거나 — 합이 같으면 기준은 상관없기 때문에","mis":"SO6-2-u2-X05"}],"explanation":["합이 같으면 더 중요한 기준을 봐요.","가격 별은 ①이 3개, ②가 2개예요.","그래서 ①을 골라요."],"asset":{"type":"passage","lines":["우리 가족이 고른 기준 — 연비 · 크기 · 가격","자동차 ① — 연비 ★★★ · 크기 ★ · 가격 ★★★","자동차 ② — 연비 ★★ · 크기 ★★★ · 가격 ★★","자동차 ③ — 연비 ★ · 크기 ★★ · 가격 ★","별이 많을수록 그 기준에서 우리 가족에게 더 알맞다."],"title":"자동차 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#4','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','네 고리 가운데 ④(기업이 가계에 급여를 준다)가 끊기면 흐름은 어떻게 될까요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"네 고리 가운데 ④(기업이 가계에 급여를 준다)가 끊기면 흐름은 어떻게 될까요?","options":[{"t":"가계가 소득을 얻지 못해 물건을 사지 못하고, 기업도 물건을 팔지 못해 함께 어려워진다","correct":true},{"t":"가계만 어려워지고 기업은 그대로다","mis":"SO6-2-u2-X04"},{"t":"기업만 어려워지고 가계는 그대로다","mis":"SO6-2-u2-X04"},{"t":"흐름이 다른 고리로 돌아 그대로 이어진다","mis":"SO6-2-u2-X04"}],"explanation":["급여가 끊기면 가계의 소득이 없어요.","소득이 없으면 물건을 사지 못해요.","그러면 기업도 이윤을 얻지 못해요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#5','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'ox','auto','기업이 꾸준히 성장하면 일자리가 늘어나 가계에도 도움이 돼요.',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"ox","stem":"기업이 꾸준히 성장하면 일자리가 늘어나 가계에도 도움이 돼요.","answer":"O","reason_options":[{"t":"기업이 커지면 일할 사람이 더 필요해 가계가 소득을 얻을 기회가 늘기 때문에","correct":true},{"t":"기업이 성장하면 일할 사람이 필요 없어지기 때문에","mis":"SO6-2-u2-X04"}],"mis":"SO6-2-u2-X04","explanation":["기업이 커지면 일손이 더 필요해요.","일자리가 늘면 가계의 소득도 늘어요.","기업의 성장은 나라 경제에도 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#6','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'mc','auto','기업이 더 많은 이윤을 얻으려고 하는 노력으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"기업이 더 많은 이윤을 얻으려고 하는 노력으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"근로자에게 약속한 급여를 주지 않는다","correct":true},{"t":"생산 시설에 투자해 생산량을 늘린다","mis":"SO6-2-u2-X03"},{"t":"생산 비용을 줄일 방법을 찾는다","mis":"SO6-2-u2-X03"},{"t":"판매량을 늘릴 방법을 찾는다","mis":"SO6-2-u2-X03"}],"explanation":["기업은 투자·비용 줄이기·판매 늘리기를 해요.","약속한 급여를 주지 않는 것은 바른 노력이 아니에요.","근로자는 기업의 소중한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#7','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',3,'error','auto','합리적 선택을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"error","stem":"합리적 선택을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은우 — 「제일 비싼 자동차가 제일 좋으니까 그걸 사면 돼.」","correct":true,"mis_target":"SO6-2-u2-X05"},{"t":"라희 — 「모아 둔 돈으로 살 수 있는 것 중에서 골라야 해.」","mis":"SO6-2-u2-X05"},{"t":"지안 — 「우리 가족에게 중요한 기준을 정해서 비교해 보자.」","mis":"SO6-2-u2-X05"}],"explanation":["비싼 것이 꼭 알맞은 것은 아니에요.","소득 안에서 기준을 정해 비교해요.","그것이 합리적 선택이에요."],"asset":{"type":"passage","lines":["우리 가족이 고른 기준 — 연비 · 크기 · 가격","자동차 ① — 연비 ★★★ · 크기 ★ · 가격 ★★★","자동차 ② — 연비 ★★ · 크기 ★★★ · 가격 ★★","자동차 ③ — 연비 ★ · 크기 ★★ · 가격 ★","별이 많을수록 그 기준에서 우리 가족에게 더 알맞다."],"title":"자동차 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#8','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'mc','auto','가계와 기업의 관계를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X04']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"mc","stem":"가계와 기업의 관계를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"기업은 가계에 일자리와 물건을 주고, 가계는 일손과 물건값을 주어 서로 없어서는 안 되는 관계이다","correct":true},{"t":"가계는 물건을 만들고 기업은 사서 쓰기만 하는 관계이다","mis":"SO6-2-u2-X03"},{"t":"가계와 기업은 서로 만나지 않는 관계이다","mis":"SO6-2-u2-X04"},{"t":"기업만 가계에 도움을 주는 한쪽의 관계이다","mis":"SO6-2-u2-X04"}],"explanation":["두 쪽은 서로 주고받아요.","한쪽이 멈추면 다른 쪽도 멈춰요.","그래서 서로 꼭 필요한 관계예요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#9','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'mc','auto','어느 지역의 큰 공장이 문을 닫았어요. 그 뒤 그 지역의 식당과 가게 손님도 줄었어요. 이 일을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X02','SO6-2-u2-X05']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"mc","stem":"어느 지역의 큰 공장이 문을 닫았어요. 그 뒤 그 지역의 식당과 가게 손님도 줄었어요. 이 일을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"공장에서 일하던 가계가 소득을 잃어 소비가 줄자, 물건을 팔던 다른 기업들도 어려워졌다","correct":true},{"t":"공장과 식당은 서로 관계가 없어 우연히 함께 일어났다","mis":"SO6-2-u2-X04"},{"t":"식당이 가격을 올려서 생긴 일이다","mis":"SO6-2-u2-X02"},{"t":"가계가 저축을 하지 않아서 생긴 일이다","mis":"SO6-2-u2-X05"}],"explanation":["공장 → 가계의 급여가 끊겼어요.","가계는 소득이 줄어 덜 사요.","그러면 다른 기업도 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L02_challenge#10','soc',6,2,'u2','L02','g6_2_soc_u2_L02_challenge','lesson_challenge','SO6-2-u2-C2',4,'essay','teacher','시장경제에서 가계와 기업이 하는 일을 하나씩 쓰고, 둘 가운데 한쪽이 역할을 제대로 하지 못하면 어떤 일이 생기는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"essay","stem":"시장경제에서 가계와 기업이 하는 일을 하나씩 쓰고, 둘 가운데 한쪽이 역할을 제대로 하지 못하면 어떤 일이 생기는지 쓰세요.","answer_guide":{"answer":"예: 가계는 기업의 생산 활동에 참여해 소득을 얻고, 그 소득으로 기업이 만든 물건이나 서비스를 소비한다. 기업은 가계에 일자리를 주고 물건과 서비스를 생산하고 판매해 이윤을 얻는다. 만약 기업이 역할을 제대로 하지 못하면 가계는 소득을 얻지 못해 필요한 물건을 사기 어려워지고, 기업도 물건을 팔지 못해 함께 어려워진다.","scoring_points":["가계가 하는 일을 바르게 썼는가","기업이 하는 일을 바르게 썼는가","한쪽이 멈추면 다른 쪽도 어려워짐을 썼는가"]},"explanation":["가계 — 일하고 소득을 얻어 소비해요.","기업 — 일자리를 주고 생산해 이윤을 얻어요.","둘은 서로 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#1','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'mc','auto','가계는 기업에 무엇을 제공하는 근로자로서 경제활동에 참여하나요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"가계는 기업에 무엇을 제공하는 근로자로서 경제활동에 참여하나요?","options":[{"t":"노동력","correct":true},{"t":"이윤","mis":"SO6-2-u2-X03"},{"t":"세금","mis":"SO6-2-u2-X03"},{"t":"물건값","mis":"SO6-2-u2-X03"}],"explanation":["근로자는 기업에서 일해요.","일하는 힘이 노동력이에요.","기업은 그 대가로 급여를 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#2','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'mc','auto','우리나라가 근로자의 권리를 보호하려고 마련해 둔 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"우리나라가 근로자의 권리를 보호하려고 마련해 둔 것은 어느 것인가요?","options":[{"t":"법과 제도","correct":true},{"t":"벌금과 광고","mis":"SO6-2-u2-X06"},{"t":"관세와 무역","mis":"SO6-2-u2-X06"},{"t":"이윤과 가격","mis":"SO6-2-u2-X06"}],"explanation":["나라는 법과 제도로 근로자를 보호해요.","근로자는 그 위에서 성실히 일해요.","기업도 목표를 이룰 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#3','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'mc','auto','근로자의 권리를 보호하려고 우리나라가 실시하는 제도는 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"근로자의 권리를 보호하려고 우리나라가 실시하는 제도는 어느 것인가요?","options":[{"t":"최저 임금 제도","correct":true},{"t":"휴가를 줄이는 제도","mis":"SO6-2-u2-X06"},{"t":"휴게실을 닫는 제도","mis":"SO6-2-u2-X06"},{"t":"아파도 출근하게 하는 제도","mis":"SO6-2-u2-X06"}],"explanation":["최저 임금 제도는 임금의 가장 낮은 기준을 정해요.","육아 휴직 제도도 있어요.","모두 근로자를 보호하는 제도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#4','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',1,'ox','auto','근로자는 근로 조건이나 근로 환경에 관해 기업과 협의할 수 있어요.',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"ox","stem":"근로자는 근로 조건이나 근로 환경에 관해 기업과 협의할 수 있어요.","answer":"O","reason_options":[{"t":"법과 제도가 근로자가 기업과 협의할 권리를 보장하기 때문에","correct":true},{"t":"근로 조건은 기업만 정할 수 있기 때문에","mis":"SO6-2-u2-X06"}],"mis":"SO6-2-u2-X06","explanation":["근로자는 기업과 이야기를 나눌 수 있어요.","근무 시간이나 복지를 두고 협의해요.","법이 이 권리를 지켜 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#5','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'match','auto','근로자의 말과 그 말에 담긴 권리를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"match","stem":"근로자의 말과 그 말에 담긴 권리를 알맞게 이으세요.","pairs":[{"l":"근로자 ㉠","r":"근로 조건을 기업과 협의하는 권리"},{"l":"근로자 ㉡","r":"다른 근로자들과 함께 단체로 행동하는 권리"},{"l":"근로자 ㉢","r":"단체를 만들거나 가입하는 권리"}],"mis":"SO6-2-u2-X06","explanation":["㉠은 근무 시간을 회사와 이야기해요.","㉡은 함께 요청하자고 해요.","㉢은 근로자 단체에 가입했어요."],"asset":{"type":"speech","turns":[{"who":"근로자 ㉠","text":"근무 시간을 각자 사정에 맞게 조정할 수 있으면 좋겠어요. 회사와 이야기해 봐요."},{"who":"근로자 ㉡","text":"복지 혜택이 너무 부족해요. 우리 함께 늘려 달라고 요청합시다."},{"who":"근로자 ㉢","text":"더 나은 근로 조건을 만들려고 근로자 단체에 가입했어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#6','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','근로자 조사 기사에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자 조사 기사에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"휴가·휴식 같은 기본적인 권리조차 지켜지지 않는 근로자가 있다","correct":true},{"t":"모든 근로자가 휴가를 마음껏 썼다","mis":"SO6-2-u2-X06"},{"t":"근로자의 권리는 법이 없어도 잘 지켜진다","mis":"SO6-2-u2-X06"},{"t":"휴게실은 근로자의 권리와 관계가 없다","mis":"SO6-2-u2-X06"}],"explanation":["유급 휴가를 쓰지 못한 사람이 많았어요.","아파도 출근한 사람도 있었어요.","기본적인 권리가 지켜지지 않았어요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#7','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','근로자의 권리가 오래도록 지켜지지 않으면 생길 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자의 권리가 오래도록 지켜지지 않으면 생길 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"기업이 더 좋은 물건을 쉽게 만들게 된다","correct":true},{"t":"근로자의 일할 의욕이 낮아진다","mis":"SO6-2-u2-X07"},{"t":"근로자가 행복하게 일하기 힘들어진다","mis":"SO6-2-u2-X07"},{"t":"소비자가 그 기업의 물건을 사지 않으려 한다","mis":"SO6-2-u2-X07"}],"explanation":["일할 의욕이 낮으면 일을 잘하기 어려워요.","그러면 좋은 물건을 만들기도 어려워요.","소비자도 그 기업을 멀리할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#8','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'ox','auto','근로자의 권리는 기업이 알아서 지켜 주므로 법과 제도는 필요하지 않아요.',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"ox","stem":"근로자의 권리는 기업이 알아서 지켜 주므로 법과 제도는 필요하지 않아요.","answer":"X","reason_options":[{"t":"조사 기사처럼 권리가 지켜지지 않는 일이 있어 법과 제도로 보호해야 하기 때문에","correct":true},{"t":"기업은 언제나 근로자의 권리를 먼저 생각하기 때문에","mis":"SO6-2-u2-X06"}],"mis":"SO6-2-u2-X06","explanation":["권리가 지켜지지 않는 근로자도 있어요.","그래서 법과 제도가 필요해요.","법은 근로자의 목소리를 받쳐 줘요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#9','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',2,'mc','auto','근로자의 권리를 보호하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자의 권리를 보호하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"휴식을 보장하지 않는 기업을 칭찬한다","correct":true},{"t":"근로자에게 권리를 지키는 방법을 교육한다","mis":"SO6-2-u2-X06"},{"t":"근로자의 권리를 지키려고 노력하는 기업에 혜택을 준다","mis":"SO6-2-u2-X06"},{"t":"안전하게 일할 수 있는 환경을 마련한다","mis":"SO6-2-u2-X06"}],"explanation":["교육·혜택·안전한 환경은 좋은 방법이에요.","휴식을 보장하지 않는 기업은 바로잡아야 해요.","벌금을 물게 하는 방법도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_basic#10','soc',6,2,'u2','L03','g6_2_soc_u2_L03_basic','lesson_basic','SO6-2-u2-C3',3,'error','auto','근로자의 권리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"error","stem":"근로자의 권리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「근로자는 회사가 정한 대로만 해야 하고 단체를 만들 수 없어.」","correct":true,"mis_target":"SO6-2-u2-X06"},{"t":"유나 — 「근로자는 함께 단체로 행동하며 정당한 권리를 주장할 수 있어.」","mis":"SO6-2-u2-X06"},{"t":"하율 — 「육아 휴직 제도도 근로자를 보호하는 제도야.」","mis":"SO6-2-u2-X06"}],"explanation":["근로자는 단체를 만들거나 가입할 수 있어요.","함께 단체로 행동할 수도 있어요.","법과 제도가 이를 보장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#1','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',2,'sa','auto','휴가 기간에도 급여가 지급되는 휴가를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"sa","stem":"휴가 기간에도 급여가 지급되는 휴가를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["유급 휴가","유급휴가"],"explanation":["「유급」은 급여가 있다는 뜻이에요.","법이 일정 기간 일한 근로자에게 보장해요.","그런데도 못 쓰는 근로자가 있었어요."],"mis":"SO6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#2','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',2,'mc','auto','근로자 ㉡처럼 「우리 함께 요청합시다」라고 말하는 것은 어떤 권리를 누리는 모습인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"근로자 ㉡처럼 「우리 함께 요청합시다」라고 말하는 것은 어떤 권리를 누리는 모습인가요?","options":[{"t":"다른 근로자들과 함께 단체로 행동하는 권리","correct":true},{"t":"혼자서만 몰래 요청하는 권리","mis":"SO6-2-u2-X06"},{"t":"휴가를 스스로 포기하는 권리","mis":"SO6-2-u2-X06"},{"t":"기업을 대신해 가격을 정하는 권리","mis":"SO6-2-u2-X03"}],"explanation":["㉡은 함께 요청하자고 해요.","정당한 권리를 함께 주장하는 모습이에요.","법이 이 권리를 보장해요."],"asset":{"type":"speech","turns":[{"who":"근로자 ㉠","text":"근무 시간을 각자 사정에 맞게 조정할 수 있으면 좋겠어요. 회사와 이야기해 봐요."},{"who":"근로자 ㉡","text":"복지 혜택이 너무 부족해요. 우리 함께 늘려 달라고 요청합시다."},{"who":"근로자 ㉢","text":"더 나은 근로 조건을 만들려고 근로자 단체에 가입했어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#3','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','근로자 한 사람이 혼자 요청할 때보다 법이 보장한 권리가 있을 때 협의가 더 잘 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X07']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"근로자 한 사람이 혼자 요청할 때보다 법이 보장한 권리가 있을 때 협의가 더 잘 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혼자 낸 목소리는 작지만 법이 보장한 권리가 근로자와 기업이 대등하게 마주 앉게 해 주기 때문에","correct":true},{"t":"법이 있으면 근로자의 요청은 무엇이든 받아들여지기 때문에","mis":"SO6-2-u2-X06"},{"t":"법이 있으면 기업이 약해져서 문을 닫기 때문에","mis":"SO6-2-u2-X07"},{"t":"혼자 요청해도 결과는 언제나 같기 때문에","mis":"SO6-2-u2-X06"}],"explanation":["근로자 한 사람은 기업보다 힘이 약해요.","법과 제도가 근로자의 목소리를 받쳐 줘요.","그래서 대등하게 협의할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#4','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','시장경제에서 근로자의 권리를 보호해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"시장경제에서 근로자의 권리를 보호해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근로자의 노동력은 경제활동에서 중요하고, 근로자와 기업은 서로 의존하는 관계이기 때문에","correct":true},{"t":"근로자와 기업은 서로 상관없이 따로 일하기 때문에","mis":"SO6-2-u2-X07"},{"t":"기업은 근로자 없이도 생산할 수 있기 때문에","mis":"SO6-2-u2-X07"},{"t":"근로자는 일을 하지 않아도 되기 때문에","mis":"SO6-2-u2-X06"}],"explanation":["기업이 생산하려면 노동력이 필요해요.","근로자는 기업에서 소득을 얻어요.","서로 기대고 있어서 권리 보호가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#5','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'ox','auto','근로자가 권리를 보호받으면 근로자는 일을 성실히 하고, 기업도 원하는 목표를 이루기 쉬워져요.',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"ox","stem":"근로자가 권리를 보호받으면 근로자는 일을 성실히 하고, 기업도 원하는 목표를 이루기 쉬워져요.","answer":"O","reason_options":[{"t":"근로자가 안심하고 일하면 일할 의욕이 높아져 기업의 생산에도 도움이 되기 때문에","correct":true},{"t":"근로자의 권리를 지키면 기업은 반드시 손해를 보기 때문에","mis":"SO6-2-u2-X07"}],"mis":"SO6-2-u2-X07","explanation":["권리를 보호받으면 의욕이 높아져요.","좋은 물건과 서비스를 만들기 쉬워요.","근로자와 기업 모두에게 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#6','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'mc','auto','유급 휴가를 법에서 보장하는데도 제대로 쓰지 못하는 근로자가 있는 까닭으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"유급 휴가를 법에서 보장하는데도 제대로 쓰지 못하는 근로자가 있는 까닭으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"근로자가 자기 권리를 잘 모르거나, 기업이 권리 보호에 소극적이기 때문에","correct":true},{"t":"유급 휴가는 법에 없는 휴가이기 때문에","mis":"SO6-2-u2-X06"},{"t":"근로자는 휴가가 필요 없기 때문에","mis":"SO6-2-u2-X06"},{"t":"휴가를 쓰면 반드시 일자리를 잃는다고 법에 적혀 있기 때문에","mis":"SO6-2-u2-X06"}],"explanation":["권리를 모르면 누리지 못해요.","기업이 소극적이면 쓰기 어려워요.","그래서 교육과 제도가 함께 필요해요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#7','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',3,'error','auto','근로자 조사 기사를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X06']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"error","stem":"근로자 조사 기사를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「근로자가 힘든 건 근로자만의 일이니 소비자와는 상관없어.」","correct":true,"mis_target":"SO6-2-u2-X07"},{"t":"봄이 — 「근로자가 행복하지 않으면 좋은 물건을 만들기도 어려워.」","mis":"SO6-2-u2-X07"},{"t":"가온 — 「근로자를 위한 휴게실을 쓰게 해야 해.」","mis":"SO6-2-u2-X06"}],"explanation":["근로자·기업·소비자는 이어져 있어요.","근로자가 힘들면 물건의 질도 떨어져요.","소비자도 그 기업을 멀리할 수 있어요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#8','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'mc','auto','어느 회사가 「휴게실을 쓰지 말라」고 했고, 근로자들이 근로자 단체를 통해 회사와 이야기한 끝에 휴게실을 다시 쓰게 되었어요. 이 일에 담긴 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"mc","stem":"어느 회사가 「휴게실을 쓰지 말라」고 했고, 근로자들이 근로자 단체를 통해 회사와 이야기한 끝에 휴게실을 다시 쓰게 되었어요. 이 일에 담긴 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"근로자의 권리는 단체로 행동해야만 지켜지므로 협의는 쓸모가 없다","correct":true},{"t":"휴식은 근로자의 기본적인 권리이다","mis":"SO6-2-u2-X06"},{"t":"근로자는 단체를 통해 기업과 협의할 수 있다","mis":"SO6-2-u2-X06"},{"t":"법과 제도가 근로자의 목소리를 받쳐 준다","mis":"SO6-2-u2-X06"}],"explanation":["근로자는 단체를 통해 협의했어요.","협의로 문제를 풀었어요.","협의도 중요한 권리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#9','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'mc','auto','「최저 임금 제도」가 근로자와 시장경제 모두에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X06','SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"mc","stem":"「최저 임금 제도」가 근로자와 시장경제 모두에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근로자가 생활에 필요한 만큼의 소득을 얻으면 안심하고 일하고 소비할 수 있어 기업에도 도움이 되기 때문에","correct":true},{"t":"기업이 근로자를 더 이상 고용하지 않게 되기 때문에","mis":"SO6-2-u2-X07"},{"t":"근로자가 일하지 않아도 급여를 받기 때문에","mis":"SO6-2-u2-X06"},{"t":"물건값이 모두 같아지기 때문에","mis":"SO6-2-u2-X02"}],"explanation":["최저 임금은 소득의 바닥을 지켜요.","소득이 있으면 소비도 할 수 있어요.","가계와 기업은 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L03_challenge#10','soc',6,2,'u2','L03','g6_2_soc_u2_L03_challenge','lesson_challenge','SO6-2-u2-C3',4,'essay','teacher','근로자의 권리가 지켜지지 않는 상황을 하나 쓰고, 그 상황이 근로자·기업·소비자에게 어떤 영향을 주는지 쓴 뒤, 권리를 보호할 방법을 하나 제안하세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"essay","stem":"근로자의 권리가 지켜지지 않는 상황을 하나 쓰고, 그 상황이 근로자·기업·소비자에게 어떤 영향을 주는지 쓴 뒤, 권리를 보호할 방법을 하나 제안하세요.","answer_guide":{"answer":"예: 몸이 아파도 휴가를 쓰지 못하고 출근해야 하는 근로자가 있다. 근로자는 일할 의욕이 낮아져 행복하게 일하기 어렵고, 기업은 좋은 물건을 만들기 어려워지며, 소비자는 그 기업의 물건을 사지 않으려 할 수 있다. 그래서 근로자에게 권리를 알려 주는 교육을 하고, 휴가를 보장하지 않는 기업에는 벌금을 물게 하면 좋겠다.","scoring_points":["권리가 지켜지지 않는 상황을 썼는가","근로자·기업·소비자에게 주는 영향을 썼는가","알맞은 보호 방법을 제안했는가"]},"explanation":["권리가 무너지면 모두 어려워요.","근로자·기업·소비자는 이어져 있어요.","교육·제도·벌금·혜택을 떠올려요."],"asset":{"type":"passage","lines":["어느 분야 근로자를 조사한 결과 —","· 법이 보장한 유급 휴가를 제대로 쓰지 못했다는 사람이 많았다.","· 몸이 아파도 휴가를 낼 수 없어 출근했다는 사람도 있었다.","· 휴게실을 쓰지 말라는 말을 들었다는 사람도 있었다."],"title":"근로자 조사 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#1','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','우리나라에서 기업이 누리는 경제활동의 자유로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라에서 기업이 누리는 경제활동의 자유로 알맞은 것은 어느 것인가요?","options":[{"t":"기업을 세워 다른 기업과 자유롭게 경쟁할 수 있다","correct":true},{"t":"다른 기업의 사업을 방해할 수 있다","mis":"SO6-2-u2-X08"},{"t":"소비자에게 잘못된 정보를 줄 수 있다","mis":"SO6-2-u2-X08"},{"t":"나라가 정해 준 상품만 만들 수 있다","mis":"SO6-2-u2-X02"}],"explanation":["우리나라는 헌법에서 기업의 자유를 보장해요.","기업을 세우고 자유롭게 경쟁해요.","방해나 거짓 정보는 자유가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#2','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','기업의 경제활동은 사회에 큰 영향을 미치므로 기업이 가져야 할 것은 무엇인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"기업의 경제활동은 사회에 큰 영향을 미치므로 기업이 가져야 할 것은 무엇인가요?","options":[{"t":"사회에 대한 책임감","correct":true},{"t":"이윤만 생각하는 마음","mis":"SO6-2-u2-X08"},{"t":"다른 기업을 이기려는 욕심","mis":"SO6-2-u2-X08"},{"t":"소비자를 속이는 꾀","mis":"SO6-2-u2-X08"}],"explanation":["기업의 활동은 많은 사람에게 영향을 줘요.","그래서 사회적 책임이 필요해요.","책임을 다하면 사회가 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#3','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'ox','auto','기업은 어떤 상품을 얼마나 생산할지 자유롭게 정할 수 있어요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"ox","stem":"기업은 어떤 상품을 얼마나 생산할지 자유롭게 정할 수 있어요.","answer":"O","reason_options":[{"t":"기업은 이윤을 얻으려고 생산할 상품과 양을 합리적으로 결정할 자유가 있기 때문에","correct":true},{"t":"생산할 상품과 양은 소비자가 대신 정해 주기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["기업은 무엇을 얼마나 만들지 정해요.","적은 비용으로 큰 이윤을 얻으려 해요.","이것이 합리적 결정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#4','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',1,'mc','auto','공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓰는 기업이 중요하게 여기는 가치는 어느 것인가요?',ARRAY['SO6-2-u2-X09','SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓰는 기업이 중요하게 여기는 가치는 어느 것인가요?","options":[{"t":"환경","correct":true},{"t":"투명 경영","mis":"SO6-2-u2-X09"},{"t":"사회","mis":"SO6-2-u2-X09"},{"t":"담합","mis":"SO6-2-u2-X08"}],"explanation":["에너지를 효율적으로 쓰는 것은 환경을 위한 노력이에요.","폐기물 관리도 환경이에요.","담합은 가치가 아니라 문제예요."],"asset":{"type":"passage","lines":["환경 — 폐기물을 관리하고 에너지를 효율적으로 쓴다.","사회 — 사람들의 인권을 존중하고 소비자와 지역사회를 살핀다.","투명 경영 — 공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통한다."],"title":"기업이 중요하게 여기는 세 가치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#5','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','기업 소식 다섯 가운데 기업이 사회적 책임을 다한 모습은 어느 것인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"기업 소식 다섯 가운데 기업이 사회적 책임을 다한 모습은 어느 것인가요?","options":[{"t":"㉤","correct":true},{"t":"㉠","mis":"SO6-2-u2-X08"},{"t":"㉡","mis":"SO6-2-u2-X08"},{"t":"㉢","mis":"SO6-2-u2-X08"}],"explanation":["㉤은 친환경 에너지를 써요.","㉠ 담합, ㉡ 오염, ㉢ 거짓 광고예요.","㉣ 사업 방해도 문제예요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#6','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','기업 소식 ㉠처럼 몇몇 회사가 몰래 약속해서 가격을 올리면 누가 가장 피해를 보나요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X02']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"기업 소식 ㉠처럼 몇몇 회사가 몰래 약속해서 가격을 올리면 누가 가장 피해를 보나요?","options":[{"t":"물건을 사는 소비자","correct":true},{"t":"약속한 회사들","mis":"SO6-2-u2-X08"},{"t":"가격을 정하는 나라","mis":"SO6-2-u2-X02"},{"t":"아무도 피해를 보지 않는다","mis":"SO6-2-u2-X08"}],"explanation":["경쟁하지 않고 함께 값을 올렸어요.","소비자는 비싼 값을 낼 수밖에 없어요.","그래서 정부가 이를 바로잡아요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#7','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'match','auto','기업의 노력과 그 노력이 지키려는 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"match","stem":"기업의 노력과 그 노력이 지키려는 가치를 알맞게 이으세요.","pairs":[{"l":"폐기물을 줄이고 재활용한다","r":"환경"},{"l":"지역 주민을 위한 도서관을 짓는다","r":"사회"},{"l":"근로자와 정기적으로 소통한다","r":"투명 경영"}],"mis":"SO6-2-u2-X09","explanation":["폐기물 관리는 환경이에요.","지역사회를 돕는 것은 사회예요.","공정·윤리·소통은 투명 경영이에요."],"asset":{"type":"passage","lines":["환경 — 폐기물을 관리하고 에너지를 효율적으로 쓴다.","사회 — 사람들의 인권을 존중하고 소비자와 지역사회를 살핀다.","투명 경영 — 공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통한다."],"title":"기업이 중요하게 여기는 세 가치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#8','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'ox','auto','기업에 자유가 있으니 다른 기업의 사업을 방해해도 괜찮아요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"ox","stem":"기업에 자유가 있으니 다른 기업의 사업을 방해해도 괜찮아요.","answer":"X","reason_options":[{"t":"자유로운 경쟁은 공정해야 하고, 방해하면 다른 기업과 소비자가 피해를 보기 때문에","correct":true},{"t":"경쟁에서 이기는 것이 가장 중요하기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["기업의 자유에는 책임이 따라요.","방해는 공정한 경쟁이 아니에요.","정부가 이런 일을 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#9','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',2,'mc','auto','기업이 자유롭게 새 제품을 개발하고 생산하면 생기는 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X04']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"기업이 자유롭게 새 제품을 개발하고 생산하면 생기는 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"시장에 다양한 상품이 나오고 일자리가 늘어 나라 경제가 발전한다","correct":true},{"t":"시장에 상품이 하나만 남는다","mis":"SO6-2-u2-X02"},{"t":"일자리가 줄어든다","mis":"SO6-2-u2-X04"},{"t":"소비자가 고를 필요가 없어진다","mis":"SO6-2-u2-X02"}],"explanation":["기업이 자유로우면 성장하려고 노력해요.","다양한 상품과 일자리가 생겨요.","나라 경제가 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_basic#10','soc',6,2,'u2','L04','g6_2_soc_u2_L04_basic','lesson_basic','SO6-2-u2-C4',3,'error','auto','기업의 자유와 책임을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"error","stem":"기업의 자유와 책임을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「기업은 이윤을 얻으면 그만이니까 사회는 생각하지 않아도 돼.」","correct":true,"mis_target":"SO6-2-u2-X08"},{"t":"채아 — 「기업은 자유롭게 경쟁하지만 공정하게 해야 해.」","mis":"SO6-2-u2-X08"},{"t":"윤재 — 「사회적 책임을 다하는 기업이 늘면 사회가 발전해.」","mis":"SO6-2-u2-X08"}],"explanation":["기업의 활동은 사회에 큰 영향을 줘요.","이윤만 좇으면 여러 문제가 생겨요.","자유와 책임을 함께 가져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#1','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',2,'mc','auto','정부가 기업의 경제활동을 지원하는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X08','SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"정부가 기업의 경제활동을 지원하는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"기업이 새로운 기술과 제품을 개발하도록 도와준다","correct":true},{"t":"기업이 만들 상품을 모두 정해 준다","mis":"SO6-2-u2-X02"},{"t":"기업끼리 가격을 함께 올리게 돕는다","mis":"SO6-2-u2-X08"},{"t":"기업이 세금을 내지 않게 한다","mis":"SO6-2-u2-X03"}],"explanation":["정부는 새 기술 개발을 지원해요.","방해되는 제도를 고치기도 해요.","담합은 오히려 바로잡아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#2','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',2,'sa','auto','기업 소식 ㉠·㉡·㉢·㉣ 가운데 환경을 오염한 소식의 기호를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"sa","stem":"기업 소식 ㉠·㉡·㉢·㉣ 가운데 환경을 오염한 소식의 기호를 쓰세요.","answer":["㉡"],"explanation":["㉡은 폐수를 강에 흘려보냈어요.","이것은 환경 오염이에요.","㉠ 담합, ㉢ 거짓 광고, ㉣ 방해예요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"},"mis":"SO6-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#3','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','기업 소식 ㉢처럼 효과를 부풀린 광고를 막으려면 어떤 노력이 필요할까요?',ARRAY['SO6-2-u2-X09','SO6-2-u2-X08']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"기업 소식 ㉢처럼 효과를 부풀린 광고를 막으려면 어떤 노력이 필요할까요?","options":[{"t":"정부가 거짓이나 부풀린 광고를 하지 못하도록 규칙을 정하고 살핀다","correct":true},{"t":"기업이 광고를 더 많이 하게 돕는다","mis":"SO6-2-u2-X09"},{"t":"소비자가 광고를 믿고 그대로 사게 한다","mis":"SO6-2-u2-X08"},{"t":"광고는 기업의 자유이니 그냥 둔다","mis":"SO6-2-u2-X08"}],"explanation":["잘못된 정보는 소비자에게 피해를 줘요.","정부가 규칙을 정해 살펴요.","기업도 바른 정보를 줄 책임이 있어요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#4','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','기업이 지나치게 경쟁할 때 생기는 문제를 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"기업이 지나치게 경쟁할 때 생기는 문제를 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"소비자나 다른 기업이 입을 피해는 생각하지 않고 이윤만 좇아 담합·오염·거짓 광고가 생길 수 있다","correct":true},{"t":"경쟁이 지나치면 상품의 품질이 언제나 좋아진다","mis":"SO6-2-u2-X08"},{"t":"경쟁이 지나치면 기업이 모두 같은 상품을 만들어 문제가 없다","mis":"SO6-2-u2-X08"},{"t":"지나친 경쟁은 소비자에게 언제나 이익이다","mis":"SO6-2-u2-X08"}],"explanation":["이윤만 좇으면 다른 사람의 피해를 놓쳐요.","담합·오염·거짓 광고·방해가 생겨요.","그래서 책임과 바로잡기가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#5','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'ox','auto','기업이 사회적 책임을 다하면 경제가 성장하고 사회가 발전해요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"ox","stem":"기업이 사회적 책임을 다하면 경제가 성장하고 사회가 발전해요.","answer":"O","reason_options":[{"t":"환경을 지키고 소비자와 근로자를 살피는 기업이 늘면 사회 전체가 함께 좋아지기 때문에","correct":true},{"t":"사회적 책임은 기업의 이윤을 모두 없애기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["기업은 사회와 이어져 있어요.","책임을 다하면 믿음이 쌓여요.","경제와 사회가 함께 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#6','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'mc','auto','10대와 20대가 고루 좋아하는 제품을 알게 된 기업이 할 결정으로 가장 합리적인 것은 어느 것인가요?',ARRAY['SO6-2-u2-X09']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"10대와 20대가 고루 좋아하는 제품을 알게 된 기업이 할 결정으로 가장 합리적인 것은 어느 것인가요?","options":[{"t":"그 제품의 생산을 늘린다","correct":true},{"t":"아무도 찾지 않는 제품을 더 만든다","mis":"SO6-2-u2-X09"},{"t":"조사 결과와 상관없이 아무 제품이나 만든다","mis":"SO6-2-u2-X09"},{"t":"모든 제품의 생산을 멈춘다","mis":"SO6-2-u2-X09"}],"explanation":["많이 팔릴 제품을 더 만드는 것이 합리적이에요.","적은 비용으로 큰 이윤을 얻으려 해요.","주로 살 사람을 생각해 결정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#7','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',3,'error','auto','기업이 중요하게 여기는 세 가치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X09']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"error","stem":"기업이 중요하게 여기는 세 가치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「근로자와 소통하는 건 환경을 지키는 노력이야.」","correct":true,"mis_target":"SO6-2-u2-X09"},{"t":"리안 — 「에너지를 아껴 쓰는 건 환경을 위한 노력이야.」","mis":"SO6-2-u2-X09"},{"t":"건우 — 「소비자를 보호하는 건 사회를 위한 노력이야.」","mis":"SO6-2-u2-X09"}],"explanation":["근로자와 소통은 투명 경영이에요.","에너지는 환경, 소비자 보호는 사회예요.","세 가치를 가려서 기억해요."],"asset":{"type":"passage","lines":["환경 — 폐기물을 관리하고 에너지를 효율적으로 쓴다.","사회 — 사람들의 인권을 존중하고 소비자와 지역사회를 살핀다.","투명 경영 — 공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통한다."],"title":"기업이 중요하게 여기는 세 가치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#8','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'mc','auto','배에 돛(자유)만 달고 키(책임)가 없으면 바위에 부딪히는 것에 빗대어 말할 때, 이 비유가 뜻하는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"mc","stem":"배에 돛(자유)만 달고 키(책임)가 없으면 바위에 부딪히는 것에 빗대어 말할 때, 이 비유가 뜻하는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기업이 자유롭게 빨리 나아가도 책임이 없으면 이윤만 좇다가 사회에 피해를 주어 결국 자신도 어려워진다","correct":true},{"t":"기업에 자유가 있으면 책임은 필요 없다","mis":"SO6-2-u2-X08"},{"t":"기업은 자유 없이 책임만 있어야 잘 나아간다","mis":"SO6-2-u2-X08"},{"t":"바위는 경쟁하는 다른 기업을 뜻한다","mis":"SO6-2-u2-X08"}],"explanation":["돛은 앞으로 나아가는 힘이에요.","키는 방향을 바르게 잡아요.","둘 다 있어야 항구에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#9','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'mc','auto','작은 기업이 큰 기업과 공정하게 경쟁할 수 있도록 하는 노력이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X07']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"mc","stem":"작은 기업이 큰 기업과 공정하게 경쟁할 수 있도록 하는 노력이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공정한 경쟁이 있어야 여러 기업이 좋은 상품을 내놓아 소비자가 고를 수 있고 시장경제가 건강하게 돌아가기 때문에","correct":true},{"t":"큰 기업만 남아야 상품이 좋아지기 때문에","mis":"SO6-2-u2-X08"},{"t":"작은 기업은 경쟁하지 않아야 하기 때문에","mis":"SO6-2-u2-X08"},{"t":"경쟁은 소비자와 상관없기 때문에","mis":"SO6-2-u2-X07"}],"explanation":["큰 기업이 힘으로 누르면 경쟁이 사라져요.","경쟁이 사라지면 소비자가 손해예요.","공정한 경쟁이 시장경제를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L04_challenge#10','soc',6,2,'u2','L04','g6_2_soc_u2_L04_challenge','lesson_challenge','SO6-2-u2-C4',4,'essay','teacher','기업 소식 ㉠~㉣ 가운데 하나를 골라 어떤 문제가 있는지 쓰고, 그 문제를 해결하려면 정부와 기업이 각각 무엇을 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"essay","stem":"기업 소식 ㉠~㉣ 가운데 하나를 골라 어떤 문제가 있는지 쓰고, 그 문제를 해결하려면 정부와 기업이 각각 무엇을 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: ㉡은 공장에서 나온 폐수를 강에 몰래 흘려보내 환경을 오염했다. 정부는 환경을 오염한 기업에 벌금을 물리고, 환경을 오염하지 않는 것이 확인된 기업에 인증을 해 주면 좋겠다. 기업은 폐수를 깨끗하게 처리하는 시설을 갖추고 폐기물을 관리하는 사회적 책임을 다해야 한다.","scoring_points":["고른 소식의 문제를 바르게 썼는가","정부가 할 일을 썼는가","기업이 할 사회적 책임을 썼는가"]},"explanation":["지나친 경쟁은 문제를 낳아요.","정부는 바로잡고 지원해요.","기업은 사회적 책임을 다해요."],"asset":{"type":"passage","lines":["㉠ 몇몇 회사가 몰래 약속해서 함께 가격을 올렸다.","㉡ 공장에서 나온 폐수를 강에 몰래 흘려보냈다.","㉢ 효과가 없는 기능을 있는 것처럼 광고했다.","㉣ 다른 회사의 가게 앞을 막아 장사를 방해했다.","㉤ 공장 지붕에 태양광 패널을 달아 친환경 에너지를 쓴다."],"title":"어느 해 기업 소식 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#1','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'mc','auto','국가 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"국가 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것을 무엇이라고 하나요?","options":[{"t":"경제성장","correct":true},{"t":"시장경제","mis":"SO6-2-u2-X10"},{"t":"사회적 책임","mis":"SO6-2-u2-X10"},{"t":"무역","mis":"SO6-2-u2-X10"}],"explanation":["나라 전체의 생산과 소득이 늘어요.","경제 규모가 커져요.","이것이 경제성장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#2','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'mc','auto','세계가 우리나라의 빠른 경제성장을 부른 이름은 무엇인가요?',ARRAY['SO6-2-u2-X11','SO6-2-u2-X16']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"세계가 우리나라의 빠른 경제성장을 부른 이름은 무엇인가요?","options":[{"t":"한강의 기적","correct":true},{"t":"벽란도의 기적","mis":"SO6-2-u2-X11"},{"t":"공유지의 비극","mis":"SO6-2-u2-X16"},{"t":"지중해의 기적","mis":"SO6-2-u2-X11"}],"explanation":["폐허에서 빠르게 성장했어요.","세계가 놀랐어요.","그래서 「한강의 기적」이라 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#3','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',1,'ox','auto','우리나라는 처음부터 자원과 자본이 넉넉해서 쉽게 경제성장을 이루었어요.',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"ox","stem":"우리나라는 처음부터 자원과 자본이 넉넉해서 쉽게 경제성장을 이루었어요.","answer":"X","reason_options":[{"t":"6·25 전쟁으로 산업 시설이 폐허가 되고 자원과 자본이 거의 없는 상태에서 성장했기 때문에","correct":true},{"t":"우리나라는 땅속 자원이 세계에서 가장 많기 때문에","mis":"SO6-2-u2-X11"}],"mis":"SO6-2-u2-X11","explanation":["전쟁으로 산업 시설이 무너졌어요.","자원과 자본도 거의 없었어요.","그런데도 빠르게 성장했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#4','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',1,'mc','auto','경제가 성장하면서 의료 기술이 발달해 생긴 변화로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C6","difficulty":1,"kind":"mc","stem":"경제가 성장하면서 의료 기술이 발달해 생긴 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들의 기대 수명이 늘어났다","correct":true},{"t":"병원이 모두 사라졌다","mis":"SO6-2-u2-X13"},{"t":"기대 수명이 줄었다","mis":"SO6-2-u2-X13"},{"t":"의료 혜택을 받기 더 어려워졌다","mis":"SO6-2-u2-X13"}],"explanation":["치료하기 힘들던 병을 고칠 수 있게 됐어요.","수준 높은 의료 혜택을 받아요.","그래서 기대 수명이 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#5','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','우리나라 경제성장의 장면 ㉠~㉣을 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"우리나라 경제성장의 장면 ㉠~㉣을 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉠ → ㉣","correct":true},{"t":"㉢ → ㉡ → ㉠ → ㉣","mis":"SO6-2-u2-X11"},{"t":"㉠ → ㉡ → ㉢ → ㉣","mis":"SO6-2-u2-X11"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SO6-2-u2-X11"}],"explanation":["1960년대 경공업이 먼저예요.","1970년대 중화학 공업, 1988년 올림픽이에요.","오늘날 반도체와 문화 콘텐츠가 이어져요."],"asset":{"type":"passage","lines":["㉠ 1988년 서울 올림픽 대회를 열었다.","㉡ 1960년대 — 옷·신발·가발 같은 경공업 제품을 수출했다.","㉢ 1970년대 — 철강·배·석유 화학 같은 중화학 공업이 발달했다.","㉣ 오늘날 — 반도체·자동차와 음악·게임·웹툰이 세계로 나간다."],"title":"우리나라 경제성장의 장면(차례 섞음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#6','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','「1인당 국민 총소득」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"「1인당 국민 총소득」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 일정 기간 생산 활동에 참여한 대가로 받은 소득의 합을 인구수로 나눈 금액","correct":true},{"t":"한 나라에 사는 사람의 수","mis":"SO6-2-u2-X10"},{"t":"한 기업이 얻은 이윤의 합계","mis":"SO6-2-u2-X10"},{"t":"한 가계가 물건을 사는 데 쓴 돈","mis":"SO6-2-u2-X10"}],"explanation":["나라 사람들이 받은 소득을 모두 더해요.","그것을 인구수로 나눠요.","한 사람이 받은 소득을 어림할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#7','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',2,'match','auto','경제성장 뒤 달라진 모습 카드와 그 카드가 들어갈 바구니를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"match","stem":"경제성장 뒤 달라진 모습 카드와 그 카드가 들어갈 바구니를 알맞게 이으세요.","pairs":[{"l":"카드 ①","r":"첨단 기술"},{"l":"카드 ②","r":"의료"},{"l":"카드 ③","r":"문화 산업"},{"l":"카드 ④","r":"교육"}],"mis":"SO6-2-u2-X13","explanation":["로봇 생산은 첨단 기술이에요.","병 치료는 의료, 드라마·웹툰은 문화 산업이에요.","학습 자료는 교육이에요."],"asset":{"type":"passage","lines":["① 공장에서 로봇이 쉬지 않고 물건을 만든다.","② 치료하기 힘들던 병을 고칠 수 있게 되었다.","③ 외국 사람들이 우리 드라마와 웹툰을 즐겨 본다.","④ 학교마다 컴퓨터와 다양한 학습 자료가 갖춰졌다.","⑤ 빅데이터 전문가 같은 새로운 직업이 생겼다.","⑥ 사람들의 기대 수명이 늘어났다."],"title":"경제성장 뒤 달라진 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#8','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C6',2,'ox','auto','경제가 성장해 사람들의 생활이 풍족해지면 문화에 관한 관심이 높아져 문화 산업이 발달해요.',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"ox","stem":"경제가 성장해 사람들의 생활이 풍족해지면 문화에 관한 관심이 높아져 문화 산업이 발달해요.","answer":"O","reason_options":[{"t":"소득이 늘어 여유가 생기면 영화·음악·게임 같은 문화를 더 즐기기 때문에","correct":true},{"t":"경제가 성장하면 문화 산업은 사라지기 때문에","mis":"SO6-2-u2-X13"}],"mis":"SO6-2-u2-X13","explanation":["일자리와 소득이 늘었어요.","생활에 여유가 생겼어요.","문화와 관련한 산업이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#9','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',2,'mc','auto','우리나라가 빠른 경제성장을 이룰 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"우리나라가 빠른 경제성장을 이룰 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가계와 기업, 정부가 함께 노력했기 때문에","correct":true},{"t":"정부 혼자서만 노력했기 때문에","mis":"SO6-2-u2-X12"},{"t":"기업만 노력했기 때문에","mis":"SO6-2-u2-X12"},{"t":"아무도 노력하지 않아도 저절로 성장했기 때문에","mis":"SO6-2-u2-X12"}],"explanation":["가계는 열심히 일하고 저축했어요.","기업은 생산하고 수출했어요.","정부는 계획을 세우고 도왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_basic#10','soc',6,2,'u2','L05','g6_2_soc_u2_L05_basic','lesson_basic','SO6-2-u2-C5',3,'error','auto','두 나라의 1인당 국민 총소득 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"error","stem":"두 나라의 1인당 국민 총소득 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「우리나라는 처음부터 ○○ 나라보다 소득이 높았어.」","correct":true,"mis_target":"SO6-2-u2-X11"},{"t":"소은 — 「1980년까지는 두 나라가 크게 다르지 않았어.」","mis":"SO6-2-u2-X11"},{"t":"이든 — 「1980년 뒤로 우리나라 막대가 훨씬 빠르게 커졌어.」","mis":"SO6-2-u2-X11"}],"explanation":["1960년에는 ○○ 나라가 조금 더 높았어요.","1980년에는 비슷했어요.","그 뒤 우리나라가 급격하게 높아졌어요."],"asset":{"type":"passage","lines":["1인당 국민 총소득을 막대 크기로만 견준 표(금액 없음)","1960년 — 우리나라 ▮ · ○○ 나라 ▮▮","1980년 — 우리나라 ▮▮ · ○○ 나라 ▮▮","2000년 — 우리나라 ▮▮▮▮▮▮ · ○○ 나라 ▮▮▮","2020년 — 우리나라 ▮▮▮▮▮▮▮▮▮▮ · ○○ 나라 ▮▮▮▮"],"title":"두 나라의 1인당 국민 총소득"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#1','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',2,'sa','auto','경제성장 뒤 달라진 모습 카드 ⑤처럼 다양한 분야에서 빠르게 생기는 많은 양의 데이터 가운데 필요한 것을 찾아 분석하는 사람을 무엇이라고 하나요? 「○○○ 전문가」의 ○○○을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"sa","stem":"경제성장 뒤 달라진 모습 카드 ⑤처럼 다양한 분야에서 빠르게 생기는 많은 양의 데이터 가운데 필요한 것을 찾아 분석하는 사람을 무엇이라고 하나요? 「○○○ 전문가」의 ○○○을 쓰세요.","answer":["빅데이터"],"explanation":["빅데이터는 아주 많은 양의 데이터예요.","필요한 것을 찾아 분석해요.","경제성장으로 생긴 새로운 직업이에요."],"asset":{"type":"passage","lines":["① 공장에서 로봇이 쉬지 않고 물건을 만든다.","② 치료하기 힘들던 병을 고칠 수 있게 되었다.","③ 외국 사람들이 우리 드라마와 웹툰을 즐겨 본다.","④ 학교마다 컴퓨터와 다양한 학습 자료가 갖춰졌다.","⑤ 빅데이터 전문가 같은 새로운 직업이 생겼다.","⑥ 사람들의 기대 수명이 늘어났다."],"title":"경제성장 뒤 달라진 모습 카드"},"mis":"SO6-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#2','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',2,'mc','auto','경제성장 뒤 달라진 모습 카드 가운데 「의료」 바구니에 함께 들어갈 두 장은 어느 것인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"mc","stem":"경제성장 뒤 달라진 모습 카드 가운데 「의료」 바구니에 함께 들어갈 두 장은 어느 것인가요?","options":[{"t":"② · ⑥","correct":true},{"t":"① · ⑤","mis":"SO6-2-u2-X13"},{"t":"③ · ④","mis":"SO6-2-u2-X13"},{"t":"① · ③","mis":"SO6-2-u2-X13"}],"explanation":["②는 병 치료, ⑥은 기대 수명이에요.","둘 다 의료 기술 발달과 이어져요.","①·⑤는 첨단 기술이에요."],"asset":{"type":"passage","lines":["① 공장에서 로봇이 쉬지 않고 물건을 만든다.","② 치료하기 힘들던 병을 고칠 수 있게 되었다.","③ 외국 사람들이 우리 드라마와 웹툰을 즐겨 본다.","④ 학교마다 컴퓨터와 다양한 학습 자료가 갖춰졌다.","⑤ 빅데이터 전문가 같은 새로운 직업이 생겼다.","⑥ 사람들의 기대 수명이 늘어났다."],"title":"경제성장 뒤 달라진 모습 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#3','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',3,'mc','auto','두 나라의 1인당 국민 총소득 표에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X11','SO6-2-u2-X10']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"mc","stem":"두 나라의 1인당 국민 총소득 표에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"경제성장 속도는 나라마다 달라, 비슷하던 두 나라도 시간이 지나면 차이가 크게 벌어질 수 있다","correct":true},{"t":"두 나라의 경제성장 속도는 늘 같다","mis":"SO6-2-u2-X11"},{"t":"○○ 나라는 소득이 줄어들기만 했다","mis":"SO6-2-u2-X11"},{"t":"1인당 국민 총소득은 인구수와 같다","mis":"SO6-2-u2-X10"}],"explanation":["1980년까지는 비슷했어요.","그 뒤 우리나라가 훨씬 빠르게 성장했어요.","성장 속도는 나라마다 달라요."],"asset":{"type":"passage","lines":["1인당 국민 총소득을 막대 크기로만 견준 표(금액 없음)","1960년 — 우리나라 ▮ · ○○ 나라 ▮▮","1980년 — 우리나라 ▮▮ · ○○ 나라 ▮▮","2000년 — 우리나라 ▮▮▮▮▮▮ · ○○ 나라 ▮▮▮","2020년 — 우리나라 ▮▮▮▮▮▮▮▮▮▮ · ○○ 나라 ▮▮▮▮"],"title":"두 나라의 1인당 국민 총소득"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#4','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',3,'mc','auto','1960년대에 우리나라가 옷·신발·가발 같은 경공업 제품을 먼저 수출한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X11','SO6-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"mc","stem":"1960년대에 우리나라가 옷·신발·가발 같은 경공업 제품을 먼저 수출한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자본과 기술은 부족했지만 일할 사람이 많아 손으로 만드는 가벼운 제품을 만들기 알맞았기 때문에","correct":true},{"t":"처음부터 반도체를 만드는 기술이 뛰어났기 때문에","mis":"SO6-2-u2-X11"},{"t":"땅속에 원유가 많았기 때문에","mis":"SO6-2-u2-X19"},{"t":"올림픽을 먼저 열어 돈이 많았기 때문에","mis":"SO6-2-u2-X11"}],"explanation":["전쟁 뒤 자본과 기술이 모자랐어요.","일할 사람은 많았어요.","그래서 가벼운 제품부터 만들었어요."],"asset":{"type":"passage","lines":["㉠ 1988년 서울 올림픽 대회를 열었다.","㉡ 1960년대 — 옷·신발·가발 같은 경공업 제품을 수출했다.","㉢ 1970년대 — 철강·배·석유 화학 같은 중화학 공업이 발달했다.","㉣ 오늘날 — 반도체·자동차와 음악·게임·웹툰이 세계로 나간다."],"title":"우리나라 경제성장의 장면(차례 섞음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#5','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',3,'ox','auto','첨단 기술이 발전해 생산 속도가 빨라지고 생산량이 늘면 많은 상품을 적은 비용으로 만들 수 있어 경제가 더 성장해요.',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C6","difficulty":3,"kind":"ox","stem":"첨단 기술이 발전해 생산 속도가 빨라지고 생산량이 늘면 많은 상품을 적은 비용으로 만들 수 있어 경제가 더 성장해요.","answer":"O","reason_options":[{"t":"같은 비용으로 더 많이 만들면 값이 싸지고 더 많이 팔 수 있기 때문에","correct":true},{"t":"생산량이 늘면 상품을 팔 곳이 모두 사라지기 때문에","mis":"SO6-2-u2-X13"}],"mis":"SO6-2-u2-X13","explanation":["기술이 생산을 빠르게 해요.","많이 만들면 값이 싸져요.","경제가 더 성장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#6','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',3,'mc','auto','세계 여러 나라 사람들이 우리나라의 드라마와 웹툰을 즐기게 되면 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X13','SO6-2-u2-X12']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C6","difficulty":3,"kind":"mc","stem":"세계 여러 나라 사람들이 우리나라의 드라마와 웹툰을 즐기게 되면 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"콘텐츠 산업과 관련한 일자리가 늘고 우리나라 경제가 더 성장한다","correct":true},{"t":"콘텐츠와 관련한 일자리가 모두 사라진다","mis":"SO6-2-u2-X13"},{"t":"다른 산업의 수출이 모두 멈춘다","mis":"SO6-2-u2-X12"},{"t":"우리 경제와는 아무 관계가 없다","mis":"SO6-2-u2-X12"}],"explanation":["문화 콘텐츠도 수출 상품이에요.","많이 팔리면 일자리가 늘어요.","경제와 문화 산업은 함께 성장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#7','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',3,'error','auto','경제성장과 우리 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C6","difficulty":3,"kind":"error","stem":"경제성장과 우리 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「경제가 성장해도 교육과 의료는 하나도 달라지지 않았어.」","correct":true,"mis_target":"SO6-2-u2-X13"},{"t":"서하 — 「교육의 질이 높아지고 수준 높은 의료 혜택을 받게 됐어.」","mis":"SO6-2-u2-X13"},{"t":"주원 — 「생활이 풍족해져서 문화에 관한 관심이 높아졌어.」","mis":"SO6-2-u2-X13"}],"explanation":["경제성장은 교육과 의료도 바꿨어요.","교육의 질이 높아졌어요.","삶의 질이 높아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#8','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',4,'mc','auto','경제성장이 「경제 규모가 커지는 것」이라는 뜻에 가장 잘 맞는 예는 어느 것인가요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C5","difficulty":4,"kind":"mc","stem":"경제성장이 「경제 규모가 커지는 것」이라는 뜻에 가장 잘 맞는 예는 어느 것인가요?","options":[{"t":"나라 전체에서 만드는 물건과 서비스가 늘고 국민이 받는 소득도 함께 늘었다","correct":true},{"t":"한 회사가 올해 이윤을 많이 남겼다","mis":"SO6-2-u2-X10"},{"t":"나라의 인구가 늘었다","mis":"SO6-2-u2-X10"},{"t":"한 가족이 큰 집으로 이사했다","mis":"SO6-2-u2-X10"}],"explanation":["경제성장은 나라 전체를 봐요.","한 회사나 한 가족의 일이 아니에요.","인구가 느는 것과도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#9','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C6',4,'mc','auto','경제와 문화 산업의 관계를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X13']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C6","difficulty":4,"kind":"mc","stem":"경제와 문화 산업의 관계를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"경제가 성장하면 문화 산업이 발달하고, 문화 산업이 발전하면 일자리가 늘어 경제가 다시 성장한다","correct":true},{"t":"문화 산업이 발달하면 경제가 반드시 줄어든다","mis":"SO6-2-u2-X12"},{"t":"경제와 문화 산업은 서로 관계가 없다","mis":"SO6-2-u2-X12"},{"t":"경제가 성장하면 문화 산업만 작아진다","mis":"SO6-2-u2-X13"}],"explanation":["경제성장 → 여유 → 문화 산업 발달이에요.","문화 산업 → 일자리·수출 → 경제성장이에요.","둘은 서로 이어져 함께 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L05_challenge#10','soc',6,2,'u2','L05','g6_2_soc_u2_L05_challenge','lesson_challenge','SO6-2-u2-C5',4,'essay','teacher','두 나라의 1인당 국민 총소득 표와 우리나라 경제성장의 장면을 보고, 우리나라 경제성장의 특징을 쓰고 그렇게 성장할 수 있었던 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C5","difficulty":4,"kind":"essay","stem":"두 나라의 1인당 국민 총소득 표와 우리나라 경제성장의 장면을 보고, 우리나라 경제성장의 특징을 쓰고 그렇게 성장할 수 있었던 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리나라는 1980년까지는 ○○ 나라와 소득이 비슷했지만 그 뒤 매우 빠르게 성장해 차이가 크게 벌어졌다. 6·25 전쟁으로 산업 시설이 폐허가 되고 자원과 자본이 거의 없었는데도 1960년대 경공업, 1970년대 중화학 공업, 오늘날 반도체와 문화 콘텐츠로 이어지며 성장했다. 이렇게 성장할 수 있었던 것은 가계와 기업, 정부가 함께 노력했기 때문이다.","scoring_points":["빠르게 성장했다는 특징을 표를 근거로 썼는가","어려운 출발 조건이나 성장 과정을 썼는가","가계·기업·정부의 노력을 까닭으로 썼는가"]},"explanation":["표 — 1980년 뒤 급격히 커졌어요.","폐허에서 출발했어요.","모두가 함께 노력했어요."],"asset":{"type":"passage","lines":["1인당 국민 총소득을 막대 크기로만 견준 표(금액 없음)","1960년 — 우리나라 ▮ · ○○ 나라 ▮▮","1980년 — 우리나라 ▮▮ · ○○ 나라 ▮▮","2000년 — 우리나라 ▮▮▮▮▮▮ · ○○ 나라 ▮▮▮","2020년 — 우리나라 ▮▮▮▮▮▮▮▮▮▮ · ○○ 나라 ▮▮▮▮"],"title":"두 나라의 1인당 국민 총소득"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#1','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',1,'mc','auto','경제적으로 부유한 사람과 가난한 사람의 소득 차이가 커지는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X14','SO6-2-u2-X12']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C7","difficulty":1,"kind":"mc","stem":"경제적으로 부유한 사람과 가난한 사람의 소득 차이가 커지는 것을 무엇이라고 하나요?","options":[{"t":"빈부 격차","correct":true},{"t":"과소비","mis":"SO6-2-u2-X14"},{"t":"노사 갈등","mis":"SO6-2-u2-X14"},{"t":"경제성장","mis":"SO6-2-u2-X12"}],"explanation":["「빈」은 가난, 「부」는 부유함이에요.","소득 차이가 커지는 것이에요.","경제성장 과정에서 나타나기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#2','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',1,'mc','auto','필요한 것보다 더 많은 돈을 쓰는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X14','SO6-2-u2-X05']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C7","difficulty":1,"kind":"mc","stem":"필요한 것보다 더 많은 돈을 쓰는 것을 무엇이라고 하나요?","options":[{"t":"과소비","correct":true},{"t":"저축","mis":"SO6-2-u2-X14"},{"t":"합리적 선택","mis":"SO6-2-u2-X05"},{"t":"빈부 격차","mis":"SO6-2-u2-X14"}],"explanation":["「과」는 지나치다는 뜻이에요.","필요보다 많이 쓰는 거예요.","소득이 늘면서 나타났어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#3','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',1,'ox','auto','빠른 경제성장으로 생긴 문제를 해결해야 우리나라 경제가 지속적으로 발전할 수 있어요.',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C8","difficulty":1,"kind":"ox","stem":"빠른 경제성장으로 생긴 문제를 해결해야 우리나라 경제가 지속적으로 발전할 수 있어요.","answer":"O","reason_options":[{"t":"문제를 그대로 두면 생활에 나쁜 영향을 주고 해결 비용도 커져 성장이 어려워지기 때문에","correct":true},{"t":"문제를 해결하면 경제성장이 멈추기 때문에","mis":"SO6-2-u2-X15"}],"mis":"SO6-2-u2-X15","explanation":["문제가 쌓이면 성장도 막혀요.","해결 비용도 점점 커져요.","그래서 함께 해결해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#4','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',1,'mc','auto','공유하는 자원을 자기 이익만 생각하며 써서 결국 공동체 전체가 피해를 보는 현상을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X16','SO6-2-u2-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C8","difficulty":1,"kind":"mc","stem":"공유하는 자원을 자기 이익만 생각하며 써서 결국 공동체 전체가 피해를 보는 현상을 무엇이라고 하나요?","options":[{"t":"공유지의 비극","correct":true},{"t":"한강의 기적","mis":"SO6-2-u2-X16"},{"t":"빈부 격차","mis":"SO6-2-u2-X14"},{"t":"사회적 책임","mis":"SO6-2-u2-X16"}],"explanation":["함께 쓰는 자원을 나만 생각하며 써요.","자원이 줄어 모두 피해를 봐요.","이것이 공유지의 비극이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#5','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',2,'match','auto','경고등 ㉮~㉱와 그 문제의 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"match","stem":"경고등 ㉮~㉱와 그 문제의 이름을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"자원 낭비와 환경 문제"},{"l":"㉯","r":"빈부 격차 문제"},{"l":"㉰","r":"과소비 문제"},{"l":"㉱","r":"노사 갈등 문제"}],"mis":"SO6-2-u2-X14","explanation":["㉮ 쓰레기가 넘쳐요.","㉯ 소득 차이, ㉰ 많이 사고 버려요.","㉱ 근로자와 기업이 맞서요."],"asset":{"type":"passage","lines":["㉮ 쓰레기 처리장에 재활용 쓰레기가 넘쳐 묻을 곳이 모자란다.","㉯ 소득이 높은 사람과 낮은 사람의 차이가 점점 커진다.","㉰ 필요한 것보다 많이 사고 쉽게 버리는 일이 늘었다.","㉱ 임금과 복지를 두고 근로자와 기업이 맞선다."],"title":"경제성장 뒤에 켜진 경고등"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#6','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',2,'mc','auto','경제성장 과정에서 환경 문제가 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"경제성장 과정에서 환경 문제가 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자연을 무분별하게 개발하고 오염 물질과 쓰레기가 늘었기 때문에","correct":true},{"t":"숲을 더 많이 가꾸었기 때문에","mis":"SO6-2-u2-X14"},{"t":"공장이 모두 문을 닫았기 때문에","mis":"SO6-2-u2-X14"},{"t":"사람들이 물건을 덜 샀기 때문에","mis":"SO6-2-u2-X14"}],"explanation":["개발이 지나쳤어요.","공장과 가정에서 오염 물질이 늘었어요.","쓰레기도 많아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#7','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',2,'mc','auto','모둠에서 해결 방안을 고를 때 알맞은 방법은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"모둠에서 해결 방안을 고를 때 알맞은 방법은 어느 것인가요?","options":[{"t":"평가 기준을 세우고 기준에 따라 점수를 매겨 견준다","correct":true},{"t":"가장 먼저 나온 방안으로 정한다","mis":"SO6-2-u2-X15"},{"t":"느낌으로 마음에 드는 것을 고른다","mis":"SO6-2-u2-X15"},{"t":"비용이 가장 많이 드는 방안을 고른다","mis":"SO6-2-u2-X15"}],"explanation":["기준을 먼저 세워요.","기준마다 점수를 매겨요.","합계를 견주어 골라요."],"asset":{"type":"passage","lines":["해결하고 싶은 문제 — 자원 낭비(재활용 쓰레기가 넘침)","방안 ㉠ 분리배출 캠페인 — 실천 3 · 효과 1 · 비용 3","방안 ㉡ 재활용 공장 새로 짓기 — 실천 1 · 효과 3 · 비용 1","방안 ㉢ 다회용기 쓰는 가게에 혜택 — 실천 2 · 효과 3 · 비용 1","점수는 1~3, 비용은 적게 들수록 높은 점수"],"title":"모둠 해결 방안 점수판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#8','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',2,'sa','auto','모둠 해결 방안 점수판에서 방안 ㉠의 점수 합계는 몇 점인가요?','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"sa","stem":"모둠 해결 방안 점수판에서 방안 ㉠의 점수 합계는 몇 점인가요?","answer":["7"],"explanation":["실천 3, 효과 1, 비용 3이에요.","3 + 1 + 3 = 7이에요.","합계로 방안을 견줘요."],"asset":{"type":"passage","lines":["해결하고 싶은 문제 — 자원 낭비(재활용 쓰레기가 넘침)","방안 ㉠ 분리배출 캠페인 — 실천 3 · 효과 1 · 비용 3","방안 ㉡ 재활용 공장 새로 짓기 — 실천 1 · 효과 3 · 비용 1","방안 ㉢ 다회용기 쓰는 가게에 혜택 — 실천 2 · 효과 3 · 비용 1","점수는 1~3, 비용은 적게 들수록 높은 점수"],"title":"모둠 해결 방안 점수판"},"mis":"SO6-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#9','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C7',2,'ox','auto','빈부 격차가 커지면 사람들 사이의 갈등이 커져 사회가 불안정해질 수 있어요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"ox","stem":"빈부 격차가 커지면 사람들 사이의 갈등이 커져 사회가 불안정해질 수 있어요.","answer":"O","reason_options":[{"t":"소득이 낮은 사람의 살기가 점점 어려워지면 불만과 갈등이 커지기 때문에","correct":true},{"t":"빈부 격차는 사람들의 생활과 관계가 없기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["차이가 커지면 갈등이 생겨요.","사회가 불안정해져요.","경제성장도 어려워질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_basic#10','soc',6,2,'u2','L07','g6_2_soc_u2_L07_basic','lesson_basic','SO6-2-u2-C8',3,'error','auto','경제성장 문제의 해결을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"error","stem":"경제성장 문제의 해결을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「문제 해결은 정부가 할 일이니 우리는 할 게 없어.」","correct":true,"mis_target":"SO6-2-u2-X15"},{"t":"예린 — 「기업과 근로자는 서로 소통하며 근로 환경을 고쳐 나가.」","mis":"SO6-2-u2-X15"},{"t":"하온 — 「시민 단체와 개인도 쓰레기 줍기 같은 노력을 해.」","mis":"SO6-2-u2-X15"}],"explanation":["정부는 제도와 정책을 만들어요.","기업·근로자·시민 단체·개인도 노력해요.","모두 함께 해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#1','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C7',2,'mc','auto','전체 인구 가운데 빈곤 위험에 처한 사람의 비율이 높다는 것은 무엇을 뜻하나요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X14']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"전체 인구 가운데 빈곤 위험에 처한 사람의 비율이 높다는 것은 무엇을 뜻하나요?","options":[{"t":"그 나라의 빈부 격차가 크다","correct":true},{"t":"그 나라의 경제가 빠르게 성장한다","mis":"SO6-2-u2-X12"},{"t":"그 나라 사람들이 과소비를 하지 않는다","mis":"SO6-2-u2-X14"},{"t":"그 나라의 환경이 깨끗하다","mis":"SO6-2-u2-X14"}],"explanation":["이 비율을 상대적 빈곤율이라고 해요.","높을수록 어려운 사람이 많아요.","빈부 격차가 크다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#2','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',2,'mc','auto','모둠 해결 방안 점수판에서 합계가 가장 높은 방안은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"모둠 해결 방안 점수판에서 합계가 가장 높은 방안은 어느 것인가요?","options":[{"t":"㉠ 분리배출 캠페인","correct":true},{"t":"㉡ 재활용 공장 새로 짓기","mis":"SO6-2-u2-X15"},{"t":"㉢ 다회용기 쓰는 가게에 혜택","mis":"SO6-2-u2-X15"},{"t":"세 방안이 모두 같다","mis":"SO6-2-u2-X15"}],"explanation":["㉠ 3+1+3 = 7이에요.","㉡ 1+3+1 = 5, ㉢ 2+3+1 = 6이에요.","㉠이 가장 높아요."],"asset":{"type":"passage","lines":["해결하고 싶은 문제 — 자원 낭비(재활용 쓰레기가 넘침)","방안 ㉠ 분리배출 캠페인 — 실천 3 · 효과 1 · 비용 3","방안 ㉡ 재활용 공장 새로 짓기 — 실천 1 · 효과 3 · 비용 1","방안 ㉢ 다회용기 쓰는 가게에 혜택 — 실천 2 · 효과 3 · 비용 1","점수는 1~3, 비용은 적게 들수록 높은 점수"],"title":"모둠 해결 방안 점수판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#3','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',3,'mc','auto','모둠이 「효과」를 가장 중요하게 보고 효과 점수를 두 번 더하기로 했어요. 그러면 합계가 가장 높은 방안은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"모둠이 「효과」를 가장 중요하게 보고 효과 점수를 두 번 더하기로 했어요. 그러면 합계가 가장 높은 방안은 어느 것인가요?","options":[{"t":"㉢ 다회용기 쓰는 가게에 혜택","correct":true},{"t":"㉠ 분리배출 캠페인","mis":"SO6-2-u2-X15"},{"t":"㉡ 재활용 공장 새로 짓기","mis":"SO6-2-u2-X15"},{"t":"세 방안이 모두 같다","mis":"SO6-2-u2-X15"}],"explanation":["㉠ 3+1+1+3 = 8이에요.","㉡ 1+3+3+1 = 8, ㉢ 2+3+3+1 = 9예요.","효과를 무겁게 보니 ㉢이 가장 높아요."],"asset":{"type":"passage","lines":["해결하고 싶은 문제 — 자원 낭비(재활용 쓰레기가 넘침)","방안 ㉠ 분리배출 캠페인 — 실천 3 · 효과 1 · 비용 3","방안 ㉡ 재활용 공장 새로 짓기 — 실천 1 · 효과 3 · 비용 1","방안 ㉢ 다회용기 쓰는 가게에 혜택 — 실천 2 · 효과 3 · 비용 1","점수는 1~3, 비용은 적게 들수록 높은 점수"],"title":"모둠 해결 방안 점수판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#4','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C7',3,'mc','auto','과소비가 계속될 때 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"mc","stem":"과소비가 계속될 때 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빚을 지게 되고 자원이 낭비되어 경제가 계속 성장하기 어려워진다","correct":true},{"t":"자원이 저절로 늘어난다","mis":"SO6-2-u2-X14"},{"t":"빈부 격차가 모두 사라진다","mis":"SO6-2-u2-X14"},{"t":"쓰레기가 줄어든다","mis":"SO6-2-u2-X14"}],"explanation":["필요보다 많이 쓰면 빚이 생겨요.","자원도 헤프게 써요.","경제성장에 걸림돌이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#5','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',3,'ox','auto','공유지의 비극을 막으려면 자원을 함부로 쓰지 못하게 하는 규칙과 함께, 공동의 이익을 생각하는 사람들의 태도가 필요해요.',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"ox","stem":"공유지의 비극을 막으려면 자원을 함부로 쓰지 못하게 하는 규칙과 함께, 공동의 이익을 생각하는 사람들의 태도가 필요해요.","answer":"O","reason_options":[{"t":"규칙만 있어도 사람들이 지키려 하지 않으면 자원은 계속 줄어들기 때문에","correct":true},{"t":"규칙만 만들면 태도는 상관없기 때문에","mis":"SO6-2-u2-X16"}],"mis":"SO6-2-u2-X16","explanation":["규칙은 자원을 지키는 울타리예요.","사람들이 지켜야 울타리가 돼요.","공동의 이익을 생각하는 마음이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#6','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',3,'mc','auto','공동 어장 이야기에서 물고기가 크게 줄어든 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"공동 어장 이야기에서 물고기가 크게 줄어든 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"함께 쓰는 어장을 저마다 자기 이익만 생각하며 써서","correct":true},{"t":"사람들이 물고기를 아껴 잡아서","mis":"SO6-2-u2-X16"},{"t":"어장에 규칙이 너무 많아서","mis":"SO6-2-u2-X16"},{"t":"바다가 저절로 깨끗해져서","mis":"SO6-2-u2-X16"}],"explanation":["「남이 잡기 전에 나도」라고 생각했어요.","모두 더 많이 잡았어요.","결국 모두 잡을 것이 없어졌어요."],"asset":{"type":"passage","lines":["어느 바닷가 마을 사람들은 함께 쓰는 어장에서 물고기를 잡는다.","저마다 「남이 더 잡기 전에 나도 많이 잡자」고 생각했다.","몇 해 뒤 어장의 물고기가 크게 줄어 모두 잡을 것이 없어졌다."],"title":"공동 어장 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#7','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C7',3,'error','auto','경고등 ㉯를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X14','SO6-2-u2-X12']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"error","stem":"경고등 ㉯를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세린 — 「소득 차이가 커지는 건 쓰레기가 넘치는 것과 같은 문제야.」","correct":true,"mis_target":"SO6-2-u2-X14"},{"t":"다온 — 「소득 차이가 커지면 갈등이 커질 수 있어.」","mis":"SO6-2-u2-X12"},{"t":"로하 — 「소득 차이가 줄면 사회가 안정될 수 있어.」","mis":"SO6-2-u2-X12"}],"explanation":["㉯는 빈부 격차 문제예요.","쓰레기가 넘치는 것은 ㉮의 문제예요.","문제마다 까닭과 해결이 달라요."],"asset":{"type":"passage","lines":["㉮ 쓰레기 처리장에 재활용 쓰레기가 넘쳐 묻을 곳이 모자란다.","㉯ 소득이 높은 사람과 낮은 사람의 차이가 점점 커진다.","㉰ 필요한 것보다 많이 사고 쉽게 버리는 일이 늘었다.","㉱ 임금과 복지를 두고 근로자와 기업이 맞선다."],"title":"경제성장 뒤에 켜진 경고등"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#8','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',4,'mc','auto','점수판에서 기준에 두는 무게를 바꾸자 가장 높은 방안이 달라졌어요. 여기서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"mc","stem":"점수판에서 기준에 두는 무게를 바꾸자 가장 높은 방안이 달라졌어요. 여기서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 평가 기준을 얼마나 중요하게 보느냐에 따라 고르는 방안이 달라지므로 기준을 함께 정하는 일이 중요하다","correct":true},{"t":"점수판은 쓸모가 없으니 느낌으로 고르는 것이 낫다","mis":"SO6-2-u2-X15"},{"t":"어떤 기준을 쓰든 언제나 같은 방안이 뽑힌다","mis":"SO6-2-u2-X15"},{"t":"비용이 적게 드는 방안이 언제나 가장 좋다","mis":"SO6-2-u2-X15"}],"explanation":["기준의 무게가 결과를 바꿔요.","그래서 기준을 정하는 일이 중요해요.","모둠이 함께 기준을 정해요."],"asset":{"type":"passage","lines":["해결하고 싶은 문제 — 자원 낭비(재활용 쓰레기가 넘침)","방안 ㉠ 분리배출 캠페인 — 실천 3 · 효과 1 · 비용 3","방안 ㉡ 재활용 공장 새로 짓기 — 실천 1 · 효과 3 · 비용 1","방안 ㉢ 다회용기 쓰는 가게에 혜택 — 실천 2 · 효과 3 · 비용 1","점수는 1~3, 비용은 적게 들수록 높은 점수"],"title":"모둠 해결 방안 점수판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#9','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C7',4,'mc','auto','경고등 ㉱(노사 갈등)를 해결하려는 노력으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X14','SO6-2-u2-X06']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C7","difficulty":4,"kind":"mc","stem":"경고등 ㉱(노사 갈등)를 해결하려는 노력으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근로자와 기업이 정기적으로 만나 임금과 복지를 협의하고, 정부는 더 나은 일자리를 위한 제도를 만든다","correct":true},{"t":"쓰레기 줍기 캠페인을 연다","mis":"SO6-2-u2-X14"},{"t":"물건을 더 많이 사도록 광고한다","mis":"SO6-2-u2-X14"},{"t":"근로자의 의견은 듣지 않고 기업이 정한다","mis":"SO6-2-u2-X06"}],"explanation":["노사 갈등은 근로자와 기업 사이의 문제예요.","협의와 소통이 해결의 길이에요.","정부의 제도도 함께해요."],"asset":{"type":"passage","lines":["㉮ 쓰레기 처리장에 재활용 쓰레기가 넘쳐 묻을 곳이 모자란다.","㉯ 소득이 높은 사람과 낮은 사람의 차이가 점점 커진다.","㉰ 필요한 것보다 많이 사고 쉽게 버리는 일이 늘었다.","㉱ 임금과 복지를 두고 근로자와 기업이 맞선다."],"title":"경제성장 뒤에 켜진 경고등"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L07_challenge#10','soc',6,2,'u2','L07','g6_2_soc_u2_L07_challenge','lesson_challenge','SO6-2-u2-C8',4,'essay','teacher','경고등 ㉮~㉱ 가운데 하나를 골라 문제의 까닭을 쓰고, 해결 방안 두 가지를 평가 기준 두 가지로 견주어 하나를 고른 뒤 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"essay","stem":"경고등 ㉮~㉱ 가운데 하나를 골라 문제의 까닭을 쓰고, 해결 방안 두 가지를 평가 기준 두 가지로 견주어 하나를 고른 뒤 그 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉰ 과소비 문제를 골랐다. 소득이 늘면서 필요보다 많이 사고 쉽게 버리게 되었기 때문이다. 방안 ① 「사기 전에 꼭 필요한지 적어 보는 소비 일기 쓰기」는 실천하기 쉽고 비용이 들지 않는다. 방안 ② 「중고 물품 나눔 장터 열기」는 효과는 크지만 장소와 준비에 비용이 든다. 실천할 수 있는지와 비용 두 기준으로 보면 ①이 더 높아서 ①을 고르겠다.","scoring_points":["문제의 까닭을 바르게 썼는가","방안 두 가지를 평가 기준 두 가지로 견주었는가","고른 방안과 그 까닭을 기준에 맞게 썼는가"]},"explanation":["문제의 까닭부터 찾아요.","기준을 세워 견줘요.","고른 까닭을 기준으로 말해요."],"asset":{"type":"passage","lines":["㉮ 쓰레기 처리장에 재활용 쓰레기가 넘쳐 묻을 곳이 모자란다.","㉯ 소득이 높은 사람과 낮은 사람의 차이가 점점 커진다.","㉰ 필요한 것보다 많이 사고 쉽게 버리는 일이 늘었다.","㉱ 임금과 복지를 두고 근로자와 기업이 맞선다."],"title":"경제성장 뒤에 켜진 경고등"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#1','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'mc','auto','나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X20']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일을 무엇이라고 하나요?","options":[{"t":"무역","correct":true},{"t":"경제성장","mis":"SO6-2-u2-X18"},{"t":"시장경제","mis":"SO6-2-u2-X18"},{"t":"관세","mis":"SO6-2-u2-X20"}],"explanation":["나라와 나라 사이의 거래예요.","물건도 서비스도 오가요.","이것이 무역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#2','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'mc','auto','다른 나라에서 물자나 서비스를 사 오는 것을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"다른 나라에서 물자나 서비스를 사 오는 것을 무엇이라고 하나요?","options":[{"t":"수입","correct":true},{"t":"수출","mis":"SO6-2-u2-X17"},{"t":"소득","mis":"SO6-2-u2-X17"},{"t":"이윤","mis":"SO6-2-u2-X17"}],"explanation":["사 오는 것은 수입이에요.","파는 것은 수출이에요.","「입」은 들어온다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#3','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'sa','auto','다른 나라에 물자나 서비스를 파는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"sa","stem":"다른 나라에 물자나 서비스를 파는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["수출"],"explanation":["파는 것은 수출이에요.","「출」은 나간다는 뜻이에요.","사 오는 것은 수입이에요."],"mis":"SO6-2-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#4','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',1,'ox','auto','드라마나 예능 같은 서비스도 다른 나라에 수출할 수 있어요.',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"ox","stem":"드라마나 예능 같은 서비스도 다른 나라에 수출할 수 있어요.","answer":"O","reason_options":[{"t":"무역에서는 물건뿐 아니라 서비스도 사고팔기 때문에","correct":true},{"t":"무역은 손에 잡히는 물건만 사고팔기 때문에","mis":"SO6-2-u2-X18"}],"mis":"SO6-2-u2-X18","explanation":["드라마와 예능도 다른 나라에 팔아요.","서비스도 무역의 대상이에요.","다양한 분야에서 무역이 이루어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#5','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','벽란도에서 다른 나라 상인들이 사 간 고려의 물건이 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"벽란도에서 다른 나라 상인들이 사 간 고려의 물건이 아닌 것은 어느 것인가요?","options":[{"t":"비단","correct":true},{"t":"인삼","mis":"SO6-2-u2-X17"},{"t":"종이","mis":"SO6-2-u2-X17"},{"t":"삼베","mis":"SO6-2-u2-X17"}],"explanation":["비단은 송나라 상인이 가져와 판 물건이에요.","고려의 인삼·종이·삼베·모시를 사 갔어요.","고려 시대에도 무역이 활발했어요."],"asset":{"type":"passage","lines":["고려 시대 예성강 하구의 항구 벽란도에는 여러 나라 배가 드나들었다.","송나라 상인 — 비단·약재·서적·악기를 가져와 팔았다.","아라비아 상인 — 보석과 향료를 가져와 팔았다.","다른 나라 상인들은 고려의 인삼·종이·삼베·모시를 사 갔다."],"title":"고려의 무역항 벽란도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#6','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','벽란도에서 송나라 상인이 고려의 인삼을 사 갔어요. 이 거래는 송나라 쪽에서 보면 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X18']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"벽란도에서 송나라 상인이 고려의 인삼을 사 갔어요. 이 거래는 송나라 쪽에서 보면 무엇인가요?","options":[{"t":"수입","correct":true},{"t":"수출","mis":"SO6-2-u2-X17"},{"t":"무역이 아니다","mis":"SO6-2-u2-X18"},{"t":"한 나라 안의 거래","mis":"SO6-2-u2-X18"}],"explanation":["송나라 상인이 다른 나라 물건을 사 갔어요.","송나라 쪽에서는 들여온 것이에요.","고려 쪽에서 보면 수출이에요."],"asset":{"type":"passage","lines":["고려 시대 예성강 하구의 항구 벽란도에는 여러 나라 배가 드나들었다.","송나라 상인 — 비단·약재·서적·악기를 가져와 팔았다.","아라비아 상인 — 보석과 향료를 가져와 팔았다.","다른 나라 상인들은 고려의 인삼·종이·삼베·모시를 사 갔다."],"title":"고려의 무역항 벽란도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#7','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'mc','auto','사람들이 무역을 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"사람들이 무역을 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 나라 안에서 구하기 어려운 물자나 서비스를 이용하려고","correct":true},{"t":"한 나라 안에서 모든 물자를 쉽게 구할 수 있어서","mis":"SO6-2-u2-X18"},{"t":"다른 나라 물자는 모두 품질이 낮아서","mis":"SO6-2-u2-X18"},{"t":"나라마다 필요한 물자가 하나도 없어서","mis":"SO6-2-u2-X18"}],"explanation":["나라 안에 없는 것도 있어요.","다른 나라에서 사 와요.","그래서 무역을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#8','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'match','auto','두 나라 이야기를 보고 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"match","stem":"두 나라 이야기를 보고 알맞게 이으세요.","pairs":[{"l":"㉮ 나라가 수출할 상품","r":"옷"},{"l":"㉯ 나라가 수출할 상품","r":"쌀"},{"l":"㉮ 나라가 옷을 잘 만드는 까닭","r":"높은 기술 수준"},{"l":"㉯ 나라가 쌀을 잘 기르는 까닭","r":"넓은 들과 알맞은 기후"}],"mis":"SO6-2-u2-X18","explanation":["㉮는 기술이 높아 옷을 잘 만들어요.","㉯는 들이 넓어 쌀을 잘 길러요.","잘 만드는 것을 팔고 모자란 것을 사요."],"asset":{"type":"passage","lines":["㉮ 나라 — 기술 수준이 높아 옷을 잘 만든다. 쌀을 기르기엔 땅이 모자란다.","㉯ 나라 — 넓은 들과 알맞은 기후로 쌀을 잘 기른다. 옷 만드는 기술은 모자란다.","두 나라가 같은 시간과 비용을 들인다고 하자."],"title":"두 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#9','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',2,'ox','auto','나라마다 자연환경·자원·자본·기술이 달라 더 잘 생산할 수 있는 물자나 서비스가 서로 달라요.',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"ox","stem":"나라마다 자연환경·자원·자본·기술이 달라 더 잘 생산할 수 있는 물자나 서비스가 서로 달라요.","answer":"O","reason_options":[{"t":"조건이 다르면 같은 비용으로 더 많이, 더 잘 만드는 것이 달라지기 때문에","correct":true},{"t":"모든 나라는 같은 물자를 똑같이 잘 만들기 때문에","mis":"SO6-2-u2-X18"}],"mis":"SO6-2-u2-X18","explanation":["땅·기후·자원이 달라요.","돈과 기술도 달라요.","그래서 잘 만드는 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_basic#10','soc',6,2,'u2','L09','g6_2_soc_u2_L09_basic','lesson_basic','SO6-2-u2-C9',3,'error','auto','수입과 수출을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"error","stem":"수입과 수출을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「우리나라가 외국에서 바나나를 사 오는 건 수출이야.」","correct":true,"mis_target":"SO6-2-u2-X17"},{"t":"연우 — 「우리 떡볶이를 다른 나라에 파는 건 수출이야.」","mis":"SO6-2-u2-X17"},{"t":"채린 — 「외국에서 만든 학용품을 사 오는 건 수입이야.」","mis":"SO6-2-u2-X17"}],"explanation":["사 오는 것은 수입이에요.","바나나를 사 오는 것은 수입이에요.","파는 것이 수출이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#1','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',2,'mc','auto','한 나라가 천연가스를 전혀 구할 수 없다면 어떤 어려움이 생길까요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"한 나라가 천연가스를 전혀 구할 수 없다면 어떤 어려움이 생길까요?","options":[{"t":"난방을 하거나 차를 움직이는 연료가 모자라 생활이 불편해진다","correct":true},{"t":"쌀을 재배하기 어려워진다","mis":"SO6-2-u2-X18"},{"t":"비행기를 더 많이 만들 수 있다","mis":"SO6-2-u2-X18"},{"t":"아무 문제도 생기지 않는다","mis":"SO6-2-u2-X18"}],"explanation":["천연가스는 난방과 차량의 연료예요.","없으면 생활이 불편해요.","그래서 다른 나라에서 수입해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#2','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',2,'mc','auto','흑연과 배터리 이야기에서 우리나라가 흑연을 거의 캐지 않게 된 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X17']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"흑연과 배터리 이야기에서 우리나라가 흑연을 거의 캐지 않게 된 까닭은 무엇인가요?","options":[{"t":"다른 나라에서 값싼 흑연을 수입하게 되었기 때문에","correct":true},{"t":"흑연이 더 이상 쓸모없어졌기 때문에","mis":"SO6-2-u2-X18"},{"t":"흑연을 다른 나라에 모두 수출했기 때문에","mis":"SO6-2-u2-X17"},{"t":"흑연으로는 아무것도 만들 수 없기 때문에","mis":"SO6-2-u2-X18"}],"explanation":["다른 나라 흑연이 더 쌌어요.","사 오는 편이 이익이었어요.","그래서 직접 캐지 않게 됐어요."],"asset":{"type":"passage","lines":["과거 — 우리나라는 흑연을 많이 캐는 나라였다.","그 뒤 — 다른 나라에서 값싼 흑연을 수입하며 거의 캐지 않게 되었다.","오늘날 — 수입한 흑연으로 전기차 배터리를 만들어 수출한다.","흑연을 캐는 나라는 그 배터리를 단 전기차를 수입하기도 한다."],"title":"흑연과 배터리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#3','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'mc','auto','두 나라 이야기에서 두 나라가 저마다 쌀과 옷을 모두 직접 만들 때보다 무역을 할 때 더 좋은 까닭은 어느 것인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"두 나라 이야기에서 두 나라가 저마다 쌀과 옷을 모두 직접 만들 때보다 무역을 할 때 더 좋은 까닭은 어느 것인가요?","options":[{"t":"저마다 잘 만드는 것에 힘을 모아 더 많이 만들고 서로 바꾸면 두 나라 모두 더 넉넉해지기 때문에","correct":true},{"t":"무역을 하면 한 나라만 이익을 얻기 때문에","mis":"SO6-2-u2-X18"},{"t":"무역을 하면 두 나라 모두 아무것도 만들지 않아도 되기 때문에","mis":"SO6-2-u2-X18"},{"t":"직접 다 만드는 것이 언제나 더 싸기 때문에","mis":"SO6-2-u2-X18"}],"explanation":["㉮는 옷, ㉯는 쌀을 잘 만들어요.","잘 만드는 것에 집중해요.","바꾸면 두 나라 모두 이익이에요."],"asset":{"type":"passage","lines":["㉮ 나라 — 기술 수준이 높아 옷을 잘 만든다. 쌀을 기르기엔 땅이 모자란다.","㉯ 나라 — 넓은 들과 알맞은 기후로 쌀을 잘 기른다. 옷 만드는 기술은 모자란다.","두 나라가 같은 시간과 비용을 들인다고 하자."],"title":"두 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#4','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'mc','auto','흑연과 배터리 이야기에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X17']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"흑연과 배터리 이야기에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 나라가 수입한 자원으로 만든 제품을, 자원을 판 나라가 다시 수입하기도 한다","correct":true},{"t":"자원을 수입하는 나라는 아무것도 수출할 수 없다","mis":"SO6-2-u2-X18"},{"t":"흑연을 캐는 나라는 배터리를 쓰지 않는다","mis":"SO6-2-u2-X18"},{"t":"무역은 한 방향으로만 이루어진다","mis":"SO6-2-u2-X17"}],"explanation":["우리나라는 흑연을 사 와요.","배터리를 만들어 팔아요.","흑연을 판 나라도 전기차를 사 가요."],"asset":{"type":"passage","lines":["과거 — 우리나라는 흑연을 많이 캐는 나라였다.","그 뒤 — 다른 나라에서 값싼 흑연을 수입하며 거의 캐지 않게 되었다.","오늘날 — 수입한 흑연으로 전기차 배터리를 만들어 수출한다.","흑연을 캐는 나라는 그 배터리를 단 전기차를 수입하기도 한다."],"title":"흑연과 배터리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#5','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'ox','auto','같은 거래라도 어느 나라 쪽에서 보느냐에 따라 수입이 되기도 하고 수출이 되기도 해요.',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"ox","stem":"같은 거래라도 어느 나라 쪽에서 보느냐에 따라 수입이 되기도 하고 수출이 되기도 해요.","answer":"O","reason_options":[{"t":"판 나라에서는 수출이고 산 나라에서는 수입이기 때문에","correct":true},{"t":"한 거래는 언제나 수입이거나 언제나 수출이기 때문에","mis":"SO6-2-u2-X17"}],"mis":"SO6-2-u2-X17","explanation":["고려가 인삼을 팔면 고려에선 수출이에요.","송나라에선 같은 거래가 수입이에요.","보는 쪽을 먼저 정해요."],"asset":{"type":"passage","lines":["고려 시대 예성강 하구의 항구 벽란도에는 여러 나라 배가 드나들었다.","송나라 상인 — 비단·약재·서적·악기를 가져와 팔았다.","아라비아 상인 — 보석과 향료를 가져와 팔았다.","다른 나라 상인들은 고려의 인삼·종이·삼베·모시를 사 갔다."],"title":"고려의 무역항 벽란도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#6','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'mc','auto','한 나라 안에서도 만들 수 있는 물자를 다른 나라에서 수입하기도 하는 까닭은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X17']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"mc","stem":"한 나라 안에서도 만들 수 있는 물자를 다른 나라에서 수입하기도 하는 까닭은 어느 것인가요?","options":[{"t":"더 좋은 품질이나 더 싼 값의 물자를 다른 나라에서 구할 수 있어서","correct":true},{"t":"다른 나라 물자는 언제나 더 비싸서","mis":"SO6-2-u2-X18"},{"t":"한 나라 안에서 만든 것은 쓸 수 없어서","mis":"SO6-2-u2-X18"},{"t":"수입을 하면 무역이 아니게 되어서","mis":"SO6-2-u2-X17"}],"explanation":["만들 수 있어도 더 싸거나 좋으면 사 와요.","흑연이 그런 예예요.","그 대신 잘 만드는 것을 팔아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#7','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',3,'error','auto','두 나라 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"error","stem":"두 나라 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하진 — 「㉯ 나라는 기술이 모자라니까 무역에서 얻을 게 없어.」","correct":true,"mis_target":"SO6-2-u2-X18"},{"t":"수빈 — 「㉯ 나라는 쌀을 팔아 이익을 얻을 수 있어.」","mis":"SO6-2-u2-X18"},{"t":"우진 — 「㉮ 나라는 옷을 팔고 쌀을 사 오면 돼.」","mis":"SO6-2-u2-X18"}],"explanation":["㉯ 나라는 쌀을 잘 길러요.","쌀을 팔아 이익을 얻어요.","나라마다 잘 만드는 것이 있어요."],"asset":{"type":"passage","lines":["㉮ 나라 — 기술 수준이 높아 옷을 잘 만든다. 쌀을 기르기엔 땅이 모자란다.","㉯ 나라 — 넓은 들과 알맞은 기후로 쌀을 잘 기른다. 옷 만드는 기술은 모자란다.","두 나라가 같은 시간과 비용을 들인다고 하자."],"title":"두 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#8','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',4,'mc','auto','두 나라 이야기에서 ㉮ 나라가 쌀이 모자란다고 옷 공장을 줄이고 모자란 땅에 쌀을 직접 기르기로 했어요. 이 결정에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"mc","stem":"두 나라 이야기에서 ㉮ 나라가 쌀이 모자란다고 옷 공장을 줄이고 모자란 땅에 쌀을 직접 기르기로 했어요. 이 결정에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 시간과 비용으로 옷을 만들어 팔고 쌀을 사 오는 편이 더 이익이므로 좋은 결정이 아니다","correct":true},{"t":"직접 기르면 무조건 더 이익이므로 좋은 결정이다","mis":"SO6-2-u2-X18"},{"t":"쌀과 옷은 무역할 수 없으므로 어쩔 수 없다","mis":"SO6-2-u2-X18"},{"t":"옷 공장을 줄이면 옷을 더 많이 팔 수 있다","mis":"SO6-2-u2-X18"}],"explanation":["㉮는 쌀 기르기에 알맞지 않아요.","옷을 잘 만드는 힘을 버리게 돼요.","잘 만드는 것을 팔고 사 오는 편이 나아요."],"asset":{"type":"passage","lines":["㉮ 나라 — 기술 수준이 높아 옷을 잘 만든다. 쌀을 기르기엔 땅이 모자란다.","㉯ 나라 — 넓은 들과 알맞은 기후로 쌀을 잘 기른다. 옷 만드는 기술은 모자란다.","두 나라가 같은 시간과 비용을 들인다고 하자."],"title":"두 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#9','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',4,'mc','auto','고려의 벽란도와 오늘날의 무역을 견주어 볼 때 같은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X17']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"mc","stem":"고려의 벽란도와 오늘날의 무역을 견주어 볼 때 같은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라마다 가진 것이 달라 서로 필요한 물자를 사고판다","correct":true},{"t":"오늘날에는 서비스는 무역하지 않는다","mis":"SO6-2-u2-X18"},{"t":"옛날에는 수입만 하고 수출은 하지 않았다","mis":"SO6-2-u2-X17"},{"t":"무역은 한 나라 안에서만 이루어진다","mis":"SO6-2-u2-X18"}],"explanation":["고려는 인삼을 팔고 비단을 샀어요.","오늘날에도 필요한 것을 사고팔아요.","가진 것이 달라 무역해요."],"asset":{"type":"passage","lines":["고려 시대 예성강 하구의 항구 벽란도에는 여러 나라 배가 드나들었다.","송나라 상인 — 비단·약재·서적·악기를 가져와 팔았다.","아라비아 상인 — 보석과 향료를 가져와 팔았다.","다른 나라 상인들은 고려의 인삼·종이·삼베·모시를 사 갔다."],"title":"고려의 무역항 벽란도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L09_challenge#10','soc',6,2,'u2','L09','g6_2_soc_u2_L09_challenge','lesson_challenge','SO6-2-u2-C9',4,'essay','teacher','두 나라 이야기를 보고, ㉮ 나라와 ㉯ 나라가 각각 무엇을 수출하고 무엇을 수입하면 좋을지 쓰고, 그렇게 무역이 이루어지는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"essay","stem":"두 나라 이야기를 보고, ㉮ 나라와 ㉯ 나라가 각각 무엇을 수출하고 무엇을 수입하면 좋을지 쓰고, 그렇게 무역이 이루어지는 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉮ 나라는 기술 수준이 높아 옷을 잘 만드니 옷을 수출하고 쌀을 수입하면 좋다. ㉯ 나라는 넓은 들과 알맞은 기후로 쌀을 잘 기르니 쌀을 수출하고 옷을 수입하면 좋다. 나라마다 자연환경·자원·자본·기술이 달라 더 잘 생산할 수 있는 것이 다르기 때문에, 잘 만드는 것을 수출하고 모자란 것을 수입하면 두 나라 모두 이익을 얻는다.","scoring_points":["㉮ 나라의 수출·수입을 바르게 썼는가","㉯ 나라의 수출·수입을 바르게 썼는가","나라마다 조건이 달라 두 나라 모두 이익이라는 까닭을 썼는가"]},"explanation":["㉮ — 옷 수출, 쌀 수입이에요.","㉯ — 쌀 수출, 옷 수입이에요.","조건이 달라 서로 이익이에요."],"asset":{"type":"passage","lines":["㉮ 나라 — 기술 수준이 높아 옷을 잘 만든다. 쌀을 기르기엔 땅이 모자란다.","㉯ 나라 — 넓은 들과 알맞은 기후로 쌀을 잘 기른다. 옷 만드는 기술은 모자란다.","두 나라가 같은 시간과 비용을 들인다고 하자."],"title":"두 나라 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#1','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'mc','auto','우리나라의 주요 수입품은 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"mc","stem":"우리나라의 주요 수입품은 어느 것인가요?","options":[{"t":"원유","correct":true},{"t":"반도체","mis":"SO6-2-u2-X19"},{"t":"자동차","mis":"SO6-2-u2-X19"},{"t":"무선 통신 기기","mis":"SO6-2-u2-X19"}],"explanation":["우리나라는 천연자원을 주로 수입해요.","원유·천연가스·석탄이 대표적이에요.","반도체·자동차는 수출품이에요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#2','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'mc','auto','우리나라의 주요 수출품은 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"mc","stem":"우리나라의 주요 수출품은 어느 것인가요?","options":[{"t":"반도체","correct":true},{"t":"천연가스","mis":"SO6-2-u2-X19"},{"t":"석탄","mis":"SO6-2-u2-X19"},{"t":"원유","mis":"SO6-2-u2-X19"}],"explanation":["반도체·자동차·석유 제품·무선 통신 기기를 수출해요.","천연가스·석탄·원유는 수입품이에요.","수입한 자원으로 제품을 만들어요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#3','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'ox','auto','원유와 석유 제품은 같은 것이에요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"ox","stem":"원유와 석유 제품은 같은 것이에요.","answer":"X","reason_options":[{"t":"원유는 자연 상태의 석유이고, 석유 제품은 원유에서 분리해 만든 휘발유·경유 같은 연료이기 때문에","correct":true},{"t":"둘 다 땅에서 캐낸 그대로의 석유이기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["원유는 불순물을 없애지 않은 석유예요.","석유 제품은 원유를 가공해 만들어요.","우리나라는 원유를 사 와 석유 제품을 팔아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#4','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',1,'mc','auto','일정한 기간과 장소를 정해 다양한 물품을 전시하는 행사를 무엇이라고 하나요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"mc","stem":"일정한 기간과 장소를 정해 다양한 물품을 전시하는 행사를 무엇이라고 하나요?","options":[{"t":"박람회","correct":true},{"t":"벽란도","mis":"SO6-2-u2-X19"},{"t":"공동 어장","mis":"SO6-2-u2-X19"},{"t":"수상 시장","mis":"SO6-2-u2-X19"}],"explanation":["박람회에서 상품을 전시해요.","판매자와 소비자가 묻고 답해요.","사거나 나중에 살 약속도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#5','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'match','auto','여러 나라의 무역 모습과 그 무역을 가능하게 한 조건을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"match","stem":"여러 나라의 무역 모습과 그 무역을 가능하게 한 조건을 알맞게 이으세요.","pairs":[{"l":"㉠ 쌀 수출","r":"넓은 땅과 쌀 재배에 알맞은 기후"},{"l":"㉡ 원유 수출","r":"땅속에 풍부한 자원"},{"l":"㉢ 백신·로봇 수출","r":"뛰어난 기술"},{"l":"㉣ 큰 항구","r":"항로 길목의 지리적 위치"}],"mis":"SO6-2-u2-X19","explanation":["㉠ 땅과 기후예요.","㉡ 자원, ㉢ 기술이에요.","㉣ 위치예요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#6','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'mc','auto','우리나라가 반도체·자동차 같은 제품을 수출할 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19','SO6-2-u2-X18']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"우리나라가 반도체·자동차 같은 제품을 수출할 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"수입한 자원으로 다양한 상품을 만드는 기술이 발달했기 때문에","correct":true},{"t":"천연자원이 아주 풍부하기 때문에","mis":"SO6-2-u2-X19"},{"t":"땅이 넓어 농사가 잘되기 때문에","mis":"SO6-2-u2-X19"},{"t":"우리나라에서는 이 물건을 쓰지 않기 때문에","mis":"SO6-2-u2-X18"}],"explanation":["우리나라는 자원이 부족해요.","그 대신 기술이 발달했어요.","자원을 사 와 제품을 만들어 팔아요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#7','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'mc','auto','싱가포르에 큰 항구가 생겨 여러 나라 상품이 모이게 된 까닭은 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"싱가포르에 큰 항구가 생겨 여러 나라 상품이 모이게 된 까닭은 어느 것인가요?","options":[{"t":"유럽과 아시아를 잇는 항로에 자리 잡고 있어서","correct":true},{"t":"땅이 매우 넓어서","mis":"SO6-2-u2-X19"},{"t":"쌀이 많이 나서","mis":"SO6-2-u2-X19"},{"t":"원유가 풍부해서","mis":"SO6-2-u2-X19"}],"explanation":["싱가포르는 바닷길의 길목에 있어요.","지나는 배가 쉬어 가요.","상품이 모였다가 필요한 나라로 가요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#8','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'ox','auto','뛰어난 기술로 만든 제품이나 문화 상품을 수출하는 나라도 있어요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"ox","stem":"뛰어난 기술로 만든 제품이나 문화 상품을 수출하는 나라도 있어요.","answer":"O","reason_options":[{"t":"자원이나 땅이 아니어도 기술과 문화가 경쟁력이 될 수 있기 때문에","correct":true},{"t":"수출은 자원이 많은 나라만 할 수 있기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["독일은 백신, 일본은 로봇을 수출해요.","우리 드라마·음악도 수출해요.","기술과 문화도 무역의 힘이에요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#9','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',2,'mc','auto','우리나라 무역의 특징을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19','SO6-2-u2-X18']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"우리나라 무역의 특징을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"천연자원을 수입한 뒤 상품을 만들어 수출한다","correct":true},{"t":"완성된 자동차를 수입한 뒤 천연자원을 수출한다","mis":"SO6-2-u2-X19"},{"t":"쌀을 가장 많이 수출한다","mis":"SO6-2-u2-X19"},{"t":"무역을 거의 하지 않는다","mis":"SO6-2-u2-X18"}],"explanation":["자원은 들여와요.","기술로 상품을 만들어요.","만든 상품을 내보내요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_basic#10','soc',6,2,'u2','L11','g6_2_soc_u2_L11_basic','lesson_basic','SO6-2-u2-C10',3,'error','auto','여러 나라의 무역 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"error","stem":"여러 나라의 무역 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「싱가포르는 땅이 넓어 쌀을 많이 수출하는 나라야.」","correct":true,"mis_target":"SO6-2-u2-X19"},{"t":"다인 — 「사우디아라비아는 풍부한 원유를 수출해.」","mis":"SO6-2-u2-X19"},{"t":"준혁 — 「독일은 백신을 만드는 기술이 발달했어.」","mis":"SO6-2-u2-X19"}],"explanation":["싱가포르는 위치를 활용한 무역을 해요.","쌀을 많이 수출하는 나라는 인도·타이·베트남이에요.","조건과 무역 모습을 바르게 짝지어요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#1','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',2,'sa','auto','우리나라의 주요 수입품 가운데 불순물을 없애지 않은 자연 상태의 석유를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"sa","stem":"우리나라의 주요 수입품 가운데 불순물을 없애지 않은 자연 상태의 석유를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["원유"],"explanation":["원유는 자연 상태의 석유예요.","우리나라는 원유를 수입해요.","가공한 석유 제품은 수출해요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"},"mis":"SO6-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#2','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',2,'mc','auto','쌀을 많이 수출하는 나라들이 가졌을 조건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"쌀을 많이 수출하는 나라들이 가졌을 조건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쌀을 기를 넓은 땅과 쌀 재배에 알맞은 기후","correct":true},{"t":"항로 길목의 큰 항구","mis":"SO6-2-u2-X19"},{"t":"로봇을 만드는 뛰어난 기술","mis":"SO6-2-u2-X19"},{"t":"땅속의 풍부한 원유","mis":"SO6-2-u2-X19"}],"explanation":["쌀은 넓은 땅이 필요해요.","알맞은 기후도 필요해요.","그래서 농산물을 수출해요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#3','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'mc','auto','우리나라가 원유를 수입하면서 동시에 석유 제품을 수출할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"mc","stem":"우리나라가 원유를 수입하면서 동시에 석유 제품을 수출할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"수입한 원유를 기술로 가공해 휘발유·경유 같은 제품으로 만들 수 있기 때문에","correct":true},{"t":"원유와 석유 제품은 같은 것이라 그대로 되팔기 때문에","mis":"SO6-2-u2-X19"},{"t":"우리나라 땅속에서 원유가 많이 나기 때문에","mis":"SO6-2-u2-X19"},{"t":"석유 제품은 수출할 수 없기 때문에","mis":"SO6-2-u2-X19"}],"explanation":["원유는 원료예요.","가공하면 석유 제품이 돼요.","기술이 더한 값을 팔아요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#4','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'mc','auto','나라마다 무역의 모습이 다른 까닭을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"mc","stem":"나라마다 무역의 모습이 다른 까닭을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"자연환경·자원·자본·기술·위치 같은 조건이 나라마다 달라 잘 만들거나 잘할 수 있는 것이 다르기 때문에","correct":true},{"t":"나라마다 무역을 하는 날이 다르기 때문에","mis":"SO6-2-u2-X18"},{"t":"모든 나라가 같은 물건만 사고팔기 때문에","mis":"SO6-2-u2-X18"},{"t":"무역은 나라 크기로만 정해지기 때문에","mis":"SO6-2-u2-X19"}],"explanation":["땅·기후·자원·기술·위치가 달라요.","그래서 잘하는 것도 달라요.","무역의 모습도 달라져요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#5','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'ox','auto','박람회에서는 판매자와 소비자가 직접 묻고 답하며 상품을 사거나 나중에 살 것을 약속하기도 해요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"ox","stem":"박람회에서는 판매자와 소비자가 직접 묻고 답하며 상품을 사거나 나중에 살 것을 약속하기도 해요.","answer":"O","reason_options":[{"t":"박람회는 상품을 알리고 거래가 이루어지는 자리이기 때문에","correct":true},{"t":"박람회는 상품을 구경만 하고 거래는 할 수 없는 곳이기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["박람회는 상품을 알리는 자리예요.","직접 묻고 답해요.","거래도 이루어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#6','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'mc','auto','싱가포르처럼 자원이나 땅이 부족한 나라가 무역으로 이익을 얻는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19','SO6-2-u2-X18']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"mc","stem":"싱가포르처럼 자원이나 땅이 부족한 나라가 무역으로 이익을 얻는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"바닷길 길목이라는 위치를 활용해 항구에 상품을 모았다가 필요한 나라로 보낸다","correct":true},{"t":"땅을 넓혀 쌀을 많이 기른다","mis":"SO6-2-u2-X19"},{"t":"땅속 원유를 캐서 판다","mis":"SO6-2-u2-X19"},{"t":"무역을 하지 않고 모두 직접 만든다","mis":"SO6-2-u2-X18"}],"explanation":["싱가포르는 위치가 좋아요.","배들이 쉬어 가요.","상품이 모이고 다시 나가요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#7','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',3,'error','auto','우리나라의 수출품과 수입품을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"error","stem":"우리나라의 수출품과 수입품을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시아 — 「우리나라는 자원이 많아서 석탄을 주로 수출해.」","correct":true,"mis_target":"SO6-2-u2-X19"},{"t":"규리 — 「우리나라는 원유와 천연가스를 주로 수입해.」","mis":"SO6-2-u2-X19"},{"t":"찬 — 「무선 통신 기기는 우리나라의 주요 수출품이야.」","mis":"SO6-2-u2-X19"}],"explanation":["석탄은 주요 수입품이에요.","우리나라는 자원이 부족해요.","기술로 만든 제품을 수출해요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#8','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',4,'mc','auto','어느 나라가 땅이 좁고 자원도 거의 없지만 교육 수준이 높아 기술자가 많아요. 이 나라가 택할 무역 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19','SO6-2-u2-X18']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C10","difficulty":4,"kind":"mc","stem":"어느 나라가 땅이 좁고 자원도 거의 없지만 교육 수준이 높아 기술자가 많아요. 이 나라가 택할 무역 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자원을 수입해 뛰어난 기술로 첨단 제품을 만들어 수출한다","correct":true},{"t":"넓은 땅이 필요한 쌀을 수출한다","mis":"SO6-2-u2-X19"},{"t":"땅속 자원을 캐서 수출한다","mis":"SO6-2-u2-X19"},{"t":"무역을 끊고 필요한 것을 모두 직접 만든다","mis":"SO6-2-u2-X18"}],"explanation":["땅과 자원은 부족해요.","기술이 강점이에요.","우리나라와 비슷한 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#9','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',4,'mc','auto','우리나라의 수출품과 수입품을 보고 우리나라 무역에 대해 말할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X19','SO6-2-u2-X17']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C10","difficulty":4,"kind":"mc","stem":"우리나라의 수출품과 수입품을 보고 우리나라 무역에 대해 말할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자원이 들어오지 않으면 제품도 만들기 어려우니, 우리나라 무역은 다른 나라와 깊이 이어져 있다","correct":true},{"t":"우리나라는 다른 나라 없이도 모든 제품을 만들 수 있다","mis":"SO6-2-u2-X18"},{"t":"수입품과 수출품은 서로 아무 관계가 없다","mis":"SO6-2-u2-X19"},{"t":"우리나라는 수입만 하고 수출은 하지 않는다","mis":"SO6-2-u2-X17"}],"explanation":["원유가 들어와야 석유 제품을 만들어요.","수입과 수출이 이어져 있어요.","다른 나라와 깊이 기대고 있어요."],"asset":{"type":"passage","lines":["주요 수출품 — 반도체 · 자동차 · 석유 제품 · 무선 통신 기기","주요 수입품 — 원유 · 천연가스 · 석탄 · 정밀 화학 원료"],"title":"우리나라의 주요 수출품과 수입품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L11_challenge#10','soc',6,2,'u2','L11','g6_2_soc_u2_L11_challenge','lesson_challenge','SO6-2-u2-C10',4,'essay','teacher','여러 나라의 무역 모습 ㉠~㉣ 가운데 두 가지를 골라 각 나라가 그런 무역을 하는 까닭을 쓰고, 우리나라의 무역 모습은 그 가운데 어느 쪽에 더 가까운지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C10","difficulty":4,"kind":"essay","stem":"여러 나라의 무역 모습 ㉠~㉣ 가운데 두 가지를 골라 각 나라가 그런 무역을 하는 까닭을 쓰고, 우리나라의 무역 모습은 그 가운데 어느 쪽에 더 가까운지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ㉡ 사우디아라비아는 땅속에 원유가 풍부해서 원유를 많이 수출한다. ㉢ 독일과 일본은 기술이 뛰어나 백신과 로봇 같은 첨단 제품을 수출한다. 우리나라는 원유 같은 자원을 수입하고 기술로 반도체·자동차를 만들어 수출하므로 ㉢에 더 가깝다.","scoring_points":["두 나라의 무역 모습과 까닭을 바르게 썼는가","나라의 조건(자원·기술·땅·위치)과 이었는가","우리나라가 기술 쪽에 가깝다는 것을 까닭과 함께 썼는가"]},"explanation":["조건이 무역 모습을 정해요.","자원·기술·땅·위치를 봐요.","우리나라는 기술로 수출해요."],"asset":{"type":"passage","lines":["㉠ 인도·타이·베트남 — 쌀을 많이 수출한다.","㉡ 사우디아라비아 — 원유를 많이 수출한다.","㉢ 독일 — 백신을, 일본 — 로봇을 수출한다.","㉣ 싱가포르 — 큰 항구에 여러 나라 상품이 모였다가 다시 나간다."],"title":"여러 나라의 무역 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#1','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'mc','auto','다른 나라에서 수입하는 상품에 매기는 세금을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"mc","stem":"다른 나라에서 수입하는 상품에 매기는 세금을 무엇이라고 하나요?","options":[{"t":"관세","correct":true},{"t":"이윤","mis":"SO6-2-u2-X20"},{"t":"급여","mis":"SO6-2-u2-X20"},{"t":"소득","mis":"SO6-2-u2-X20"}],"explanation":["관세는 수입품에 매기는 세금이에요.","관세가 높으면 수입품이 비싸져요.","국내 산업을 보호할 때 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#2','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'mc','auto','여러 나라의 우수한 부품을 모아 스마트폰을 만드는 것은 어떤 관계를 보여 주나요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X07','SO6-2-u2-X14']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"mc","stem":"여러 나라의 우수한 부품을 모아 스마트폰을 만드는 것은 어떤 관계를 보여 주나요?","options":[{"t":"상호 의존 관계","correct":true},{"t":"경쟁 관계","mis":"SO6-2-u2-X20"},{"t":"아무 관계도 아님","mis":"SO6-2-u2-X07"},{"t":"빈부 격차","mis":"SO6-2-u2-X14"}],"explanation":["여러 나라가 부품을 주고받아요.","서로 기대어 하나의 제품을 만들어요.","이것이 상호 의존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#3','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',1,'ox','auto','수출이 늘어나면 더 많이 생산해야 하므로 산업이 성장하고 일자리와 소득이 늘어나요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"ox","stem":"수출이 늘어나면 더 많이 생산해야 하므로 산업이 성장하고 일자리와 소득이 늘어나요.","answer":"O","reason_options":[{"t":"팔 곳이 늘면 만들 것이 늘어 일할 사람과 소득도 함께 늘기 때문에","correct":true},{"t":"수출이 늘면 만들 것이 줄어들기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["수출 → 더 많이 생산해요.","산업이 성장해요.","일자리와 소득이 늘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#4','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C12',1,'mc','auto','기업 운영 계획에서 대표 상품에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X21']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C12","difficulty":1,"kind":"mc","stem":"기업 운영 계획에서 대표 상품에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"물건뿐 아니라 배달 서비스 같은 서비스도 대표 상품이 될 수 있다","correct":true},{"t":"대표 상품은 손으로 만질 수 있는 물건만 된다","mis":"SO6-2-u2-X18"},{"t":"대표 상품은 다른 기업의 상품에서 고른다","mis":"SO6-2-u2-X21"},{"t":"대표 상품은 정하지 않아도 된다","mis":"SO6-2-u2-X21"}],"explanation":["게임도, 배달 서비스도 상품이에요.","우리 기업이 알리고 싶은 것을 정해요.","특징도 함께 정해요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#5','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','수입 철강에 높은 관세를 매긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"수입 철강에 높은 관세를 매긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라에서 만든 철강이 시장에서 경쟁력을 갖추게 하려고","correct":true},{"t":"수입 철강이 더 잘 팔리게 하려고","mis":"SO6-2-u2-X20"},{"t":"철강을 아무도 쓰지 않게 하려고","mis":"SO6-2-u2-X20"},{"t":"다른 나라와 무역을 모두 멈추려고","mis":"SO6-2-u2-X20"}],"explanation":["관세가 붙으면 수입 철강이 비싸져요.","우리 철강이 상대적으로 잘 팔려요.","그 사이 우리 제철소가 자랐어요."],"asset":{"type":"passage","lines":["예전 우리나라는 제철소를 막 짓기 시작했다.","외국의 값싼 철강이 많이 들어와 우리 제철소가 어려웠다.","정부는 수입 철강에 높은 관세를 매겼다.","오늘날 우리나라는 세계적인 철강 산업 국가가 되었다."],"title":"우리 철강 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#6','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','여러 나라가 자동화 항만 시스템을 갖추려고 하는 것은 무엇을 두고 하는 경쟁인가요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X16']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"여러 나라가 자동화 항만 시스템을 갖추려고 하는 것은 무엇을 두고 하는 경쟁인가요?","options":[{"t":"더 나은 무역 환경","correct":true},{"t":"쌀을 더 많이 기르는 것","mis":"SO6-2-u2-X20"},{"t":"다른 나라의 다리를 짓는 것","mis":"SO6-2-u2-X20"},{"t":"공동 어장의 물고기","mis":"SO6-2-u2-X16"}],"explanation":["항만은 배가 물건을 싣고 내리는 곳이에요.","빠르고 편리할수록 배가 모여요.","무역 환경을 두고 경쟁해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#7','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'mc','auto','베트남으로 가는 기업에 나온 조건 가운데 베트남의 위치와 관계있는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"베트남으로 가는 기업에 나온 조건 가운데 베트남의 위치와 관계있는 것은 어느 것인가요?","options":[{"t":"큰 시장인 중국과 국경을 맞대고 있다","correct":true},{"t":"노동력이 비교적 저렴하다","mis":"SO6-2-u2-X20"},{"t":"베트남 제품에 낮은 관세를 매기기로 약속한 나라가 많다","mis":"SO6-2-u2-X20"},{"t":"공장을 짓는 기업이 많다","mis":"SO6-2-u2-X20"}],"explanation":["국경을 맞댄 것은 위치예요.","만든 물건을 가까운 큰 시장에 보내기 쉬워요.","노동력·관세는 다른 조건이에요."],"asset":{"type":"passage","lines":["여러 외국 기업이 베트남에 공장을 짓고 있다.","· 노동력이 비교적 저렴하다.","· 큰 시장인 중국과 국경을 맞대고 있다.","· 베트남 제품에 낮은 관세를 매기기로 약속한 나라가 많다."],"title":"베트남으로 가는 기업"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#8','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C12',2,'match','auto','기업 소개 잡지 표지 계획의 칸과 그 칸에 담긴 기업의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C12","difficulty":2,"kind":"match","stem":"기업 소개 잡지 표지 계획의 칸과 그 칸에 담긴 기업의 모습을 알맞게 이으세요.","pairs":[{"l":"주요 수출국","r":"상품이 필요할 만한 나라를 조사해 고른 모습"},{"l":"목표","r":"사회적 책임을 다하려는 모습"},{"l":"근로자를 위한 노력","r":"근로자의 권리를 보호하려는 모습"}],"mis":"SO6-2-u2-X21","explanation":["수출국은 조사로 골라요.","목표에는 사회적 책임을 담아요.","노력에는 근로자 권리 보호를 담아요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#9','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',2,'ox','auto','무역으로 세계 여러 나라는 서로 의존하기만 하고 경쟁하지는 않아요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"ox","stem":"무역으로 세계 여러 나라는 서로 의존하기만 하고 경쟁하지는 않아요.","answer":"X","reason_options":[{"t":"물자와 기술을 주고받으며 의존하면서도 첨단 기술·시설 건설·무역 환경을 두고 경쟁하기 때문에","correct":true},{"t":"나라끼리는 언제나 돕기만 하기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["부품을 주고받는 것은 의존이에요.","기술을 먼저 개발하려는 것은 경쟁이에요.","두 관계가 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_basic#10','soc',6,2,'u2','L12','g6_2_soc_u2_L12_basic','lesson_basic','SO6-2-u2-C11',3,'error','auto','우리 철강 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"error","stem":"우리 철강 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「관세를 매기면 좋은 점만 있고 걱정할 건 하나도 없어.」","correct":true,"mis_target":"SO6-2-u2-X20"},{"t":"도겸 — 「관세 덕분에 우리 제철소가 자랄 시간을 얻었어.」","mis":"SO6-2-u2-X20"},{"t":"새봄 — 「관세가 붙으면 수입 철강을 사는 사람은 더 비싸게 사.」","mis":"SO6-2-u2-X20"}],"explanation":["관세는 국내 산업을 보호해요.","하지만 수입품을 사는 쪽은 더 비싸게 사요.","두 쪽 영향을 함께 봐요."],"asset":{"type":"passage","lines":["예전 우리나라는 제철소를 막 짓기 시작했다.","외국의 값싼 철강이 많이 들어와 우리 제철소가 어려웠다.","정부는 수입 철강에 높은 관세를 매겼다.","오늘날 우리나라는 세계적인 철강 산업 국가가 되었다."],"title":"우리 철강 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#1','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',2,'mc','auto','우리나라와 인도네시아가 핵심 광물 연구 개발에 협력할 때 인도네시아가 얻는 이익으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X18']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C11","difficulty":2,"kind":"mc","stem":"우리나라와 인도네시아가 핵심 광물 연구 개발에 협력할 때 인도네시아가 얻는 이익으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라의 뛰어난 광물 탐사 기술로 자원을 효율적으로 개발할 수 있다","correct":true},{"t":"우리나라의 광물을 모두 가져갈 수 있다","mis":"SO6-2-u2-X20"},{"t":"무역을 하지 않아도 된다","mis":"SO6-2-u2-X18"},{"t":"우리나라에 광물을 팔지 않아도 된다","mis":"SO6-2-u2-X20"}],"explanation":["인도네시아는 기술을 얻어요.","우리나라는 자원을 안정적으로 얻어요.","서로 의존하는 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#2','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C12',2,'sa','auto','기업 소개 잡지 표지 계획에서 △△ 게임 회사가 주요 수출국을 고른 기준은 그 나라의 무엇이 많아서인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-2-u2-C12","difficulty":2,"kind":"sa","stem":"기업 소개 잡지 표지 계획에서 △△ 게임 회사가 주요 수출국을 고른 기준은 그 나라의 무엇이 많아서인가요? 두 글자로 쓰세요.","answer":["인구"],"explanation":["인구가 많으면 게임을 즐길 사람도 많아요.","상품이 필요할 만한 나라를 골라요.","조사한 내용으로 까닭을 말해요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"},"mis":"SO6-2-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#3','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'mc','auto','수입이 늘어날 때 생기는 일을 두 쪽 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"수입이 늘어날 때 생기는 일을 두 쪽 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"국내에서 얻기 힘든 물자를 쓸 수 있어 생활이 편리해지지만, 같은 상품을 만드는 국내 기업이 어려워질 수 있다","correct":true},{"t":"생활이 편리해지기만 하고 걱정할 것은 없다","mis":"SO6-2-u2-X20"},{"t":"국내 기업이 어려워지기만 하고 좋은 점은 없다","mis":"SO6-2-u2-X20"},{"t":"수입은 생활과 아무 관계가 없다","mis":"SO6-2-u2-X18"}],"explanation":["수입품으로 생활이 편리해져요.","하지만 국내 기업은 경쟁이 힘들어져요.","두 쪽을 함께 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#4','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'mc','auto','베트남으로 가는 기업 이야기에서 베트남에서 만든 제품을 사는 세계 사람들이 얻는 이익은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"베트남으로 가는 기업 이야기에서 베트남에서 만든 제품을 사는 세계 사람들이 얻는 이익은 어느 것인가요?","options":[{"t":"기존보다 저렴한 가격으로 더 다양한 제품을 살 수 있다","correct":true},{"t":"제품을 전혀 살 수 없게 된다","mis":"SO6-2-u2-X20"},{"t":"한 가지 제품만 살 수 있다","mis":"SO6-2-u2-X20"},{"t":"제품 가격이 언제나 더 비싸진다","mis":"SO6-2-u2-X20"}],"explanation":["생산 비용이 낮아져요.","값이 싸지고 종류가 늘어요.","베트남 사람들은 일자리를 얻어요."],"asset":{"type":"passage","lines":["여러 외국 기업이 베트남에 공장을 짓고 있다.","· 노동력이 비교적 저렴하다.","· 큰 시장인 중국과 국경을 맞대고 있다.","· 베트남 제품에 낮은 관세를 매기기로 약속한 나라가 많다."],"title":"베트남으로 가는 기업"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#5','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'ox','auto','한 기업이 여러 나라에 공장을 운영할 때는 그 나라 근로자가 정당한 임금을 받는지, 환경이 오염되지 않는지도 살펴야 해요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"ox","stem":"한 기업이 여러 나라에 공장을 운영할 때는 그 나라 근로자가 정당한 임금을 받는지, 환경이 오염되지 않는지도 살펴야 해요.","answer":"O","reason_options":[{"t":"기업이 얻는 이익에 비해 근로자가 정당한 몫을 받지 못하거나 환경이 오염되는 문제가 생기기도 하기 때문에","correct":true},{"t":"다른 나라 공장은 그 나라의 일이라 기업과 관계가 없기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["해외 생산은 좋은 점이 많아요.","하지만 임금·환경 문제가 생길 수 있어요.","정당한 분배가 이루어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#6','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',3,'mc','auto','다음 가운데 무역을 통한 「경쟁 관계」를 보여 주는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"다음 가운데 무역을 통한 「경쟁 관계」를 보여 주는 것은 어느 것인가요?","options":[{"t":"여러 나라가 생성형 인공지능을 먼저 개발하려고 힘쓴다","correct":true},{"t":"여러 나라의 부품을 모아 스마트폰을 만든다","mis":"SO6-2-u2-X20"},{"t":"광물 탐사 기술과 자원을 서로 나눈다","mis":"SO6-2-u2-X20"},{"t":"흑연을 수입해 배터리를 만들어 판다","mis":"SO6-2-u2-X20"}],"explanation":["먼저 차지하려는 것은 경쟁이에요.","함께 만드는 것은 의존이에요.","두 관계를 가려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#7','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C12',3,'error','auto','기업 운영 계획을 세우며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C12","difficulty":3,"kind":"error","stem":"기업 운영 계획을 세우며 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"가람 — 「목표에는 이윤을 많이 남기는 것만 적으면 충분해.」","correct":true,"mis_target":"SO6-2-u2-X21"},{"t":"나래 — 「환경을 지키며 성장하는 목표도 넣자.」","mis":"SO6-2-u2-X21"},{"t":"솔 — 「근로자에게 휴가를 보장하는 노력을 적자.」","mis":"SO6-2-u2-X21"}],"explanation":["이윤만 적으면 기업의 특징이 잘 드러나지 않아요.","사회적 책임 목표를 함께 담아요.","근로자를 위한 노력도 담아요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#8','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C11',4,'mc','auto','우리 철강 이야기와 오늘날의 무역을 함께 볼 때 관세에 대해 가장 알맞게 판단한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"mc","stem":"우리 철강 이야기와 오늘날의 무역을 함께 볼 때 관세에 대해 가장 알맞게 판단한 것은 어느 것인가요?","options":[{"t":"자라는 국내 산업을 보호하는 데 도움이 될 수 있지만, 수입품을 비싸게 사는 사람과 상대 나라와의 관계도 함께 생각해야 한다","correct":true},{"t":"관세는 높을수록 언제나 좋다","mis":"SO6-2-u2-X20"},{"t":"관세는 언제나 나쁘니 모두 없애야 한다","mis":"SO6-2-u2-X20"},{"t":"관세는 수출품에 매기는 세금이다","mis":"SO6-2-u2-X20"}],"explanation":["관세는 국내 산업을 지켜 줄 수 있어요.","소비자와 상대 나라에는 부담이 될 수 있어요.","여러 쪽을 함께 따져요."],"asset":{"type":"passage","lines":["예전 우리나라는 제철소를 막 짓기 시작했다.","외국의 값싼 철강이 많이 들어와 우리 제철소가 어려웠다.","정부는 수입 철강에 높은 관세를 매겼다.","오늘날 우리나라는 세계적인 철강 산업 국가가 되었다."],"title":"우리 철강 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#9','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C12',4,'mc','auto','△△ 게임 회사의 게임이 여러 나라에 많이 팔리게 되면 우리나라에 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C12","difficulty":4,"kind":"mc","stem":"△△ 게임 회사의 게임이 여러 나라에 많이 팔리게 되면 우리나라에 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"게임을 더 많이 만들어야 하므로 관련 산업이 성장하고 일자리와 소득이 늘어난다","correct":true},{"t":"일자리가 줄어든다","mis":"SO6-2-u2-X20"},{"t":"관련 산업이 작아진다","mis":"SO6-2-u2-X20"},{"t":"게임을 덜 만들어도 된다","mis":"SO6-2-u2-X20"}],"explanation":["수출이 늘면 생산이 늘어요.","관련 산업이 성장해요.","일자리와 소득이 늘어요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_L12_challenge#10','soc',6,2,'u2','L12','g6_2_soc_u2_L12_challenge','lesson_challenge','SO6-2-u2-C12',4,'essay','teacher','내가 기업의 대표가 되었다고 생각하고, 대표 상품과 주요 수출국(고른 까닭 포함)을 정한 뒤, 사회적 책임을 다하는 목표와 근로자를 위한 노력을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-2-u2-C12","difficulty":4,"kind":"essay","stem":"내가 기업의 대표가 되었다고 생각하고, 대표 상품과 주요 수출국(고른 까닭 포함)을 정한 뒤, 사회적 책임을 다하는 목표와 근로자를 위한 노력을 하나씩 쓰세요.","answer_guide":{"answer":"예: 대표 상품은 집 앞까지 필요한 물건을 빠르게 배달해 주는 서비스이다. 인구가 많고 도시가 넓어 배달이 필요한 사람이 많을 것 같은 인도에 수출하고 싶다. 목표는 「전기 오토바이로 배달해 환경을 지키며 매년 성장하는 기업」이다. 근로자에게는 휴가를 보장하고 매주 대화의 시간을 가져 일하고 싶은 근로 환경을 만들겠다.","scoring_points":["대표 상품을 정했는가","수출국과 고른 까닭을 썼는가","사회적 책임 목표와 근로자를 위한 노력을 썼는가"]},"explanation":["상품 → 수출국 → 목표 → 노력이에요.","수출국은 조사해 골라요.","책임과 근로자를 함께 담아요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#1','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C1',1,'mc','auto','전통 시장·대형 할인점·온라인 쇼핑의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X01','SO6-2-u2-X03','SO6-2-u2-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"전통 시장·대형 할인점·온라인 쇼핑의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건이나 서비스의 거래가 이루어지는 시장이다","correct":true},{"t":"모두 건물이 있는 곳이다","mis":"SO6-2-u2-X01"},{"t":"모두 물건을 만드는 곳이다","mis":"SO6-2-u2-X03"},{"t":"모두 나라가 운영하는 곳이다","mis":"SO6-2-u2-X02"}],"explanation":["세 곳 모두 거래가 이루어져요.","그래서 모두 시장이에요.","건물이 없는 온라인도 시장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#2','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C2',1,'mc','auto','가계가 소득으로 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"가계가 소득으로 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"기업이 만든 물건이나 서비스를 소비한다","correct":true},{"t":"근로자를 고용한다","mis":"SO6-2-u2-X03"},{"t":"물건을 생산해 이윤을 얻는다","mis":"SO6-2-u2-X03"},{"t":"나라에 관세를 매긴다","mis":"SO6-2-u2-X03"}],"explanation":["가계는 소득을 얻어요.","그 소득으로 소비해요.","고용과 생산은 기업의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#3','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C3',1,'mc','auto','근로자가 더 나은 근로 조건을 만들려고 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"근로자가 더 나은 근로 조건을 만들려고 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"근로자 단체를 만들거나 가입한다","correct":true},{"t":"기업과 이야기하지 않는다","mis":"SO6-2-u2-X06"},{"t":"휴가를 스스로 포기한다","mis":"SO6-2-u2-X06"},{"t":"혼자서만 몰래 불평한다","mis":"SO6-2-u2-X06"}],"explanation":["근로자는 단체를 만들 수 있어요.","단체를 통해 협의해요.","법이 이 권리를 보장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#4','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C4',1,'mc','auto','우리나라에서 기업의 자유를 보장하는 것은 무엇인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라에서 기업의 자유를 보장하는 것은 무엇인가요?","options":[{"t":"헌법","correct":true},{"t":"관세","mis":"SO6-2-u2-X08"},{"t":"박람회","mis":"SO6-2-u2-X08"},{"t":"공동 어장","mis":"SO6-2-u2-X08"}],"explanation":["헌법은 나라의 가장 기본 법이에요.","기업의 자유를 보장해요.","책임도 함께 따라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#5','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C5',1,'mc','auto','우리나라가 1970년대부터 발달시킨 공업은 어느 것인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"우리나라가 1970년대부터 발달시킨 공업은 어느 것인가요?","options":[{"t":"철강·배·석유 화학 같은 중화학 공업","correct":true},{"t":"옷·신발·가발 같은 경공업","mis":"SO6-2-u2-X11"},{"t":"음악·게임·웹툰 같은 문화 산업","mis":"SO6-2-u2-X11"},{"t":"쌀·채소 같은 농업","mis":"SO6-2-u2-X11"}],"explanation":["1960년대는 경공업이에요.","1970년대는 중화학 공업이에요.","오늘날은 첨단 산업과 문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#6','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C6',1,'mc','auto','경제가 성장하면서 높아진 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C6","difficulty":1,"kind":"mc","stem":"경제가 성장하면서 높아진 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람들의 삶의 질","correct":true},{"t":"빈곤 위험에 처한 사람의 비율만","mis":"SO6-2-u2-X12"},{"t":"물건을 만드는 데 드는 힘","mis":"SO6-2-u2-X13"},{"t":"병을 고치기 어려운 정도","mis":"SO6-2-u2-X13"}],"explanation":["교육·의료·문화가 좋아졌어요.","생활이 편리해졌어요.","삶의 질이 높아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#7','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C9',1,'mc','auto','고려 시대에 여러 나라 상인이 드나들던 무역항은 어디인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"고려 시대에 여러 나라 상인이 드나들던 무역항은 어디인가요?","options":[{"t":"벽란도","correct":true},{"t":"싱가포르","mis":"SO6-2-u2-X19"},{"t":"부산항","mis":"SO6-2-u2-X19"},{"t":"한강","mis":"SO6-2-u2-X19"}],"explanation":["예성강 하구에 있었어요.","송나라·아라비아 상인이 왔어요.","고려도 무역이 활발했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#8','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C10',1,'mc','auto','우리나라가 주로 수입하는 것은 어느 갈래의 물자인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C10","difficulty":1,"kind":"mc","stem":"우리나라가 주로 수입하는 것은 어느 갈래의 물자인가요?","options":[{"t":"원유·천연가스·석탄 같은 천연자원","correct":true},{"t":"반도체 같은 첨단 제품","mis":"SO6-2-u2-X19"},{"t":"자동차 같은 완제품","mis":"SO6-2-u2-X19"},{"t":"드라마 같은 문화 상품","mis":"SO6-2-u2-X19"}],"explanation":["우리나라는 자원이 부족해요.","천연자원을 수입해요.","제품은 만들어 수출해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#9','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C1',2,'mc','auto','솔빛 신문 ①에서 올해 딸기 가격은 어떻게 될까요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"솔빛 신문 ①에서 올해 딸기 가격은 어떻게 될까요?","options":[{"t":"지난해보다 싸질 것이다","correct":true},{"t":"지난해보다 비싸질 것이다","mis":"SO6-2-u2-X02"},{"t":"지난해와 똑같을 것이다","mis":"SO6-2-u2-X02"},{"t":"딸기 농장 한 곳이 정할 것이다","mis":"SO6-2-u2-X02"}],"explanation":["나온 딸기가 크게 늘었어요.","사려는 사람은 비슷해요.","그래서 가격이 싸져요."],"asset":{"type":"passage","lines":["올해 마을에 딸기 농장이 늘어 시장에 딸기가 아주 많이 나왔다.","딸기를 사려는 사람은 지난해와 비슷하다.","딸기 가게들은 손님을 끌려고 더 달고 싱싱한 딸기를 내놓는다."],"title":"솔빛 신문 ① 딸기 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#10','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C2',2,'mc','auto','솔빛 신문 ②에서 빵 공장이 가계에 준 것은 무엇인가요?',ARRAY['SO6-2-u2-X03','SO6-2-u2-X20']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"솔빛 신문 ②에서 빵 공장이 가계에 준 것은 무엇인가요?","options":[{"t":"일자리와 급여","correct":true},{"t":"물건값","mis":"SO6-2-u2-X03"},{"t":"노동력","mis":"SO6-2-u2-X03"},{"t":"관세","mis":"SO6-2-u2-X20"}],"explanation":["공장이 일손을 뽑았어요.","주민은 일자리를 얻었어요.","그 대가로 급여를 받아요."],"asset":{"type":"passage","lines":["마을 빵 공장이 일손을 열 명 더 뽑았다.","일자리를 얻은 주민들은 받은 급여로 마을 가게에서 장을 본다.","가게 주인들은 손님이 늘었다며 반긴다."],"title":"솔빛 신문 ② 빵 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#11','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C3',2,'mc','auto','솔빛 신문 ③에서 근로자들이 누린 권리는 어느 것인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X20']::text[],false,'{"seq":11,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"mc","stem":"솔빛 신문 ③에서 근로자들이 누린 권리는 어느 것인가요?","options":[{"t":"근로자 단체를 통해 기업과 근로 조건을 협의하는 권리","correct":true},{"t":"기업 대신 빵 가격을 정하는 권리","mis":"SO6-2-u2-X06"},{"t":"일하지 않고 급여를 받는 권리","mis":"SO6-2-u2-X06"},{"t":"수입 빵에 관세를 매기는 권리","mis":"SO6-2-u2-X20"}],"explanation":["단체를 통해 이야기했어요.","마주 앉아 협의했어요.","휴게실을 넓히기로 했어요."],"asset":{"type":"passage","lines":["빵 공장 근로자들이 근로자 단체를 통해 쉬는 시간을 늘려 달라고 했다.","공장과 근로자가 마주 앉아 이야기한 끝에 휴게실을 넓히기로 했다.","근로자들은 더 즐겁게 일하게 되었다고 말했다."],"title":"솔빛 신문 ③ 휴게실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#12','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C5',2,'mc','auto','우리나라 경제성장 과정을 차례대로 바르게 나타낸 것은 어느 것인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"우리나라 경제성장 과정을 차례대로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"경공업 제품 수출 → 중화학 공업 발달 → 서울 올림픽 개최 → 반도체·문화 콘텐츠 수출","correct":true},{"t":"중화학 공업 발달 → 경공업 제품 수출 → 서울 올림픽 개최 → 반도체·문화 콘텐츠 수출","mis":"SO6-2-u2-X11"},{"t":"서울 올림픽 개최 → 경공업 제품 수출 → 중화학 공업 발달 → 반도체·문화 콘텐츠 수출","mis":"SO6-2-u2-X11"},{"t":"반도체·문화 콘텐츠 수출 → 경공업 제품 수출 → 중화학 공업 발달 → 서울 올림픽 개최","mis":"SO6-2-u2-X11"}],"explanation":["1960년대 경공업이에요.","1970년대 중화학 공업, 1988년 올림픽이에요.","오늘날 첨단·문화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#13','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C6',2,'mc','auto','솔빛 신문 ⑤에서 경제성장의 긍정적인 영향은 어느 것인가요?',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑤에서 경제성장의 긍정적인 영향은 어느 것인가요?","options":[{"t":"주민 소득이 늘고 큰 병원과 도서관이 생겼다","correct":true},{"t":"개울이 탁해졌다","mis":"SO6-2-u2-X12"},{"t":"쓰레기가 크게 늘었다","mis":"SO6-2-u2-X12"},{"t":"논밭이 사라졌다는 사실만","mis":"SO6-2-u2-X12"}],"explanation":["소득이 늘었어요.","병원·도서관이 생겼어요.","삶의 질이 높아졌어요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#14','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C8',2,'mc','auto','솔빛 신문 ⑥에서 약수가 말라 간 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑥에서 약수가 말라 간 까닭은 무엇인가요?","options":[{"t":"함께 쓰는 약수를 몇몇이 자기 이익만 생각하며 마구 받아 갔기 때문에","correct":true},{"t":"모두가 아껴 썼기 때문에","mis":"SO6-2-u2-X16"},{"t":"마을 회의를 했기 때문에","mis":"SO6-2-u2-X16"},{"t":"비가 너무 많이 왔기 때문에","mis":"SO6-2-u2-X16"}],"explanation":["함께 쓰는 자원이에요.","몇몇이 마구 썼어요.","공유지의 비극이에요."],"asset":{"type":"passage","lines":["마을 사람들이 함께 쓰는 뒷산 약수터가 있다.","몇몇이 큰 통으로 물을 마구 받아 가 약수가 말라 간다.","마을 회의에서 한 사람이 하루 두 병만 받기로 정했다."],"title":"솔빛 신문 ⑥ 약수터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#15','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C9',2,'mc','auto','솔빛 신문 ⑦에서 마을 김 공장이 이웃 나라에 김을 파는 것은 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X20','SO6-2-u2-X08']::text[],false,'{"seq":15,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑦에서 마을 김 공장이 이웃 나라에 김을 파는 것은 무엇인가요?","options":[{"t":"수출","correct":true},{"t":"수입","mis":"SO6-2-u2-X17"},{"t":"관세","mis":"SO6-2-u2-X20"},{"t":"담합","mis":"SO6-2-u2-X08"}],"explanation":["다른 나라에 팔았어요.","파는 것은 수출이에요.","마을 쪽에서 본 거래예요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#16','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C10',2,'mc','auto','항로 길목에 있어 여러 나라 상품이 모였다가 다시 나가는 나라는 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"항로 길목에 있어 여러 나라 상품이 모였다가 다시 나가는 나라는 어느 것인가요?","options":[{"t":"싱가포르","correct":true},{"t":"사우디아라비아","mis":"SO6-2-u2-X19"},{"t":"타이","mis":"SO6-2-u2-X19"},{"t":"독일","mis":"SO6-2-u2-X19"}],"explanation":["싱가포르는 바닷길의 길목이에요.","큰 항구를 만들었어요.","위치를 활용한 무역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#17','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C11',3,'mc','auto','솔빛 신문 ⑧에서 정부가 수입 김에 세금을 높이면 생길 일을 두 쪽 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":17,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"솔빛 신문 ⑧에서 정부가 수입 김에 세금을 높이면 생길 일을 두 쪽 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"마을 김 공장의 판매는 늘 수 있지만, 수입 김을 사던 소비자는 더 비싸게 사게 된다","correct":true},{"t":"좋은 점만 생기고 걱정할 것은 없다","mis":"SO6-2-u2-X20"},{"t":"마을 김 공장의 판매가 더 줄어든다","mis":"SO6-2-u2-X20"},{"t":"수입 김이 더 싸진다","mis":"SO6-2-u2-X20"}],"explanation":["세금만큼 수입 김이 비싸져요.","마을 김이 상대적으로 잘 팔려요.","소비자 부담도 생겨요."],"asset":{"type":"passage","lines":["이웃 나라의 값싼 김이 많이 들어와 마을 김 공장의 판매가 줄었다.","정부는 수입 김에 매기는 세금을 높일지 의논하고 있다.","마을 김 공장은 더 맛있는 김을 개발하려고 애쓴다."],"title":"솔빛 신문 ⑧ 값싼 김"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#18','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C3',3,'mc','auto','근로자와 기업이 「서로 의존하는 관계」라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":18,"concept":"SO6-2-u2-C3","difficulty":3,"kind":"mc","stem":"근로자와 기업이 「서로 의존하는 관계」라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기업은 근로자의 노동력이 있어야 생산하고, 근로자는 기업에서 일해 소득을 얻는다","correct":true},{"t":"근로자와 기업은 서로 상관없다","mis":"SO6-2-u2-X07"},{"t":"기업만 근로자에게 기대고 근로자는 기대지 않는다","mis":"SO6-2-u2-X07"},{"t":"근로자는 기업 없이도 언제나 소득을 얻는다","mis":"SO6-2-u2-X07"}],"explanation":["기업은 노동력이 필요해요.","근로자는 소득이 필요해요.","서로 기대고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#19','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C1',3,'error','auto','시장경제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C1","difficulty":3,"kind":"error","stem":"시장경제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"루아 — 「시장경제에서는 나라가 모든 물건의 가격을 정해 줘.」","correct":true,"mis_target":"SO6-2-u2-X02"},{"t":"해솔 — 「가격은 사려는 양과 내놓은 양을 견주어 정해져.」","mis":"SO6-2-u2-X02"},{"t":"은호 — 「가계와 기업이 자유롭게 경쟁해.」","mis":"SO6-2-u2-X02"}],"explanation":["시장경제에서 가격은 시장에서 정해져요.","나라가 모두 정하지 않아요.","두 쪽의 양을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#20','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C8',3,'mc','auto','해결 방안을 평가하는 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"해결 방안을 평가하는 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"방안을 낸 사람이 누구인가?","correct":true},{"t":"실천할 수 있는가?","mis":"SO6-2-u2-X15"},{"t":"효과가 큰가?","mis":"SO6-2-u2-X15"},{"t":"비용이 적게 드는가?","mis":"SO6-2-u2-X15"}],"explanation":["기준은 방안의 좋고 나쁨을 봐요.","누가 냈는지는 기준이 아니에요.","실천·효과·비용을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#21','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C11',3,'mc','auto','솔빛 신문 ⑧에서 마을 김 공장이 더 맛있는 김을 개발하려고 애쓰는 것은 무엇을 보여 주나요?',ARRAY['SO6-2-u2-X20','SO6-2-u2-X17']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"솔빛 신문 ⑧에서 마을 김 공장이 더 맛있는 김을 개발하려고 애쓰는 것은 무엇을 보여 주나요?","options":[{"t":"무역으로 다른 나라 상품과 경쟁하는 모습","correct":true},{"t":"다른 나라와 의존하지 않는 모습","mis":"SO6-2-u2-X20"},{"t":"관세를 매기는 모습","mis":"SO6-2-u2-X20"},{"t":"수입을 늘리는 모습","mis":"SO6-2-u2-X17"}],"explanation":["값싼 수입 김과 겨뤄요.","더 좋은 김으로 이기려 해요.","무역 속의 경쟁이에요."],"asset":{"type":"passage","lines":["이웃 나라의 값싼 김이 많이 들어와 마을 김 공장의 판매가 줄었다.","정부는 수입 김에 매기는 세금을 높일지 의논하고 있다.","마을 김 공장은 더 맛있는 김을 개발하려고 애쓴다."],"title":"솔빛 신문 ⑧ 값싼 김"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#22','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C12',3,'mc','auto','기업 운영 계획을 세울 때 「주요 수출국 정하기」 바로 앞에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X21','SO6-2-u2-X20']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C12","difficulty":3,"kind":"mc","stem":"기업 운영 계획을 세울 때 「주요 수출국 정하기」 바로 앞에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"대표 상품과 그 특징 정하기","correct":true},{"t":"잡지 표지 색칠하기","mis":"SO6-2-u2-X21"},{"t":"친구들에게 표지 소개하기","mis":"SO6-2-u2-X21"},{"t":"관세 매기기","mis":"SO6-2-u2-X20"}],"explanation":["상품을 먼저 정해요.","그 상품이 필요할 나라를 골라요.","그다음 목표와 노력을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#23','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C1',4,'mc','auto','「시장경제와 국가 간 거래」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X12','SO6-2-u2-X18']::text[],false,'{"seq":23,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"mc","stem":"「시장경제와 국가 간 거래」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"가계와 기업이 시장에서 자유롭게 경쟁하며 경제가 성장했고, 나라마다 조건이 달라 무역으로 서로 의존하며 경쟁한다","correct":true},{"t":"나라가 모든 경제활동을 정하고 무역은 하지 않는다","mis":"SO6-2-u2-X02"},{"t":"경제성장은 좋은 점만 가져왔다","mis":"SO6-2-u2-X12"},{"t":"무역은 한 나라에만 이익이다","mis":"SO6-2-u2-X18"}],"explanation":["시장경제 → 경제성장 → 무역이에요.","좋은 점과 문제를 함께 봐요.","나라들은 의존하며 경쟁해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#24','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C1',4,'essay','teacher','솔빛 신문 ①을 보고 올해 딸기 가격이 어떻게 될지 까닭과 함께 쓰고, 딸기 가게들의 경쟁이 소비자에게 주는 도움을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C1","difficulty":4,"kind":"essay","stem":"솔빛 신문 ①을 보고 올해 딸기 가격이 어떻게 될지 까닭과 함께 쓰고, 딸기 가게들의 경쟁이 소비자에게 주는 도움을 쓰세요.","answer_guide":{"answer":"예: 올해는 시장에 나온 딸기가 크게 늘었는데 사려는 사람은 지난해와 비슷하므로 딸기 가격은 지난해보다 싸질 것이다. 딸기 가게들은 손님을 끌려고 더 달고 싱싱한 딸기를 내놓으며 경쟁하므로, 소비자는 더 좋은 딸기를 고를 수 있다.","scoring_points":["가격이 싸진다고 썼는가","사려는 양과 나온 양을 견주어 까닭을 썼는가","경쟁이 소비자에게 주는 도움을 썼는가"]},"explanation":["나온 양이 늘었어요.","두 양을 견줘요.","경쟁은 품질을 높여요."],"asset":{"type":"passage","lines":["올해 마을에 딸기 농장이 늘어 시장에 딸기가 아주 많이 나왔다.","딸기를 사려는 사람은 지난해와 비슷하다.","딸기 가게들은 손님을 끌려고 더 달고 싱싱한 딸기를 내놓는다."],"title":"솔빛 신문 ① 딸기 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_a#25','soc',6,2,'u2','','g6_2_soc_u2_review_a','unit_review','SO6-2-u2-C11',4,'essay','teacher','솔빛 신문 ⑧에서 정부가 수입 김에 매기는 세금을 높일지 의논하고 있어요. 세금을 높일 때 좋은 점과 걱정되는 점을 하나씩 쓰고, 자기 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑧에서 정부가 수입 김에 매기는 세금을 높일지 의논하고 있어요. 세금을 높일 때 좋은 점과 걱정되는 점을 하나씩 쓰고, 자기 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 수입 김에 관세를 높이면 수입 김이 비싸져 마을 김 공장의 판매가 늘고 일자리를 지킬 수 있다. 그러나 값싼 김을 사던 소비자는 더 비싸게 사야 하고, 이웃 나라도 우리 상품에 세금을 높일 수 있다. 나는 관세를 잠깐만 조금 높여 마을 김 공장이 더 맛있는 김을 개발할 시간을 주는 것이 좋겠다고 생각한다.","scoring_points":["좋은 점을 썼는가","걱정되는 점을 썼는가","두 쪽을 함께 고려한 자기 생각을 까닭과 썼는가"]},"explanation":["관세는 국내 산업을 지켜요.","소비자와 상대 나라에는 부담이에요.","두 쪽을 함께 따져요."],"asset":{"type":"passage","lines":["이웃 나라의 값싼 김이 많이 들어와 마을 김 공장의 판매가 줄었다.","정부는 수입 김에 매기는 세금을 높일지 의논하고 있다.","마을 김 공장은 더 맛있는 김을 개발하려고 애쓴다."],"title":"솔빛 신문 ⑧ 값싼 김"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#1','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C1',1,'mc','auto','시장경제에서 가격은 무엇에 따라 정해지나요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"mc","stem":"시장경제에서 가격은 무엇에 따라 정해지나요?","options":[{"t":"사람들이 필요로 하는 양과 기업이 제공하는 양","correct":true},{"t":"기업 한 곳이 원하는 금액","mis":"SO6-2-u2-X02"},{"t":"사려는 사람의 수 하나","mis":"SO6-2-u2-X02"},{"t":"물건의 색깔","mis":"SO6-2-u2-X02"}],"explanation":["두 가지 양을 함께 견줘요.","사려는 양이 많으면 올라요.","나온 양이 많으면 내려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#2','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C2',1,'mc','auto','기업이 가계에 제공하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"기업이 가계에 제공하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"일자리","correct":true},{"t":"살림","mis":"SO6-2-u2-X03"},{"t":"물건값","mis":"SO6-2-u2-X03"},{"t":"노동력","mis":"SO6-2-u2-X03"}],"explanation":["기업은 일자리를 줘요.","가계는 노동력을 줘요.","서로 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#3','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C3',1,'mc','auto','육아 휴직 제도는 무엇을 위한 제도인가요?',ARRAY['SO6-2-u2-X06','SO6-2-u2-X20','SO6-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"mc","stem":"육아 휴직 제도는 무엇을 위한 제도인가요?","options":[{"t":"근로자의 권리를 보호하기 위한 제도","correct":true},{"t":"기업의 이윤을 늘리기 위한 제도","mis":"SO6-2-u2-X06"},{"t":"수입품에 세금을 매기는 제도","mis":"SO6-2-u2-X20"},{"t":"물건값을 정하는 제도","mis":"SO6-2-u2-X02"}],"explanation":["아이를 돌볼 시간을 보장해요.","근로자를 보호하는 제도예요.","최저 임금 제도도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#4','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C4',1,'mc','auto','기업이 지나치게 경쟁해 생기는 문제가 아닌 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"기업이 지나치게 경쟁해 생기는 문제가 아닌 것은 어느 것인가요?","options":[{"t":"공정하게 경쟁하려고 노력한다","correct":true},{"t":"몰래 약속해 가격을 올린다","mis":"SO6-2-u2-X08"},{"t":"거짓 광고를 한다","mis":"SO6-2-u2-X08"},{"t":"환경을 오염한다","mis":"SO6-2-u2-X08"}],"explanation":["공정한 경쟁은 책임이에요.","담합·거짓 광고·오염은 문제예요.","정부가 바로잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#5','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C5',1,'mc','auto','1988년 우리나라에서 열린 세계적인 행사는 무엇인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"1988년 우리나라에서 열린 세계적인 행사는 무엇인가요?","options":[{"t":"서울 올림픽 대회","correct":true},{"t":"벽란도 박람회","mis":"SO6-2-u2-X11"},{"t":"한강 축제","mis":"SO6-2-u2-X11"},{"t":"세계 기후 회의","mis":"SO6-2-u2-X11"}],"explanation":["1988년 서울 올림픽을 열었어요.","경제성장을 세계에 보여 줬어요.","경공업·중화학 공업 다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#6','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C7',1,'mc','auto','임금이나 복지를 두고 근로자와 기업 사이에 갈등이 늘어나는 문제를 무엇이라고 하나요?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C7","difficulty":1,"kind":"mc","stem":"임금이나 복지를 두고 근로자와 기업 사이에 갈등이 늘어나는 문제를 무엇이라고 하나요?","options":[{"t":"노사 갈등 문제","correct":true},{"t":"과소비 문제","mis":"SO6-2-u2-X14"},{"t":"빈부 격차 문제","mis":"SO6-2-u2-X14"},{"t":"환경 문제","mis":"SO6-2-u2-X14"}],"explanation":["「노」는 근로자, 「사」는 기업이에요.","임금·복지를 두고 맞서요.","소통으로 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#7','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',1,'mc','auto','우리나라가 외국에서 만든 학용품을 사 오는 것은 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"우리나라가 외국에서 만든 학용품을 사 오는 것은 무엇인가요?","options":[{"t":"수입","correct":true},{"t":"수출","mis":"SO6-2-u2-X17"},{"t":"관세","mis":"SO6-2-u2-X20"},{"t":"생산","mis":"SO6-2-u2-X17"}],"explanation":["사 오는 것은 수입이에요.","파는 것은 수출이에요.","학용품은 들어왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#8','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C11',1,'mc','auto','관세를 높게 매기면 수입품의 가격은 어떻게 되나요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"mc","stem":"관세를 높게 매기면 수입품의 가격은 어떻게 되나요?","options":[{"t":"비싸진다","correct":true},{"t":"싸진다","mis":"SO6-2-u2-X20"},{"t":"그대로다","mis":"SO6-2-u2-X20"},{"t":"사라진다","mis":"SO6-2-u2-X20"}],"explanation":["관세는 수입품에 붙는 세금이에요.","세금만큼 값이 올라요.","국내 상품이 상대적으로 잘 팔려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#9','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C1',2,'mc','auto','솔빛 신문 ①에서 딸기 가게들이 더 달고 싱싱한 딸기를 내놓는 까닭은 무엇인가요?',ARRAY['SO6-2-u2-X02','SO6-2-u2-X08']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"솔빛 신문 ①에서 딸기 가게들이 더 달고 싱싱한 딸기를 내놓는 까닭은 무엇인가요?","options":[{"t":"다른 가게보다 더 많이 팔려고 경쟁하기 때문에","correct":true},{"t":"나라가 시켰기 때문에","mis":"SO6-2-u2-X02"},{"t":"딸기를 사려는 사람이 없기 때문에","mis":"SO6-2-u2-X02"},{"t":"가게끼리 약속해서 가격을 올리려고","mis":"SO6-2-u2-X08"}],"explanation":["가게끼리 손님을 두고 경쟁해요.","더 좋은 딸기를 내놓아요.","자유로운 경쟁의 모습이에요."],"asset":{"type":"passage","lines":["올해 마을에 딸기 농장이 늘어 시장에 딸기가 아주 많이 나왔다.","딸기를 사려는 사람은 지난해와 비슷하다.","딸기 가게들은 손님을 끌려고 더 달고 싱싱한 딸기를 내놓는다."],"title":"솔빛 신문 ① 딸기 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#10','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C2',2,'mc','auto','솔빛 신문 ②에서 가게 주인들이 손님이 늘어 반긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X04','SO6-2-u2-X02','SO6-2-u2-X05']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"솔빛 신문 ②에서 가게 주인들이 손님이 늘어 반긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일자리를 얻은 주민들이 받은 급여로 소비를 늘렸기 때문에","correct":true},{"t":"빵 공장이 가게를 대신 운영해서","mis":"SO6-2-u2-X04"},{"t":"가게들이 가격을 모두 올려서","mis":"SO6-2-u2-X02"},{"t":"주민들이 저축을 그만둬서","mis":"SO6-2-u2-X05"}],"explanation":["공장 → 급여 → 주민이에요.","주민 → 소비 → 가게예요.","경제활동은 이어져 있어요."],"asset":{"type":"passage","lines":["마을 빵 공장이 일손을 열 명 더 뽑았다.","일자리를 얻은 주민들은 받은 급여로 마을 가게에서 장을 본다.","가게 주인들은 손님이 늘었다며 반긴다."],"title":"솔빛 신문 ② 빵 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#11','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C3',2,'ox','auto','솔빛 신문 ③에서 휴게실을 넓힌 일은 근로자뿐 아니라 공장에도 도움이 될 수 있어요.',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":11,"concept":"SO6-2-u2-C3","difficulty":2,"kind":"ox","stem":"솔빛 신문 ③에서 휴게실을 넓힌 일은 근로자뿐 아니라 공장에도 도움이 될 수 있어요.","answer":"O","reason_options":[{"t":"근로자가 즐겁게 일하면 일할 의욕이 높아져 좋은 빵을 만들기 쉬워지기 때문에","correct":true},{"t":"휴게실을 넓히면 공장은 반드시 손해만 보기 때문에","mis":"SO6-2-u2-X07"}],"mis":"SO6-2-u2-X07","explanation":["근로자와 기업은 서로 의존해요.","의욕이 높아지면 생산도 좋아져요.","둘 다 이익이에요."],"asset":{"type":"passage","lines":["빵 공장 근로자들이 근로자 단체를 통해 쉬는 시간을 늘려 달라고 했다.","공장과 근로자가 마주 앉아 이야기한 끝에 휴게실을 넓히기로 했다.","근로자들은 더 즐겁게 일하게 되었다고 말했다."],"title":"솔빛 신문 ③ 휴게실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#12','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C5',2,'mc','auto','1인당 국민 총소득을 구할 때 국민이 받은 소득의 합계를 무엇으로 나누나요?',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"1인당 국민 총소득을 구할 때 국민이 받은 소득의 합계를 무엇으로 나누나요?","options":[{"t":"인구수","correct":true},{"t":"기업 수","mis":"SO6-2-u2-X10"},{"t":"수출액","mis":"SO6-2-u2-X10"},{"t":"도시 수","mis":"SO6-2-u2-X10"}],"explanation":["소득의 합계를 구해요.","인구수로 나눠요.","한 사람이 받은 소득을 어림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#13','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C7',2,'mc','auto','솔빛 신문 ⑤에서 켜진 경고등은 어느 문제인가요?',ARRAY['SO6-2-u2-X14']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C7","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑤에서 켜진 경고등은 어느 문제인가요?","options":[{"t":"환경 문제","correct":true},{"t":"노사 갈등 문제","mis":"SO6-2-u2-X14"},{"t":"빈부 격차 문제","mis":"SO6-2-u2-X14"},{"t":"과소비 문제만","mis":"SO6-2-u2-X14"}],"explanation":["개울이 탁해졌어요.","쓰레기가 늘었어요.","환경 문제예요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#14','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C8',2,'mc','auto','솔빛 신문 ⑥에서 마을 회의의 결정은 어떤 노력인가요?',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑥에서 마을 회의의 결정은 어떤 노력인가요?","options":[{"t":"함께 쓰는 자원을 함부로 쓰지 못하게 규칙을 정한 노력","correct":true},{"t":"자원을 더 빨리 쓰게 한 노력","mis":"SO6-2-u2-X16"},{"t":"한 사람만 약수를 쓰게 한 노력","mis":"SO6-2-u2-X16"},{"t":"약수터를 없앤 노력","mis":"SO6-2-u2-X16"}],"explanation":["하루 두 병으로 정했어요.","규칙으로 자원을 지켜요.","사람들의 태도도 함께 필요해요."],"asset":{"type":"passage","lines":["마을 사람들이 함께 쓰는 뒷산 약수터가 있다.","몇몇이 큰 통으로 물을 마구 받아 가 약수가 말라 간다.","마을 회의에서 한 사람이 하루 두 병만 받기로 정했다."],"title":"솔빛 신문 ⑥ 약수터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#15','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',2,'mc','auto','솔빛 신문 ⑦에서 김 굽는 기계를 다른 나라에서 사 온 것은 무엇인가요?',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":15,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑦에서 김 굽는 기계를 다른 나라에서 사 온 것은 무엇인가요?","options":[{"t":"수입","correct":true},{"t":"수출","mis":"SO6-2-u2-X17"},{"t":"생산","mis":"SO6-2-u2-X17"},{"t":"저축","mis":"SO6-2-u2-X17"}],"explanation":["다른 나라에서 사 왔어요.","사 오는 것은 수입이에요.","수출하는 공장도 수입을 해요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#16','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C10',2,'mc','auto','독일이 백신을 수출할 수 있는 조건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"독일이 백신을 수출할 수 있는 조건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"백신을 만드는 뛰어난 기술","correct":true},{"t":"넓은 논","mis":"SO6-2-u2-X19"},{"t":"풍부한 원유","mis":"SO6-2-u2-X19"},{"t":"항로 길목의 위치","mis":"SO6-2-u2-X19"}],"explanation":["백신은 첨단 제품이에요.","기술이 필요해요.","기술도 무역의 힘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#17','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C7',3,'mc','auto','빠른 경제성장의 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":17,"concept":"SO6-2-u2-C7","difficulty":3,"kind":"mc","stem":"빠른 경제성장의 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"생활이 풍족해지고 삶의 질이 높아졌지만, 환경 오염과 빈부 격차 같은 문제도 생겼다","correct":true},{"t":"생활이 나아지기만 했다","mis":"SO6-2-u2-X12"},{"t":"문제만 생기고 나아진 것은 없다","mis":"SO6-2-u2-X12"},{"t":"아무것도 달라지지 않았다","mis":"SO6-2-u2-X12"}],"explanation":["좋아진 점이 있어요.","문제도 생겼어요.","두 쪽을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#18','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C2',3,'mc','auto','가계와 기업이 서로 기대고 있다는 것을 가장 잘 보여 주는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":18,"concept":"SO6-2-u2-C2","difficulty":3,"kind":"mc","stem":"가계와 기업이 서로 기대고 있다는 것을 가장 잘 보여 주는 것은 어느 것인가요?","options":[{"t":"가계가 일손을 주지 않으면 기업이 생산할 수 없고, 기업이 급여를 주지 않으면 가계가 소비할 수 없다","correct":true},{"t":"가계는 기업 없이도 필요한 것을 모두 만든다","mis":"SO6-2-u2-X04"},{"t":"기업은 가계 없이도 물건을 다 판다","mis":"SO6-2-u2-X04"},{"t":"가계와 기업은 시장에서 만나지 않는다","mis":"SO6-2-u2-X04"}],"explanation":["일손과 급여가 오가요.","한쪽이 멈추면 다른 쪽도 멈춰요.","서로 꼭 필요해요."],"asset":{"type":"passage","lines":["① 가계가 기업에 일손을 준다.","② 기업이 만든 물건과 서비스가 시장에 나온다.","③ 가계가 시장에서 물건값을 내고 소비한다.","④ 기업이 일한 대가로 가계에 급여를 준다."],"title":"가계와 기업 사이의 네 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#19','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C5',3,'error','auto','우리나라 경제성장을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C5","difficulty":3,"kind":"error","stem":"우리나라 경제성장을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다올 — 「우리나라는 반도체를 먼저 수출하고 나중에 가발을 수출했어.」","correct":true,"mis_target":"SO6-2-u2-X11"},{"t":"하빈 — 「1960년대에 경공업 제품을 수출했어.」","mis":"SO6-2-u2-X11"},{"t":"지온 — 「1988년에 서울 올림픽 대회를 열었어.」","mis":"SO6-2-u2-X11"}],"explanation":["가발은 1960년대 경공업 제품이에요.","반도체는 오늘날의 수출품이에요.","차례를 바르게 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#20','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C8',3,'mc','auto','두 방안의 합계가 같을 때 고르는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"두 방안의 합계가 같을 때 고르는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모둠이 가장 중요하게 여기는 기준의 점수를 견주어 고른다","correct":true},{"t":"먼저 나온 방안을 고른다","mis":"SO6-2-u2-X15"},{"t":"아무거나 고른다","mis":"SO6-2-u2-X15"},{"t":"두 방안을 모두 버린다","mis":"SO6-2-u2-X15"}],"explanation":["합계가 같으면 더 중요한 기준을 봐요.","그 기준 점수가 높은 것을 골라요.","기준을 함께 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#21','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C11',3,'mc','auto','다음 가운데 「상호 의존」을 보여 주는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"다음 가운데 「상호 의존」을 보여 주는 것은 어느 것인가요?","options":[{"t":"마을 김 공장이 다른 나라 기계로 김을 구워 이웃 나라에 판다","correct":true},{"t":"여러 나라가 자동화 항만을 먼저 갖추려고 다툰다","mis":"SO6-2-u2-X20"},{"t":"여러 나라가 다른 나라의 큰 시설 공사를 따내려고 다툰다","mis":"SO6-2-u2-X20"},{"t":"여러 나라가 인공지능을 먼저 개발하려고 다툰다","mis":"SO6-2-u2-X20"}],"explanation":["기계를 사 오고 김을 팔아요.","서로 기대어 만들어요.","나머지 셋은 경쟁이에요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#22','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C8',3,'mc','auto','해결 방안을 검토한 뒤 이어서 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"해결 방안을 검토한 뒤 이어서 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"검토한 방안으로 실천 계획을 세워 발표하기","correct":true},{"t":"문제를 다시 고르지 않고 그만두기","mis":"SO6-2-u2-X15"},{"t":"평가 기준을 지우기","mis":"SO6-2-u2-X15"},{"t":"점수가 가장 낮은 방안 고르기","mis":"SO6-2-u2-X15"}],"explanation":["문제 → 방안 → 기준 → 검토예요.","그다음 실천 계획을 세워요.","발표하고 함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#23','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C2',4,'mc','auto','솔빛 신문 ②와 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X07','SO6-2-u2-X04','SO6-2-u2-X06']::text[],false,'{"seq":23,"concept":"SO6-2-u2-C2","difficulty":4,"kind":"mc","stem":"솔빛 신문 ②와 ③을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빵 공장이 일자리를 늘리고 근로자의 권리도 살피자 주민·가게·공장 모두에게 도움이 되었다","correct":true},{"t":"공장이 근로자와 이야기하면 반드시 손해를 본다","mis":"SO6-2-u2-X07"},{"t":"일자리가 늘어도 마을 가게와는 상관없다","mis":"SO6-2-u2-X04"},{"t":"근로자 단체가 있으면 공장이 문을 닫는다","mis":"SO6-2-u2-X06"}],"explanation":["일자리 → 소득 → 소비예요.","권리 보호 → 즐겁게 일해요.","서로 이어져 모두 이익이에요."],"asset":{"type":"passage","lines":["빵 공장 근로자들이 근로자 단체를 통해 쉬는 시간을 늘려 달라고 했다.","공장과 근로자가 마주 앉아 이야기한 끝에 휴게실을 넓히기로 했다.","근로자들은 더 즐겁게 일하게 되었다고 말했다."],"title":"솔빛 신문 ③ 휴게실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#24','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C4',4,'essay','teacher','솔빛 신문 ④의 음료 회사를 보고 기업에 사회적 책임이 필요한 까닭을 쓰고, 음료 회사가 한 노력을 환경·사회·투명 경영으로 나누어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C4","difficulty":4,"kind":"essay","stem":"솔빛 신문 ④의 음료 회사를 보고 기업에 사회적 책임이 필요한 까닭을 쓰고, 음료 회사가 한 노력을 환경·사회·투명 경영으로 나누어 쓰세요.","answer_guide":{"answer":"예: 기업의 경제활동은 사회에 큰 영향을 미치므로 기업은 사회에 대한 책임감을 가져야 한다. 음료 회사는 플라스틱병 대신 다시 쓰는 유리병으로 바꾸어 환경을 지키고, 마을 아이들을 위한 무료 과학 교실을 열어 사회에 기여하며, 해마다 경영 내용을 공개해 투명 경영을 한다.","scoring_points":["사회적 책임이 필요한 까닭을 썼는가","노력을 세 가치로 바르게 나누었는가","신문 내용을 근거로 썼는가"]},"explanation":["기업은 사회에 큰 영향을 줘요.","환경·사회·투명 경영이에요.","세 노력을 가려 써요."],"asset":{"type":"passage","lines":["마을 음료 회사가 플라스틱병 대신 다시 쓰는 유리병으로 바꾸었다.","마을 아이들을 위한 무료 과학 교실도 열었다.","회사는 해마다 경영 내용을 주민에게 공개한다."],"title":"솔빛 신문 ④ 음료 회사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_b#25','soc',6,2,'u2','','g6_2_soc_u2_review_b','unit_review','SO6-2-u2-C9',4,'essay','teacher','솔빛 신문 ⑦을 보고 마을 김 공장의 무역에서 수출과 수입을 하나씩 찾아 쓰고, 이처럼 무역이 이루어지는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C9","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑦을 보고 마을 김 공장의 무역에서 수출과 수입을 하나씩 찾아 쓰고, 이처럼 무역이 이루어지는 까닭을 쓰세요.","answer_guide":{"answer":"예: 김을 이웃 나라들에 파는 것은 수출이고, 김을 굽는 기계를 다른 나라에서 사 온 것은 수입이다. 마을은 바다가 깨끗하고 김 기르는 기술이 좋아 김을 잘 만들지만 김 굽는 기계는 다른 나라가 더 잘 만든다. 이처럼 나라마다 자연환경과 기술이 달라 잘 만드는 것을 팔고 필요한 것을 사 오면 서로 이익이 되기 때문에 무역이 이루어진다.","scoring_points":["수출을 바르게 찾았는가","수입을 바르게 찾았는가","나라마다 조건이 달라 서로 이익이라는 까닭을 썼는가"]},"explanation":["김 — 수출이에요.","기계 — 수입이에요.","조건이 달라 서로 이익이에요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#1','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C1',1,'sa','auto','시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"sa","stem":"시장에서 가계와 기업이 자유롭게 경쟁하며 경제활동을 하는 방식을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["시장경제"],"explanation":["시장에서 이루어지는 경제예요.","자유로운 경쟁이 특징이에요.","우리나라의 경제 방식이에요."],"mis":"SO6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#2','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C2',1,'ox','auto','가계와 기업은 시장에서 만나 서로 필요한 것을 주고받아요.',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"ox","stem":"가계와 기업은 시장에서 만나 서로 필요한 것을 주고받아요.","answer":"O","reason_options":[{"t":"가계는 일손과 물건값을, 기업은 급여와 물건을 주고받기 때문에","correct":true},{"t":"가계와 기업은 서로 만나지 않기 때문에","mis":"SO6-2-u2-X04"}],"mis":"SO6-2-u2-X04","explanation":["시장은 만나는 자리예요.","서로 필요한 것을 주고받아요.","한쪽이 멈추면 다른 쪽도 멈춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#3','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C3',1,'ox','auto','휴가와 휴식은 근로자의 기본적인 권리예요.',ARRAY['SO6-2-u2-X06']::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"ox","stem":"휴가와 휴식은 근로자의 기본적인 권리예요.","answer":"O","reason_options":[{"t":"근로자가 쉬어야 건강하게 일할 수 있어 법이 보장하기 때문에","correct":true},{"t":"쉬는 것은 일을 게을리하는 것이기 때문에","mis":"SO6-2-u2-X06"}],"mis":"SO6-2-u2-X06","explanation":["휴가와 휴식은 권리예요.","법이 보장해요.","지켜지지 않으면 모두 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#4','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C4',1,'ox','auto','기업의 사회적 책임에는 환경을 지키고 소비자를 보호하는 일이 들어가요.',ARRAY['SO6-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"ox","stem":"기업의 사회적 책임에는 환경을 지키고 소비자를 보호하는 일이 들어가요.","answer":"O","reason_options":[{"t":"기업의 활동이 사회에 큰 영향을 미쳐 환경·사회를 살펴야 하기 때문에","correct":true},{"t":"기업은 이윤만 얻으면 되기 때문에","mis":"SO6-2-u2-X08"}],"mis":"SO6-2-u2-X08","explanation":["환경·사회·투명 경영이 중요해요.","소비자 보호는 사회에 들어요.","책임을 다하면 사회가 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#5','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C5',1,'ox','auto','경제성장은 나라 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것이에요.',ARRAY['SO6-2-u2-X10']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"ox","stem":"경제성장은 나라 전체의 생산 수준이나 국민 소득이 늘어 경제 규모가 커지는 것이에요.","answer":"O","reason_options":[{"t":"한 기업이나 한 가족이 아니라 나라 전체의 생산과 소득을 보기 때문에","correct":true},{"t":"나라의 인구가 늘어나는 것을 말하기 때문에","mis":"SO6-2-u2-X10"}],"mis":"SO6-2-u2-X10","explanation":["나라 전체를 봐요.","생산과 소득이 늘어요.","인구 증가와는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#6','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C7',1,'ox','auto','빠른 경제성장은 좋은 영향만 주었고 문제는 생기지 않았어요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C7","difficulty":1,"kind":"ox","stem":"빠른 경제성장은 좋은 영향만 주었고 문제는 생기지 않았어요.","answer":"X","reason_options":[{"t":"생활이 나아졌지만 환경·빈부 격차·과소비·노사 갈등 같은 문제도 생겼기 때문에","correct":true},{"t":"경제가 성장하면 모든 문제가 저절로 사라지기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["좋아진 점이 많아요.","그러나 문제도 생겼어요.","두 쪽을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#7','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',1,'ox','auto','무역은 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일이에요.',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"ox","stem":"무역은 나라와 나라 사이에 물자나 서비스를 사고팔거나 교환하는 일이에요.","answer":"O","reason_options":[{"t":"나라 사이에 물건과 서비스가 오가는 활동이기 때문에","correct":true},{"t":"한 나라 안의 시장에서 사고파는 일이기 때문에","mis":"SO6-2-u2-X18"}],"mis":"SO6-2-u2-X18","explanation":["나라와 나라 사이의 거래예요.","물자도 서비스도 오가요.","이것이 무역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#8','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',1,'ox','auto','세계 여러 나라는 무역을 통해 물자와 기술을 주고받으며 서로 의존해요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"ox","stem":"세계 여러 나라는 무역을 통해 물자와 기술을 주고받으며 서로 의존해요.","answer":"O","reason_options":[{"t":"한 나라가 모든 것을 다 만들 수 없어 서로 필요한 것을 나누기 때문에","correct":true},{"t":"나라마다 필요한 것을 모두 스스로 만들기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["부품·자원·기술이 오가요.","서로 기대어 만들어요.","이것이 상호 의존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#9','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C1',2,'ox','auto','솔빛 신문 ①에서 소비자는 가게들의 경쟁 덕분에 더 좋은 딸기를 고를 수 있어요.',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"ox","stem":"솔빛 신문 ①에서 소비자는 가게들의 경쟁 덕분에 더 좋은 딸기를 고를 수 있어요.","answer":"O","reason_options":[{"t":"가게들이 손님을 끌려고 품질을 높이기 때문에","correct":true},{"t":"가게가 경쟁하면 딸기가 모두 사라지기 때문에","mis":"SO6-2-u2-X02"}],"mis":"SO6-2-u2-X02","explanation":["경쟁은 품질을 높여요.","소비자가 고를 수 있어요.","시장경제의 좋은 점이에요."],"asset":{"type":"passage","lines":["올해 마을에 딸기 농장이 늘어 시장에 딸기가 아주 많이 나왔다.","딸기를 사려는 사람은 지난해와 비슷하다.","딸기 가게들은 손님을 끌려고 더 달고 싱싱한 딸기를 내놓는다."],"title":"솔빛 신문 ① 딸기 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#10','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C2',2,'ox','auto','솔빛 신문 ②를 보면 한 기업의 활동이 다른 기업과 가계에도 영향을 줘요.',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"ox","stem":"솔빛 신문 ②를 보면 한 기업의 활동이 다른 기업과 가계에도 영향을 줘요.","answer":"O","reason_options":[{"t":"공장의 일자리가 가계의 소득이 되고, 그 소득이 가게의 판매로 이어지기 때문에","correct":true},{"t":"기업의 활동은 그 기업 안에서만 끝나기 때문에","mis":"SO6-2-u2-X04"}],"mis":"SO6-2-u2-X04","explanation":["공장이 일손을 뽑았어요.","주민 소득이 늘었어요.","가게 손님도 늘었어요."],"asset":{"type":"passage","lines":["마을 빵 공장이 일손을 열 명 더 뽑았다.","일자리를 얻은 주민들은 받은 급여로 마을 가게에서 장을 본다.","가게 주인들은 손님이 늘었다며 반긴다."],"title":"솔빛 신문 ② 빵 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#11','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C4',2,'match','auto','솔빛 신문 ④ 음료 회사의 노력과 그 가치를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"match","stem":"솔빛 신문 ④ 음료 회사의 노력과 그 가치를 알맞게 이으세요.","pairs":[{"l":"유리병으로 바꾸기","r":"환경"},{"l":"무료 과학 교실","r":"사회"},{"l":"경영 내용 공개","r":"투명 경영"}],"mis":"SO6-2-u2-X09","explanation":["병을 다시 쓰는 것은 환경이에요.","지역 아이들을 돕는 것은 사회예요.","내용 공개는 투명 경영이에요."],"asset":{"type":"passage","lines":["마을 음료 회사가 플라스틱병 대신 다시 쓰는 유리병으로 바꾸었다.","마을 아이들을 위한 무료 과학 교실도 열었다.","회사는 해마다 경영 내용을 주민에게 공개한다."],"title":"솔빛 신문 ④ 음료 회사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#12','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C5',2,'ox','auto','우리나라의 빠른 경제성장은 가계·기업·정부 가운데 한쪽만의 노력으로 이루어졌어요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"ox","stem":"우리나라의 빠른 경제성장은 가계·기업·정부 가운데 한쪽만의 노력으로 이루어졌어요.","answer":"X","reason_options":[{"t":"가계와 기업, 정부가 함께 노력했기 때문에","correct":true},{"t":"정부가 모든 일을 혼자 했기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["가계는 일하고 저축했어요.","기업은 생산하고 수출했어요.","정부는 계획하고 도왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#13','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C6',2,'ox','auto','솔빛 신문 ⑤의 마을처럼 경제성장은 좋은 점과 문제를 함께 가져올 수 있어요.',ARRAY['SO6-2-u2-X12']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"ox","stem":"솔빛 신문 ⑤의 마을처럼 경제성장은 좋은 점과 문제를 함께 가져올 수 있어요.","answer":"O","reason_options":[{"t":"소득과 시설은 늘었지만 개울 오염과 쓰레기도 함께 늘었기 때문에","correct":true},{"t":"경제성장은 좋은 점만 가져오기 때문에","mis":"SO6-2-u2-X12"}],"mis":"SO6-2-u2-X12","explanation":["좋아진 점이 있어요.","문제도 생겼어요.","두 쪽을 함께 봐요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#14','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C8',2,'ox','auto','솔빛 신문 ⑥에서 규칙을 정했으니 사람들의 태도는 더 이상 중요하지 않아요.',ARRAY['SO6-2-u2-X16']::text[],false,'{"seq":14,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"ox","stem":"솔빛 신문 ⑥에서 규칙을 정했으니 사람들의 태도는 더 이상 중요하지 않아요.","answer":"X","reason_options":[{"t":"규칙이 있어도 공동의 이익을 생각하며 지키려는 태도가 있어야 약수를 지킬 수 있기 때문에","correct":true},{"t":"규칙만 있으면 저절로 모두 지키기 때문에","mis":"SO6-2-u2-X16"}],"mis":"SO6-2-u2-X16","explanation":["규칙은 필요해요.","지키려는 마음도 필요해요.","둘이 함께 자원을 지켜요."],"asset":{"type":"passage","lines":["마을 사람들이 함께 쓰는 뒷산 약수터가 있다.","몇몇이 큰 통으로 물을 마구 받아 가 약수가 말라 간다.","마을 회의에서 한 사람이 하루 두 병만 받기로 정했다."],"title":"솔빛 신문 ⑥ 약수터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#15','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',2,'ox','auto','솔빛 신문 ⑦에서 마을 김 공장이 김을 판 거래는 김을 산 이웃 나라 쪽에서 보면 수입이에요.',ARRAY['SO6-2-u2-X17']::text[],false,'{"seq":15,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"ox","stem":"솔빛 신문 ⑦에서 마을 김 공장이 김을 판 거래는 김을 산 이웃 나라 쪽에서 보면 수입이에요.","answer":"O","reason_options":[{"t":"같은 거래라도 산 나라 쪽에서 보면 들여온 것이기 때문에","correct":true},{"t":"한 거래는 어느 쪽에서 보든 수출이기 때문에","mis":"SO6-2-u2-X17"}],"mis":"SO6-2-u2-X17","explanation":["마을 쪽 — 수출이에요.","이웃 나라 쪽 — 수입이에요.","보는 쪽을 먼저 정해요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#16','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C10',2,'ox','auto','사우디아라비아가 원유를 많이 수출하는 것은 땅속 자원이 풍부하기 때문이에요.',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"ox","stem":"사우디아라비아가 원유를 많이 수출하는 것은 땅속 자원이 풍부하기 때문이에요.","answer":"O","reason_options":[{"t":"원유 같은 자원이 많으면 남는 것을 다른 나라에 팔 수 있기 때문에","correct":true},{"t":"사우디아라비아는 반도체 기술이 가장 뛰어나기 때문에","mis":"SO6-2-u2-X19"}],"mis":"SO6-2-u2-X19","explanation":["자원이 풍부해요.","자원을 수출해요.","조건이 무역 모습을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#17','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',3,'mc','auto','기업이 다른 나라에 공장을 지을 때의 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":17,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"기업이 다른 나라에 공장을 지을 때의 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"세계 사람들은 값싸고 다양한 제품을 사고 그 나라 사람들은 일자리를 얻지만, 정당한 임금과 환경 문제를 살펴야 한다","correct":true},{"t":"그 나라 사람들은 아무 이익도 얻지 못한다","mis":"SO6-2-u2-X20"},{"t":"좋은 점만 있고 살필 것은 없다","mis":"SO6-2-u2-X20"},{"t":"제품 가격이 반드시 비싸진다","mis":"SO6-2-u2-X20"}],"explanation":["일자리와 값싼 제품이 생겨요.","임금·환경 문제가 생길 수 있어요.","정당한 분배가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#18','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',3,'mc','auto','나라와 나라가 무역으로 서로 의존한다는 것을 가장 잘 보여 주는 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X20']::text[],false,'{"seq":18,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"나라와 나라가 무역으로 서로 의존한다는 것을 가장 잘 보여 주는 것은 어느 것인가요?","options":[{"t":"우리나라는 흑연을 사 와 배터리를 만들고, 흑연을 판 나라는 그 배터리를 단 전기차를 사 간다","correct":true},{"t":"한 나라가 모든 물자를 스스로 만든다","mis":"SO6-2-u2-X18"},{"t":"여러 나라가 첨단 기술을 먼저 개발하려고 다툰다","mis":"SO6-2-u2-X20"},{"t":"나라끼리 무역을 끊는다","mis":"SO6-2-u2-X18"}],"explanation":["자원과 제품이 오가요.","서로가 서로의 손님이에요.","이것이 상호 의존이에요."],"asset":{"type":"passage","lines":["과거 — 우리나라는 흑연을 많이 캐는 나라였다.","그 뒤 — 다른 나라에서 값싼 흑연을 수입하며 거의 캐지 않게 되었다.","오늘날 — 수입한 흑연으로 전기차 배터리를 만들어 수출한다.","흑연을 캐는 나라는 그 배터리를 단 전기차를 수입하기도 한다."],"title":"흑연과 배터리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#19','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C9',3,'error','auto','무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X18']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C9","difficulty":3,"kind":"error","stem":"무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유찬 — 「무역은 물건이 하나도 없을 때만 하는 거야.」","correct":true,"mis_target":"SO6-2-u2-X18"},{"t":"아린 — 「더 싸거나 좋은 물건을 사 오려고도 무역을 해.」","mis":"SO6-2-u2-X18"},{"t":"로운 — 「잘 만드는 것을 팔고 모자란 것을 사 와.」","mis":"SO6-2-u2-X18"}],"explanation":["있어도 더 싸면 사 와요.","잘 만드는 것은 팔아요.","서로 이익이 되어 무역해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#20','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C8',3,'ox','auto','같은 방안들이라도 어떤 기준을 더 중요하게 보느냐에 따라 가장 높은 방안이 달라질 수 있어요.',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"ox","stem":"같은 방안들이라도 어떤 기준을 더 중요하게 보느냐에 따라 가장 높은 방안이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"기준의 무게가 바뀌면 방안마다 합계가 달라지기 때문에","correct":true},{"t":"방안의 점수는 기준과 상관없이 언제나 같기 때문에","mis":"SO6-2-u2-X15"}],"mis":"SO6-2-u2-X15","explanation":["기준의 무게가 결과를 바꿔요.","점수판에서 확인했어요.","그래서 기준이 중요해요."],"asset":{"type":"passage","lines":["해결하고 싶은 문제 — 자원 낭비(재활용 쓰레기가 넘침)","방안 ㉠ 분리배출 캠페인 — 실천 3 · 효과 1 · 비용 3","방안 ㉡ 재활용 공장 새로 짓기 — 실천 1 · 효과 3 · 비용 1","방안 ㉢ 다회용기 쓰는 가게에 혜택 — 실천 2 · 효과 3 · 비용 1","점수는 1~3, 비용은 적게 들수록 높은 점수"],"title":"모둠 해결 방안 점수판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#21','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',3,'ox','auto','수입이 늘어 국내 산업이 어려울 때는 관세를 높이거나 수입을 제한하기도 해요.',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"ox","stem":"수입이 늘어 국내 산업이 어려울 때는 관세를 높이거나 수입을 제한하기도 해요.","answer":"O","reason_options":[{"t":"국내 산업이 자랄 시간을 주고 경쟁력을 지키려는 방법이기 때문에","correct":true},{"t":"관세는 수출품에만 매기기 때문에","mis":"SO6-2-u2-X20"}],"mis":"SO6-2-u2-X20","explanation":["관세와 수입 제한은 보호 방법이에요.","철강 산업이 그렇게 자랐어요.","부담도 함께 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#22','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C12',3,'ox','auto','기업 소개 잡지 표지에 이윤만 적기보다 사회적 책임 목표와 근로자를 위한 노력을 함께 적으면 기업의 특징이 더 잘 드러나요.',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C12","difficulty":3,"kind":"ox","stem":"기업 소개 잡지 표지에 이윤만 적기보다 사회적 책임 목표와 근로자를 위한 노력을 함께 적으면 기업의 특징이 더 잘 드러나요.","answer":"O","reason_options":[{"t":"기업이 무엇을 중요하게 여기는지가 함께 보이기 때문에","correct":true},{"t":"잡지 표지에는 이윤 말고는 적을 수 없기 때문에","mis":"SO6-2-u2-X21"}],"mis":"SO6-2-u2-X21","explanation":["이윤만으로는 특징이 흐려요.","책임과 노력이 기업을 보여 줘요.","네 칸을 모두 채워요."],"asset":{"type":"passage","lines":["기업 이름 — △△ 게임 회사","대표 상품 — 여러 캐릭터가 과제를 풀며 자라는 ☆☆ 게임","주요 수출국 — 인구가 많아 게임을 즐길 사람이 많은 나라","목표 — 매년 성장하고 지속가능한 환경을 지키는 기업","근로자를 위한 노력 — 매주 대화의 시간, 성과급, 휴가 보장"],"title":"기업 소개 잡지 표지 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#23','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C11',4,'mc','auto','솔빛 신문 ⑦과 ⑧을 함께 볼 때 마을 김 공장의 처지를 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X17','SO6-2-u2-X20']::text[],false,'{"seq":23,"concept":"SO6-2-u2-C11","difficulty":4,"kind":"mc","stem":"솔빛 신문 ⑦과 ⑧을 함께 볼 때 마을 김 공장의 처지를 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"이웃 나라에 김을 팔며 의존하는 한편, 값싼 수입 김과 경쟁해야 한다","correct":true},{"t":"무역과 아무 관계가 없다","mis":"SO6-2-u2-X18"},{"t":"수입만 하고 수출은 하지 않는다","mis":"SO6-2-u2-X17"},{"t":"다른 나라와 경쟁할 필요가 없다","mis":"SO6-2-u2-X20"}],"explanation":["⑦ — 김을 팔고 기계를 사 와요.","⑧ — 수입 김과 경쟁해요.","의존과 경쟁이 함께 있어요."],"asset":{"type":"passage","lines":["이웃 나라의 값싼 김이 많이 들어와 마을 김 공장의 판매가 줄었다.","정부는 수입 김에 매기는 세금을 높일지 의논하고 있다.","마을 김 공장은 더 맛있는 김을 개발하려고 애쓴다."],"title":"솔빛 신문 ⑧ 값싼 김"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#24','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C7',4,'essay','teacher','솔빛 신문 ⑤의 마을이 겪은 경제성장의 긍정적인 영향과 문제를 하나씩 쓰고, 문제를 해결하려면 마을 주민·기업·정부가 각각 무엇을 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C7","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑤의 마을이 겪은 경제성장의 긍정적인 영향과 문제를 하나씩 쓰고, 문제를 해결하려면 마을 주민·기업·정부가 각각 무엇을 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 주민 소득이 늘고 큰 병원과 도서관이 생긴 것은 긍정적인 영향이다. 그러나 개울이 탁해지고 쓰레기가 늘어난 환경 문제가 생겼다. 주민은 분리배출을 잘하고 다회용기를 쓰며, 공장은 폐수를 깨끗하게 처리하는 시설을 갖추고, 정부는 오염 물질을 내보내는 기업에 벌금을 물리는 제도를 만들면 좋겠다.","scoring_points":["긍정적인 영향을 썼는가","문제를 썼는가","주민·기업·정부의 노력을 각각 썼는가"]},"explanation":["좋은 점과 문제를 함께 봐요.","문제는 환경이에요.","모두 함께 노력해요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_c#25','soc',6,2,'u2','','g6_2_soc_u2_review_c','unit_review','SO6-2-u2-C3',4,'essay','teacher','솔빛 신문 ③을 보고 근로자들이 누린 권리를 쓰고, 근로자의 권리를 법과 제도로 보호해야 하는 까닭을 근로자와 기업의 관계를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C3","difficulty":4,"kind":"essay","stem":"솔빛 신문 ③을 보고 근로자들이 누린 권리를 쓰고, 근로자의 권리를 법과 제도로 보호해야 하는 까닭을 근로자와 기업의 관계를 들어 쓰세요.","answer_guide":{"answer":"예: 근로자들은 근로자 단체를 통해 공장과 근로 조건을 협의하는 권리를 누렸다. 근로자가 기업에 제공하는 노동력은 경제활동에서 중요한 역할을 하고, 근로자와 기업은 서로 의존하는 관계이다. 그런데 근로자 한 사람의 목소리는 기업보다 작으므로 법과 제도가 권리를 보장해야 근로자와 기업이 대등하게 협의할 수 있다.","scoring_points":["협의(단체) 권리를 썼는가","근로자와 기업이 서로 의존함을 썼는가","법과 제도가 필요한 까닭을 썼는가"]},"explanation":["단체를 통해 협의했어요.","근로자와 기업은 서로 의존해요.","법이 대등한 협의를 받쳐 줘요."],"asset":{"type":"passage","lines":["빵 공장 근로자들이 근로자 단체를 통해 쉬는 시간을 늘려 달라고 했다.","공장과 근로자가 마주 앉아 이야기한 끝에 휴게실을 넓히기로 했다.","근로자들은 더 즐겁게 일하게 되었다고 말했다."],"title":"솔빛 신문 ③ 휴게실"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#1','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C1',1,'ox','auto','기업이 물건을 팔아 얻은 수입에서 비용을 뺀 금액을 이윤이라고 해요.',ARRAY['SO6-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO6-2-u2-C1","difficulty":1,"kind":"ox","stem":"기업이 물건을 팔아 얻은 수입에서 비용을 뺀 금액을 이윤이라고 해요.","answer":"O","reason_options":[{"t":"이윤은 판매 수입에서 생산 비용을 뺀 금액이기 때문에","correct":true},{"t":"이윤은 가계가 일하고 받는 급여이기 때문에","mis":"SO6-2-u2-X03"}],"mis":"SO6-2-u2-X03","explanation":["수입 − 비용 = 이윤이에요.","기업은 이윤을 목적으로 해요.","급여는 가계의 소득이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#2','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C2',1,'mc','auto','기준을 정해 비교하며 적은 비용으로 가장 큰 만족을 얻으려는 선택을 무엇이라고 하나요?',ARRAY['SO6-2-u2-X05']::text[],false,'{"seq":2,"concept":"SO6-2-u2-C2","difficulty":1,"kind":"mc","stem":"기준을 정해 비교하며 적은 비용으로 가장 큰 만족을 얻으려는 선택을 무엇이라고 하나요?","options":[{"t":"합리적 선택","correct":true},{"t":"과소비","mis":"SO6-2-u2-X05"},{"t":"담합","mis":"SO6-2-u2-X05"},{"t":"공유지의 비극","mis":"SO6-2-u2-X05"}],"explanation":["기준을 정해 비교해요.","소득 안에서 골라요.","이것이 합리적 선택이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#3','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C3',1,'sa','auto','근로자가 기업에 제공하는, 일하는 힘을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-2-u2-C3","difficulty":1,"kind":"sa","stem":"근로자가 기업에 제공하는, 일하는 힘을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["노동력"],"explanation":["일하는 힘이에요.","근로자는 노동력을 제공해요.","기업은 급여를 줘요."],"mis":"SO6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#4','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C4',1,'mc','auto','공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통하는 것은 어떤 가치에 드나요?',ARRAY['SO6-2-u2-X09']::text[],false,'{"seq":4,"concept":"SO6-2-u2-C4","difficulty":1,"kind":"mc","stem":"공정하게 경쟁하고 윤리적으로 운영하며 근로자와 소통하는 것은 어떤 가치에 드나요?","options":[{"t":"투명 경영","correct":true},{"t":"환경","mis":"SO6-2-u2-X09"},{"t":"사회","mis":"SO6-2-u2-X09"},{"t":"관세","mis":"SO6-2-u2-X09"}],"explanation":["공정·윤리·소통은 투명 경영이에요.","에너지·폐기물은 환경이에요.","인권·지역은 사회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#5','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C5',1,'mc','auto','6·25 전쟁 뒤 우리나라의 처지로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO6-2-u2-C5","difficulty":1,"kind":"mc","stem":"6·25 전쟁 뒤 우리나라의 처지로 알맞은 것은 어느 것인가요?","options":[{"t":"산업 시설이 폐허가 되고 자본과 자원이 거의 없었다","correct":true},{"t":"자원과 자본이 넉넉했다","mis":"SO6-2-u2-X11"},{"t":"반도체를 세계에서 가장 많이 팔았다","mis":"SO6-2-u2-X11"},{"t":"이미 경제 규모가 매우 컸다","mis":"SO6-2-u2-X11"}],"explanation":["전쟁으로 시설이 무너졌어요.","자본·자원이 거의 없었어요.","그 뒤 빠르게 성장했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#6','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C6',1,'mc','auto','게임·영화·방송·음악·만화·캐릭터 등을 묶어 부르는 산업은 무엇인가요?',ARRAY['SO6-2-u2-X13']::text[],false,'{"seq":6,"concept":"SO6-2-u2-C6","difficulty":1,"kind":"mc","stem":"게임·영화·방송·음악·만화·캐릭터 등을 묶어 부르는 산업은 무엇인가요?","options":[{"t":"콘텐츠 산업","correct":true},{"t":"중화학 공업","mis":"SO6-2-u2-X13"},{"t":"농업","mis":"SO6-2-u2-X13"},{"t":"광업","mis":"SO6-2-u2-X13"}],"explanation":["이야기와 즐길 거리를 만드는 산업이에요.","문화 산업의 한 갈래예요.","세계로 수출돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#7','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C9',1,'mc','auto','우리 떡볶이를 다른 나라에 파는 것은 무엇인가요?',ARRAY['SO6-2-u2-X17','SO6-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO6-2-u2-C9","difficulty":1,"kind":"mc","stem":"우리 떡볶이를 다른 나라에 파는 것은 무엇인가요?","options":[{"t":"수출","correct":true},{"t":"수입","mis":"SO6-2-u2-X17"},{"t":"소비","mis":"SO6-2-u2-X17"},{"t":"관세","mis":"SO6-2-u2-X20"}],"explanation":["다른 나라에 팔았어요.","파는 것은 수출이에요.","음식도 수출해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#8','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',1,'sa','auto','수입품에 높은 세금을 매기는 것처럼 국내 산업을 지키려고 수입하는 양을 줄이는 것을 「수입 ○○」이라고 해요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-2-u2-C11","difficulty":1,"kind":"sa","stem":"수입품에 높은 세금을 매기는 것처럼 국내 산업을 지키려고 수입하는 양을 줄이는 것을 「수입 ○○」이라고 해요. ○○에 들어갈 두 글자를 쓰세요.","answer":["제한"],"explanation":["수입을 막거나 줄여요.","관세와 함께 국내 산업을 보호해요.","상대 나라와의 관계도 생각해야 해요."],"mis":"SO6-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#9','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C1',2,'mc','auto','솔빛 신문 ①에서 딸기를 사려는 사람이 갑자기 두 배로 늘어난다면 가격에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-2-u2-C1","difficulty":2,"kind":"mc","stem":"솔빛 신문 ①에서 딸기를 사려는 사람이 갑자기 두 배로 늘어난다면 가격에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"나온 딸기도 많으므로 두 양을 견주어 봐야 가격이 어떻게 될지 알 수 있다","correct":true},{"t":"사려는 사람이 늘었으니 무조건 비싸진다","mis":"SO6-2-u2-X02"},{"t":"나온 딸기가 많으니 무조건 싸진다","mis":"SO6-2-u2-X02"},{"t":"사려는 사람 수와 가격은 관계가 없다","mis":"SO6-2-u2-X02"}],"explanation":["두 쪽이 모두 늘었어요.","어느 쪽이 더 늘었는지 견줘요.","한쪽만 보면 틀리기 쉬워요."],"asset":{"type":"passage","lines":["올해 마을에 딸기 농장이 늘어 시장에 딸기가 아주 많이 나왔다.","딸기를 사려는 사람은 지난해와 비슷하다.","딸기 가게들은 손님을 끌려고 더 달고 싱싱한 딸기를 내놓는다."],"title":"솔빛 신문 ① 딸기 시장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#10','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C2',2,'mc','auto','솔빛 신문 ②의 빵 공장이 문을 닫는다면 마을에 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X04']::text[],false,'{"seq":10,"concept":"SO6-2-u2-C2","difficulty":2,"kind":"mc","stem":"솔빛 신문 ②의 빵 공장이 문을 닫는다면 마을에 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주민 소득이 줄어 가게 손님도 줄어든다","correct":true},{"t":"가게 손님이 더 늘어난다","mis":"SO6-2-u2-X04"},{"t":"주민 소득은 그대로다","mis":"SO6-2-u2-X04"},{"t":"아무 일도 생기지 않는다","mis":"SO6-2-u2-X04"}],"explanation":["공장은 일자리를 줬어요.","문을 닫으면 소득이 끊겨요.","가게도 어려워져요."],"asset":{"type":"passage","lines":["마을 빵 공장이 일손을 열 명 더 뽑았다.","일자리를 얻은 주민들은 받은 급여로 마을 가게에서 장을 본다.","가게 주인들은 손님이 늘었다며 반긴다."],"title":"솔빛 신문 ② 빵 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#11','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C4',2,'mc','auto','솔빛 신문 ④ 음료 회사의 모습을 가장 잘 나타낸 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X02']::text[],false,'{"seq":11,"concept":"SO6-2-u2-C4","difficulty":2,"kind":"mc","stem":"솔빛 신문 ④ 음료 회사의 모습을 가장 잘 나타낸 것은 어느 것인가요?","options":[{"t":"자유롭게 이윤을 얻으면서 사회적 책임도 다하는 기업","correct":true},{"t":"이윤만 좇는 기업","mis":"SO6-2-u2-X08"},{"t":"다른 회사와 몰래 가격을 정하는 기업","mis":"SO6-2-u2-X08"},{"t":"나라가 시키는 것만 하는 기업","mis":"SO6-2-u2-X02"}],"explanation":["음료를 팔아 이윤을 얻어요.","환경·사회·투명 경영도 챙겨요.","자유와 책임을 함께 가졌어요."],"asset":{"type":"passage","lines":["마을 음료 회사가 플라스틱병 대신 다시 쓰는 유리병으로 바꾸었다.","마을 아이들을 위한 무료 과학 교실도 열었다.","회사는 해마다 경영 내용을 주민에게 공개한다."],"title":"솔빛 신문 ④ 음료 회사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#12','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C5',2,'mc','auto','오늘날 우리나라의 경제성장을 이끄는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X11','SO6-2-u2-X19']::text[],false,'{"seq":12,"concept":"SO6-2-u2-C5","difficulty":2,"kind":"mc","stem":"오늘날 우리나라의 경제성장을 이끄는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"반도체·자동차 같은 첨단 산업과 음악·게임·웹툰 같은 문화 콘텐츠","correct":true},{"t":"가발과 신발 같은 경공업만","mis":"SO6-2-u2-X11"},{"t":"쌀 수출만","mis":"SO6-2-u2-X19"},{"t":"원유 수출","mis":"SO6-2-u2-X19"}],"explanation":["첨단 산업의 경쟁력이 강해졌어요.","문화 콘텐츠도 세계로 나가요.","경공업은 1960년대의 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#13','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C6',2,'mc','auto','솔빛 신문 ⑤에서 큰 병원이 생긴 것은 어느 갈래의 변화인가요?',ARRAY['SO6-2-u2-X13','SO6-2-u2-X14']::text[],false,'{"seq":13,"concept":"SO6-2-u2-C6","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑤에서 큰 병원이 생긴 것은 어느 갈래의 변화인가요?","options":[{"t":"의료","correct":true},{"t":"문화 산업","mis":"SO6-2-u2-X13"},{"t":"첨단 기술","mis":"SO6-2-u2-X13"},{"t":"노사 갈등","mis":"SO6-2-u2-X14"}],"explanation":["병원은 의료예요.","수준 높은 의료 혜택이에요.","기대 수명이 늘 수 있어요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#14','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',2,'sa','auto','솔빛 신문 ⑥처럼 함께 쓰는 자원을 자기 이익만 생각하며 써서 모두가 피해를 보는 현상을 「○○○의 비극」이라고 해요. ○○○을 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SO6-2-u2-C8","difficulty":2,"kind":"sa","stem":"솔빛 신문 ⑥처럼 함께 쓰는 자원을 자기 이익만 생각하며 써서 모두가 피해를 보는 현상을 「○○○의 비극」이라고 해요. ○○○을 쓰세요.","answer":["공유지"],"explanation":["공유지는 함께 쓰는 땅이에요.","약수터도 함께 쓰는 자원이에요.","나만 생각하면 모두 피해를 봐요."],"asset":{"type":"passage","lines":["마을 사람들이 함께 쓰는 뒷산 약수터가 있다.","몇몇이 큰 통으로 물을 마구 받아 가 약수가 말라 간다.","마을 회의에서 한 사람이 하루 두 병만 받기로 정했다."],"title":"솔빛 신문 ⑥ 약수터"},"mis":"SO6-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#15','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C9',2,'mc','auto','솔빛 신문 ⑦에서 마을 김이 이웃 나라에서 잘 팔리는 까닭과 가장 가까운 것은 어느 것인가요?',ARRAY['SO6-2-u2-X18','SO6-2-u2-X20','SO6-2-u2-X17']::text[],false,'{"seq":15,"concept":"SO6-2-u2-C9","difficulty":2,"kind":"mc","stem":"솔빛 신문 ⑦에서 마을 김이 이웃 나라에서 잘 팔리는 까닭과 가장 가까운 것은 어느 것인가요?","options":[{"t":"깨끗한 바다라는 자연환경과 김 기르는 기술이 있어 잘 만들 수 있기 때문에","correct":true},{"t":"이웃 나라에서도 똑같은 김을 쉽게 만들기 때문에","mis":"SO6-2-u2-X18"},{"t":"김에는 관세가 붙기 때문에","mis":"SO6-2-u2-X20"},{"t":"김 공장이 기계를 수입하지 않기 때문에","mis":"SO6-2-u2-X17"}],"explanation":["자연환경과 기술이 좋아요.","잘 만드는 것을 수출해요.","무역이 이루어지는 까닭이에요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#16','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',2,'mc','auto','타이·베트남이 쌀을 많이 수출하는 조건으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":16,"concept":"SO6-2-u2-C10","difficulty":2,"kind":"mc","stem":"타이·베트남이 쌀을 많이 수출하는 조건으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓은 땅과 쌀 재배에 알맞은 기후","correct":true},{"t":"로봇 기술","mis":"SO6-2-u2-X19"},{"t":"항로 길목의 큰 항구","mis":"SO6-2-u2-X19"},{"t":"풍부한 천연가스","mis":"SO6-2-u2-X19"}],"explanation":["쌀은 넓은 땅이 필요해요.","알맞은 기후도 필요해요.","농산물을 수출해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#17','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C4',3,'mc','auto','기업의 자유가 가져오는 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-2-u2-X08','SO6-2-u2-X09']::text[],false,'{"seq":17,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"mc","stem":"기업의 자유가 가져오는 영향을 두 쪽 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"새 제품과 일자리가 늘어 경제가 발전하지만, 지나친 경쟁으로 담합·오염 같은 문제가 생길 수 있다","correct":true},{"t":"자유가 있으면 문제는 생기지 않는다","mis":"SO6-2-u2-X08"},{"t":"자유는 경제에 아무 도움이 되지 않는다","mis":"SO6-2-u2-X08"},{"t":"자유가 있으면 정부는 할 일이 없다","mis":"SO6-2-u2-X09"}],"explanation":["자유는 성장의 힘이에요.","지나치면 문제가 생겨요.","책임과 바로잡기가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#18','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C4',3,'ox','auto','기업이 사회적 책임을 다해야 하는 것도 기업과 사회가 서로 영향을 주고받기 때문이에요.',ARRAY['SO6-2-u2-X07']::text[],false,'{"seq":18,"concept":"SO6-2-u2-C4","difficulty":3,"kind":"ox","stem":"기업이 사회적 책임을 다해야 하는 것도 기업과 사회가 서로 영향을 주고받기 때문이에요.","answer":"O","reason_options":[{"t":"기업의 활동이 사회에 큰 영향을 주고, 사회의 믿음이 기업의 성장에도 이어지기 때문에","correct":true},{"t":"기업과 사회는 서로 아무 영향도 주지 않기 때문에","mis":"SO6-2-u2-X07"}],"mis":"SO6-2-u2-X07","explanation":["기업은 사회 안에 있어요.","사회에 영향을 줘요.","사회의 믿음이 기업을 키워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#19','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C10',3,'error','auto','우리나라 무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-2-u2-X19']::text[],false,'{"seq":19,"concept":"SO6-2-u2-C10","difficulty":3,"kind":"error","stem":"우리나라 무역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「우리나라는 원유를 캐서 다른 나라에 많이 팔아.」","correct":true,"mis_target":"SO6-2-u2-X19"},{"t":"보민 — 「우리나라는 원유를 사 와서 석유 제품을 만들어 팔아.」","mis":"SO6-2-u2-X19"},{"t":"하민 — 「반도체는 우리나라의 주요 수출품이야.」","mis":"SO6-2-u2-X19"}],"explanation":["우리나라는 원유를 수입해요.","석유 제품은 수출해요.","원유와 석유 제품은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#20','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',3,'mc','auto','빠른 경제성장으로 생긴 문제를 해결하려는 정부의 노력으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X15']::text[],false,'{"seq":20,"concept":"SO6-2-u2-C8","difficulty":3,"kind":"mc","stem":"빠른 경제성장으로 생긴 문제를 해결하려는 정부의 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"더 나은 일자리를 위한 제도와 정책을 만든다","correct":true},{"t":"문제를 개인에게만 맡긴다","mis":"SO6-2-u2-X15"},{"t":"기업과 근로자 사이의 일에 나서지 않는다","mis":"SO6-2-u2-X15"},{"t":"쓰레기를 더 많이 버리게 한다","mis":"SO6-2-u2-X15"}],"explanation":["정부는 제도와 정책을 만들어요.","기업·근로자는 소통해요.","시민도 함께 노력해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#21','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C11',3,'mc','auto','여러 나라가 다른 나라의 큰 시설 공사를 따내려고 경쟁하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X20']::text[],false,'{"seq":21,"concept":"SO6-2-u2-C11","difficulty":3,"kind":"mc","stem":"여러 나라가 다른 나라의 큰 시설 공사를 따내려고 경쟁하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰 이익을 얻고 뛰어난 기술을 세계에 알릴 수 있기 때문에","correct":true},{"t":"공사를 하면 손해만 보기 때문에","mis":"SO6-2-u2-X20"},{"t":"다른 나라와 의존하지 않으려고","mis":"SO6-2-u2-X20"},{"t":"관세를 내지 않으려고","mis":"SO6-2-u2-X20"}],"explanation":["시설 공사는 큰 이익이에요.","기술도 알릴 수 있어요.","그래서 서로 경쟁해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#22','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C12',3,'mc','auto','수출하고 싶은 나라를 고를 때 가장 먼저 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-2-u2-X21']::text[],false,'{"seq":22,"concept":"SO6-2-u2-C12","difficulty":3,"kind":"mc","stem":"수출하고 싶은 나라를 고를 때 가장 먼저 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"그 나라의 특징과 현황을 조사한다","correct":true},{"t":"이름이 마음에 드는 나라를 고른다","mis":"SO6-2-u2-X21"},{"t":"가장 먼 나라를 고른다","mis":"SO6-2-u2-X21"},{"t":"우리 상품이 필요 없는 나라를 고른다","mis":"SO6-2-u2-X21"}],"explanation":["상품이 필요할 나라를 찾아요.","조사한 내용이 근거예요.","고른 까닭을 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#23','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C7',4,'mc','auto','솔빛 신문 ⑤의 마을과 ⑥의 약수터를 함께 볼 때 마을이 지속적으로 발전하려면 무엇이 필요할까요?',ARRAY['SO6-2-u2-X12','SO6-2-u2-X16']::text[],false,'{"seq":23,"concept":"SO6-2-u2-C7","difficulty":4,"kind":"mc","stem":"솔빛 신문 ⑤의 마을과 ⑥의 약수터를 함께 볼 때 마을이 지속적으로 발전하려면 무엇이 필요할까요?","options":[{"t":"성장으로 얻은 것은 살리되 함께 쓰는 자원과 환경을 지키는 규칙과 태도를 갖춘다","correct":true},{"t":"개발을 멈추고 병원과 도서관을 없앤다","mis":"SO6-2-u2-X12"},{"t":"쓰레기와 오염은 그냥 둔다","mis":"SO6-2-u2-X12"},{"t":"약수를 먼저 받는 사람이 다 가져간다","mis":"SO6-2-u2-X16"}],"explanation":["성장의 열매를 지켜요.","자원과 환경도 지켜요.","규칙과 태도가 함께 필요해요."],"asset":{"type":"passage","lines":["30년 전 논밭뿐이던 마을에 공장과 아파트가 들어섰다.","주민 소득이 늘고 큰 병원과 도서관도 생겼다.","그런데 마을 개울이 탁해지고 쓰레기가 크게 늘었다."],"title":"솔빛 신문 ⑤ 달라진 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#24','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C8',4,'essay','teacher','솔빛 신문 ⑥의 약수터 이야기에 담긴 현상의 이름을 쓰고, 마을 회의의 규칙만으로 충분한지 자기 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-2-u2-C8","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑥의 약수터 이야기에 담긴 현상의 이름을 쓰고, 마을 회의의 규칙만으로 충분한지 자기 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 함께 쓰는 자원을 몇몇이 자기 이익만 생각하며 써서 모두가 피해를 보는 공유지의 비극이다. 하루 두 병이라는 규칙은 꼭 필요하지만 그것만으로는 충분하지 않다. 사람들이 규칙을 몰래 어기면 약수는 다시 마를 것이므로, 약수가 모두의 것이라는 생각으로 공동의 이익을 지키려는 태도가 함께 있어야 한다.","scoring_points":["공유지의 비극이라고 썼는가","규칙의 필요성을 썼는가","규칙과 함께 태도가 필요하다는 생각을 까닭과 썼는가"]},"explanation":["함께 쓰는 자원이에요.","규칙은 울타리예요.","지키려는 마음이 함께 필요해요."],"asset":{"type":"passage","lines":["마을 사람들이 함께 쓰는 뒷산 약수터가 있다.","몇몇이 큰 통으로 물을 마구 받아 가 약수가 말라 간다.","마을 회의에서 한 사람이 하루 두 병만 받기로 정했다."],"title":"솔빛 신문 ⑥ 약수터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_soc_u2_review_d#25','soc',6,2,'u2','','g6_2_soc_u2_review_d','unit_review','SO6-2-u2-C12',4,'essay','teacher','솔빛 신문 ⑦의 김 공장 대표가 되었다고 생각하고 기업 운영 계획을 세워 보세요. 대표 상품, 주요 수출국과 고른 까닭, 사회적 책임 목표, 근로자를 위한 노력을 차례로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-2-u2-C12","difficulty":4,"kind":"essay","stem":"솔빛 신문 ⑦의 김 공장 대표가 되었다고 생각하고 기업 운영 계획을 세워 보세요. 대표 상품, 주요 수출국과 고른 까닭, 사회적 책임 목표, 근로자를 위한 노력을 차례로 쓰세요.","answer_guide":{"answer":"예: 대표 상품은 깨끗한 바다에서 기른 바삭한 구운 김이다. 김밥과 한국 음식을 즐기는 사람이 늘고 있는 나라를 조사해 그 나라를 주요 수출국으로 고르겠다. 목표는 「바다를 깨끗하게 지키며 매년 성장하는 김 공장」으로, 김을 기르는 바다의 쓰레기를 치우겠다. 근로자에게는 휴가를 보장하고 매주 대화의 시간을 가지겠다.","scoring_points":["대표 상품을 정했는가","수출국과 고른 까닭을 썼는가","사회적 책임 목표와 근로자를 위한 노력을 썼는가"]},"explanation":["상품 → 수출국 → 목표 → 노력이에요.","수출국은 조사해 골라요.","책임과 근로자를 함께 담아요."],"asset":{"type":"passage","lines":["마을 김 공장은 김을 이웃 나라들에 판다.","김을 굽는 기계는 다른 나라에서 사 왔다.","바다가 깨끗하고 김 기르는 기술이 좋아 맛있다고 소문났다."],"title":"솔빛 신문 ⑦ 김 공장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
